# ============================================================
# 4. LOAD RAW CSV
# ============================================================

def load_csv(file_key):

    """
    Load one raw CSV.

    Pipeline 01 does NOT clean or impute data.
    It only loads, standardizes technical datatypes
    and preserves the original business values.
    """

    path = DATA_DIR / FILES[file_key]

    if not path.exists():
        raise FileNotFoundError(
            f"Required dataset not found: {path}"
        )

    df = pd.read_csv(
        path,
        low_memory=False
    )

    # Preserve identifiers as text
    identifier_columns = [
        "employee_id",
        "claim_event_id",
        "plan_id",
        "product_plan_id",
        "rule_id",
    ]

    for column in identifier_columns:

        if column in df.columns:
            df[column] = df[column].astype("string")

    # Convert recognised dates
    for column in DATE_COLUMNS[file_key]:

        if column in df.columns:

            df[column] = pd.to_datetime(
                df[column],
                errors="coerce"
            )

    return df


# ============================================================
# 5. SCHEMA VALIDATION
# ============================================================

def validate_schema(name, df):

    expected = EXPECTED_COLUMNS[name]
    actual = list(df.columns)

    missing_columns = [
        column
        for column in expected
        if column not in actual
    ]

    extra_columns = [
        column
        for column in actual
        if column not in expected
    ]

    column_order_match = actual == expected

    return {

        "dataset": name,

        "rows": len(df),

        "columns": len(df.columns),

        "expected_columns": len(expected),

        "schema_match":
            not missing_columns
            and not extra_columns
            and column_order_match,

        "missing_columns":
            ", ".join(missing_columns),

        "extra_columns":
            ", ".join(extra_columns),

        "column_order_match":
            column_order_match,
    }


# ============================================================
# 6. MISSING-VALUE PROFILE
# ============================================================

def build_missing_summary(name, df):

    """
    Report missing values.

    Missing data are NOT fixed here.
    Cleaning and imputation belong to a later pipeline.
    """

    report = pd.DataFrame({

        "column": df.columns,

        "missing_count": [
            df[column].isna().sum()
            for column in df.columns
        ],

        "missing_pct": [
            df[column].isna().mean() * 100
            for column in df.columns
        ],
    })

    report.insert(
        0,
        "dataset",
        name
    )

    return report.sort_values(
        ["missing_count", "column"],
        ascending=[False, True]
    )


# ============================================================
# 7. REFERENTIAL INTEGRITY
# ============================================================

def validate_referential_integrity(
    employee,
    salary,
    claims
):

    master_employee_ids = set(
        employee["employee_id"].dropna()
    )

    salary_orphans = salary.loc[
        ~salary["employee_id"].isin(
            master_employee_ids
        ),
        "employee_id"
    ].dropna().unique()

    claims_orphans = claims.loc[
        ~claims["employee_id"].isin(
            master_employee_ids
        ),
        "employee_id"
    ].dropna().unique()

    return pd.DataFrame([

        {
            "check":
                "salary employee_id exists in employee master",

            "exceptions":
                len(salary_orphans),
        },

        {
            "check":
                "claims employee_id exists in employee master",

            "exceptions":
                len(claims_orphans),
        },

    ])


# ============================================================
# 8. PLAN-ASSET RECONCILIATION
# ============================================================

def validate_plan_assets(assets):

    """
    Book logic:

    Closing Assets
    =
    Opening Assets
    + Employer Contributions
    + Employee Contributions
    + Investment Income
    - Benefits Paid
    - Expenses / Charges
    """

    result = assets.copy()

    result["calculated_closing_plan_assets"] = (

        result["opening_plan_assets"]

        + result["employer_contributions"]

        + result["employee_contributions"]

        + result["investment_income"]

        - result["benefits_paid"]

        - result["expenses_charges"]
    )

    result["reconciliation_difference"] = (

        result["closing_plan_assets"]

        - result[
            "calculated_closing_plan_assets"
        ]
    )

    result["reconciles"] = (

        result[
            "reconciliation_difference"
        ].abs() < 0.01
    )

    return result


# ============================================================
# 9. PIPELINE 01 CONTROLLER
# ============================================================

def run_pipeline_01():

    print("\n" + "=" * 72)

    print(
        "PIPELINE 01 - "
        "DATA LOADING & STRUCTURAL VALIDATION"
    )

    print(
        f"Valuation date: "
        f"{VALUATION_DATE.date()}"
    )

    print("=" * 72)

    # ------------------------------------------
    # LOAD ALL FIVE DATASETS
    # ------------------------------------------

    data = {

        name: load_csv(name)

        for name in FILES
    }


    # ------------------------------------------
    # SCHEMA VALIDATION
    # ------------------------------------------

    schema_report = pd.DataFrame([

        validate_schema(name, df)

        for name, df in data.items()
    ])

    schema_report.to_csv(

        OUTPUT_DIR / "schema_report.csv",

        index=False
    )


    # ------------------------------------------
    # MISSING VALUES
    # ------------------------------------------

    missing_report = pd.concat([

        build_missing_summary(
            name,
            df
        )

        for name, df in data.items()

    ], ignore_index=True)

    missing_report.to_csv(

        OUTPUT_DIR /
        "missing_values_report.csv",

        index=False
    )


    # ------------------------------------------
    # DUPLICATE EMPLOYEE IDs
    # ------------------------------------------

    duplicate_rows = data["employee"].loc[

        data["employee"].duplicated(
            "employee_id",
            keep=False
        )

    ].sort_values(
        "employee_id"
    )

    duplicate_rows.to_csv(

        OUTPUT_DIR /
        "duplicate_employee_ids.csv",

        index=False
    )


    # ------------------------------------------
    # CROSS-FILE KEY VALIDATION
    # ------------------------------------------

    referential_report = (
        validate_referential_integrity(

            data["employee"],

            data["salary"],

            data["claims"]
        )
    )

    referential_report.to_csv(

        OUTPUT_DIR /
        "referential_integrity_report.csv",

        index=False
    )


    # ------------------------------------------
    # PLAN-ASSET RECONCILIATION
    # ------------------------------------------

    asset_reconciliation = (
        validate_plan_assets(
            data["assets"]
        )
    )

    asset_reconciliation.to_csv(

        OUTPUT_DIR /
        "plan_assets_reconciliation.csv",

        index=False
    )


    # ========================================================
    # TERMINAL SUMMARY
    # ========================================================

    print("\nDataset dimensions")

    for name, df in data.items():

        print(
            f"  {FILES[name]:35s} "
            f"{len(df):>7,} rows x "
            f"{df.shape[1]:>2} columns"
        )


    print("\nEmployee master")

    print(
        f"  Raw rows:                 "
        f"{len(data['employee']):,}"
    )

    print(
        f"  Unique employee IDs:      "
        f"{data['employee']['employee_id'].nunique(dropna=True):,}"
    )

    print(
        f"  Duplicate-ID rows:        "
        f"{len(duplicate_rows):,}"
    )


    print("\nSchema status")

    for row in schema_report.itertuples():

        status = (
            "PASS"
            if row.schema_match
            else "REVIEW"
        )

        print(
            f"  {row.dataset:10s}: "
            f"{status}"
        )


    asset_failures = (
        ~asset_reconciliation[
            "reconciles"
        ]
    ).sum()

    print(
        "\nPlan asset reconciliation"
    )

    print(
        f"  Non-reconciling rows:     "
        f"{asset_failures}"
    )


    print(
        f"\nReports written to:\n"
        f"{OUTPUT_DIR}"
    )

    print(
        "\nPipeline 01 complete."
        "\nNo raw values were cleaned "
        "or imputed.\n"
    )


    return data

