# -----------------------------------------------------------------------------
# QUALITY-ASSURANCE THRESHOLDS
# -----------------------------------------------------------------------------
#
# These thresholds are NOT actuarial assumptions and they are NOT statutory
# rules.
#
# They are diagnostic review thresholds only.
#
# Their purpose is to tell us:
#
# "This observation looks unusual enough that we should inspect it."
#
# Pipeline 02 never automatically deletes a record because one of these
# thresholds is breached.
# -----------------------------------------------------------------------------


# Treat joining below age 18 as unusual and worthy of review.
# This is a project QA threshold, not a statutory eligibility rule.
QA_MIN_JOINING_AGE = 18.0


# Treat joining above age 70 as unusual and worthy of review.
QA_MAX_JOINING_AGE = 70.0


# An attained age greater than 100 would be treated as implausible
# for this synthetic employee-benefit population.
QA_MAX_ATTAINED_AGE = 100.0


# Allow a small quarter-year tolerance before flagging an active employee
# whose attained age exceeds the recorded retirement age.
QA_RETIREMENT_TOLERANCE_YEARS = 0.25


# Use three interquartile ranges rather than the more aggressive 1.5 IQR
# rule because we only want to identify extreme salary observations.
QA_EXTREME_IQR_MULTIPLIER = 3.0


# Flag a historical salary increase larger than 50% for investigation.
# A promotion may make such a movement genuine, so this is not an automatic error.
QA_LARGE_SALARY_INCREASE = 0.50


# Flag a historical salary decrease larger than 30% for investigation.
QA_LARGE_SALARY_DECREASE = -0.30


# When comparing the current census salary with the most recent salary-history
# observation, ratios below 0.70 are treated as materially unusual.
QA_HISTORY_RATIO_LOW = 0.70


# Ratios above 1.50 are also treated as materially unusual.
QA_HISTORY_RATIO_HIGH = 1.50


# =============================================================================
# SECTION 13 — CATEGORICAL DISTRIBUTION FUNCTION
# =============================================================================


# Define a reusable function that summarizes categorical variables.
def build_categorical_summary(dataset_name, df, columns):


    # Create an empty list that will temporarily hold one summary
    # DataFrame for every categorical column.
    reports = []


    # Loop through each categorical field requested by the caller.
    for column in columns:


        # Skip the requested field if it does not exist in the DataFrame.
        if column not in df.columns:
            continue


        # Convert the field to pandas String datatype.
        # fillna("<MISSING>") makes missing categories visible in the report.
        values = (
            df[column]
            .astype("string")
            .fillna("<MISSING>")
        )


        # Count how many observations occur in every category.
        counts = values.value_counts(
            dropna=False
        )


        # Convert the Series of counts into a normal DataFrame.
        report = (
            counts
            .rename_axis("value")
            .reset_index(name="count")
        )


        # Calculate percentage of the full dataset represented by each category.
        report["pct"] = (
            report["count"]
            / len(df)
            * 100
        )


        # Insert the original variable name as the first descriptive field.
        report.insert(
            0,
            "column",
            column
        )


        # Insert the dataset name before the variable name.
        report.insert(
            0,
            "dataset",
            dataset_name
        )


        # Add this variable's summary to our list.
        reports.append(report)


    # If at least one valid categorical field was found,
    # combine all summaries into one DataFrame.
    if reports:

        return pd.concat(
            reports,
            ignore_index=True
        )


    # If no valid categorical fields were found,
    # return an empty DataFrame with the correct schema.
    return pd.DataFrame(
        columns=[
            "dataset",
            "column",
            "value",
            "count",
            "pct",
        ]
    )


# =============================================================================
# SECTION 14 — NUMERIC DISTRIBUTION FUNCTION
# =============================================================================


# Define a reusable function that summarizes numeric variables.
def build_numeric_summary(dataset_name, df, columns):


    # Keep only requested numeric fields that actually exist.
    existing_columns = [

        column

        for column in columns

        if column in df.columns
    ]


    # If none of the requested numeric fields exists,
    # return an empty DataFrame.
    if not existing_columns:

        return pd.DataFrame()


    # Convert selected fields into numeric values.
    #
    # errors="coerce" means invalid numeric text becomes NaN,
    # which allows us to detect it rather than crashing.
    numeric_data = df[
        existing_columns
    ].apply(
        pd.to_numeric,
        errors="coerce"
    )


    # Generate descriptive statistics.
    #
    # In addition to ordinary quartiles, we request:
    # 1%, 5%, 95% and 99%
    #
    # because tail observations are especially useful during EDA.
    summary = numeric_data.describe(
        percentiles=[
            0.01,
            0.05,
            0.25,
            0.50,
            0.75,
            0.95,
            0.99,
        ]
    ).T


    # Count missing observations for every numeric variable.
    summary["missing_count"] = (
        numeric_data
        .isna()
        .sum()
    )


    # Calculate missing percentage for every numeric variable.
    summary["missing_pct"] = (
        numeric_data
        .isna()
        .mean()
        * 100
    )


    # Convert the numeric variable names from index into a normal column.
    summary = (
        summary
        .reset_index()
        .rename(
            columns={
                "index": "column"
            }
        )
    )


    # Insert dataset name as the first field.
    summary.insert(
        0,
        "dataset",
        dataset_name
    )


    # Return the completed descriptive-statistics report.
    return summary


# =============================================================================
# SECTION 15 — DUPLICATE EMPLOYEE IDENTITY ANALYSIS
# =============================================================================


# Define a function that distinguishes exact duplicates
# from conflicting duplicate employee records.
def build_duplicate_identity_profile(employee):


    # Select employee IDs that appear more than once.
    duplicate_ids = employee.loc[

        employee.duplicated(
            "employee_id",
            keep=False
        ),

        "employee_id"

    ].dropna().unique()


    # Create an empty list for one result per duplicated employee ID.
    records = []


    # Build a list of every employee field except the ID itself.
    compare_columns = [

        column

        for column in employee.columns

        if column != "employee_id"
    ]


    # Examine each duplicated employee separately.
    for employee_id in duplicate_ids:


        # Retrieve all rows belonging to this employee ID.
        employee_group = employee.loc[
            employee["employee_id"] == employee_id
        ]


        # Find fields where duplicate records contain different values.
        #
        # dropna=False is important because:
        #
        # value versus missing value
        #
        # should also be treated as a difference.
        differing_columns = [

            column

            for column in compare_columns

            if employee_group[
                column
            ].nunique(
                dropna=False
            ) > 1
        ]


        # Store the duplicate classification.
        records.append({

            # Employee being investigated.
            "employee_id":
                employee_id,

            # Number of rows sharing the ID.
            "row_count":
                len(employee_group),

            # If no field differs, this is an exact duplicate.
            # Otherwise it is a conflicting duplicate.
            "duplicate_type":
                (
                    "Exact"
                    if not differing_columns
                    else "Conflicting"
                ),

            # Number of fields containing conflicting information.
            "differing_column_count":
                len(differing_columns),

            # Names of fields containing differences.
            "differing_columns":
                ", ".join(
                    differing_columns
                ),
        })


    # Convert the list into a DataFrame.
    profile = pd.DataFrame(records)


    # If duplicate IDs exist, count exact and conflicting duplicates.
    if not profile.empty:

        exact_count = (
            profile[
                "duplicate_type"
            ]
            .eq("Exact")
            .sum()
        )

        conflicting_count = (
            profile[
                "duplicate_type"
            ]
            .eq("Conflicting")
            .sum()
        )


    # If no duplicate IDs exist, both counts are zero.
    else:

        exact_count = 0

        conflicting_count = 0


    # Build a compact issue summary.
    summary = pd.DataFrame({

        "area": [
            "duplicate_identity",
            "duplicate_identity",
            "duplicate_identity",
        ],

        "issue": [
            "duplicate_employee_ids",
            "exact_duplicate_ids",
            "conflicting_duplicate_ids",
        ],

        "count": [
            len(profile),
            int(exact_count),
            int(conflicting_count),
        ],
    })


    # Return both detailed and summarized results.
    return profile, summary


# =============================================================================
# SECTION 16 — EMPLOYEE DATE, AGE, SERVICE AND STATUS DIAGNOSTICS
# =============================================================================


# Define a function that investigates employee chronology.
def build_employee_chronology_diagnostics(employee):


    # Copy the raw employee DataFrame so diagnostic calculations
    # never modify our source object.
    result = employee.copy()


    # For exited employees, diagnostic service ends at exit date.
    #
    # For employees without an exit date, diagnostic service ends
    # at the project valuation date.
    diagnostic_end_date = (
        result["exit_date"]
        .where(
            result["exit_date"].notna(),
            VALUATION_DATE
        )
    )


    # Calculate attained age in approximate years.
    #
    # Formula:
    #
    # Age =
    # (Valuation Date - Date of Birth) / 365.25
    result[
        "diagnostic_attained_age_years"
    ] = (

        (
            VALUATION_DATE
            - result["date_of_birth"]
        ).dt.days

        / 365.25
    )


    # Calculate age when the employee joined the company.
    #
    # Formula:
    #
    # Joining Age =
    # (Date of Joining - Date of Birth) / 365.25
    result[
        "diagnostic_joining_age_years"
    ] = (

        (
            result["date_of_joining"]
            - result["date_of_birth"]
        ).dt.days

        / 365.25
    )


    # Calculate diagnostic completed service.
    #
    # Formula:
    #
    # Service =
    # (Exit Date or Valuation Date - Date of Joining) / 365.25
    result[
        "diagnostic_service_years"
    ] = (

        (
            diagnostic_end_date
            - result["date_of_joining"]
        ).dt.days

        / 365.25
    )


    # Flag missing Date of Birth.
    result[
        "missing_date_of_birth_flag"
    ] = result[
        "date_of_birth"
    ].isna()


    # Flag missing Date of Joining.
    result[
        "missing_date_of_joining_flag"
    ] = result[
        "date_of_joining"
    ].isna()


    # Flag missing retirement age.
    result[
        "missing_retirement_age_flag"
    ] = result[
        "retirement_age"
    ].isna()


    # Flag a spouse who is shown as eligible for survivor benefit
    # but whose spouse date of birth is missing.
    result[
        "spouse_eligible_missing_dob_flag"
    ] = (

        result[
            "spouse_eligible_flag"
        ].eq("Yes")

        & result[
            "spouse_date_of_birth"
        ].isna()
    )


    # Flag DOB occurring after the valuation date.
    result[
        "dob_after_valuation_flag"
    ] = (

        result[
            "date_of_birth"
        ].notna()

        & (
            result[
                "date_of_birth"
            ]
            > VALUATION_DATE
        )
    )


    # Flag DOJ occurring after the valuation date.
    result[
        "doj_after_valuation_flag"
    ] = (

        result[
            "date_of_joining"
        ].notna()

        & (
            result[
                "date_of_joining"
            ]
            > VALUATION_DATE
        )
    )


    # Flag joining date occurring on or before date of birth.
    result[
        "doj_on_or_before_dob_flag"
    ] = (

        result[
            "date_of_birth"
        ].notna()

        & result[
            "date_of_joining"
        ].notna()

        & (
            result[
                "date_of_joining"
            ]
            <= result[
                "date_of_birth"
            ]
        )
    )


    # Flag an exit date occurring before joining date.
    result[
        "exit_before_joining_flag"
    ] = (

        result[
            "exit_date"
        ].notna()

        & result[
            "date_of_joining"
        ].notna()

        & (
            result[
                "exit_date"
            ]
            < result[
                "date_of_joining"
            ]
        )
    )


    # Flag employees marked Active even though an exit date exists.
    result[
        "active_with_exit_date_flag"
    ] = (

        result[
            "employment_status"
        ].eq("Active")

        & result[
            "exit_date"
        ].notna()
    )


    # Flag non-active employees whose exit date is missing.
    result[
        "inactive_without_exit_date_flag"
    ] = (

        ~result[
            "employment_status"
        ].eq("Active")

        & result[
            "exit_date"
        ].isna()
    )


    # Flag Active employees who nevertheless have an exit reason.
    result[
        "active_with_exit_reason_flag"
    ] = (

        result[
            "employment_status"
        ].eq("Active")

        & result[
            "exit_reason"
        ].notna()
    )


    # Flag non-active employees without an exit reason.
    result[
        "inactive_without_exit_reason_flag"
    ] = (

        ~result[
            "employment_status"
        ].eq("Active")

        & result[
            "exit_reason"
        ].isna()
    )


    # Define the expected relationship between employment status
    # and exit reason in our synthetic project.
    expected_reason_map = {

        "Exited":
            "Withdrawal",

        "Retired":
            "Retirement",

        "Early Retired":
            "Early Retirement",

        "Deceased":
            "Death",

        "Disabled":
            "Disability",
    }


    # Convert employment status into its expected exit reason.
    expected_exit_reason = (
        result[
            "employment_status"
        ]
        .map(
            expected_reason_map
        )
    )


    # Flag records where a known non-active status conflicts
    # with the recorded exit reason.
    result[
        "status_exit_reason_mismatch_flag"
    ] = (

        expected_exit_reason.notna()

        & result[
            "exit_reason"
        ].notna()

        & (
            result[
                "exit_reason"
            ]
            != expected_exit_reason
        )
    )


    # Flag a superannuation joining date occurring before
    # the employee's company joining date.
    result[
        "superannuation_join_before_company_join_flag"
    ] = (

        result[
            "superannuation_join_date"
        ].notna()

        & result[
            "date_of_joining"
        ].notna()

        & (
            result[
                "superannuation_join_date"
            ]
            < result[
                "date_of_joining"
            ]
        )
    )


    # Flag a superannuation joining date after valuation date.
    result[
        "superannuation_join_after_valuation_flag"
    ] = (

        result[
            "superannuation_join_date"
        ].notna()

        & (
            result[
                "superannuation_join_date"
            ]
            > VALUATION_DATE
        )
    )


    # Flag an unusually young or unusually old joining age.
    #
    # IMPORTANT:
    # This is a diagnostic threshold only.
    result[
        "unusual_joining_age_flag"
    ] = (

        result[
            "diagnostic_joining_age_years"
        ].notna()

        & (

            (
                result[
                    "diagnostic_joining_age_years"
                ]
                < QA_MIN_JOINING_AGE
            )

            | (
                result[
                    "diagnostic_joining_age_years"
                ]
                > QA_MAX_JOINING_AGE
            )
        )
    )


    # Flag mathematically impossible or highly implausible attained ages.
    result[
        "impossible_attained_age_flag"
    ] = (

        result[
            "diagnostic_attained_age_years"
        ].notna()

        & (

            (
                result[
                    "diagnostic_attained_age_years"
                ]
                < 0
            )

            | (
                result[
                    "diagnostic_attained_age_years"
                ]
                > QA_MAX_ATTAINED_AGE
            )
        )
    )


    # Convert retirement age into numeric form before comparison.
    retirement_age_numeric = pd.to_numeric(

        result[
            "retirement_age"
        ],

        errors="coerce"
    )


    # Flag employees still marked Active materially beyond
    # their recorded retirement age.
    result[
        "active_past_retirement_age_flag"
    ] = (

        result[
            "employment_status"
        ].eq("Active")

        & result[
            "diagnostic_attained_age_years"
        ].notna()

        & retirement_age_numeric.notna()

        & (

            result[
                "diagnostic_attained_age_years"
            ]

            > (
                retirement_age_numeric
                + QA_RETIREMENT_TOLERANCE_YEARS
            )
        )
    )


    # Store the chronology flags in one list.
    chronology_flags = [

        "missing_date_of_birth_flag",

        "missing_date_of_joining_flag",

        "missing_retirement_age_flag",

        "spouse_eligible_missing_dob_flag",

        "dob_after_valuation_flag",

        "doj_after_valuation_flag",

        "doj_on_or_before_dob_flag",

        "exit_before_joining_flag",

        "active_with_exit_date_flag",

        "inactive_without_exit_date_flag",

        "active_with_exit_reason_flag",

        "inactive_without_exit_reason_flag",

        "status_exit_reason_mismatch_flag",

        "superannuation_join_before_company_join_flag",

        "superannuation_join_after_valuation_flag",

        "unusual_joining_age_flag",

        "impossible_attained_age_flag",

        "active_past_retirement_age_flag",
    ]


    # Select descriptive fields that help us understand an exception.
    chronology_columns = [

        "employee_id",

        "date_of_birth",

        "date_of_joining",

        "exit_date",

        "employment_status",

        "exit_reason",

        "retirement_age",

        "spouse_eligible_flag",

        "spouse_date_of_birth",

        "superannuation_join_date",

        "diagnostic_attained_age_years",

        "diagnostic_joining_age_years",

        "diagnostic_service_years",

    ] + chronology_flags


    # Keep only employee rows containing at least one chronology issue.
    details = result.loc[

        result[
            chronology_flags
        ].any(
            axis=1
        ),

        chronology_columns
    ].copy()


    # Count occurrences of every chronology flag.
    summary = pd.DataFrame({

        "area":
            [
                "employee_chronology"
            ]
            * len(
                chronology_flags
            ),

        "issue":
            chronology_flags,

        "count":
            [
                int(
                    result[
                        flag
                    ].sum()
                )

                for flag in chronology_flags
            ],
    })


    # Return:
    # 1. exception rows,
    # 2. summary counts,
    # 3. diagnostic working copy.
    return details, summary, result


# =============================================================================
# SECTION 17 — EMPLOYEE CURRENT-SALARY DIAGNOSTICS
# =============================================================================


# Define a function that investigates current employee salary data.
def build_employee_salary_diagnostics(employee):


    # Work on a copy so raw employee data remain unchanged.
    result = employee.copy()


    # Define salary fields that should normally contain positive values.
    positive_salary_columns = [

        "basic_salary_monthly",

        "eligible_gratuity_wages_monthly",

        "pensionable_salary_annual",

        "gross_compensation_annual",
    ]


    # Flag missing monthly basic salary.
    result[
        "missing_basic_salary_flag"
    ] = result[
        "basic_salary_monthly"
    ].isna()


    # Flag missing gratuity wage basis.
    result[
        "missing_gratuity_wage_flag"
    ] = result[
        "eligible_gratuity_wages_monthly"
    ].isna()


    # Flag missing pensionable salary.
    result[
        "missing_pensionable_salary_flag"
    ] = result[
        "pensionable_salary_annual"
    ].isna()


    # Flag missing gross annual compensation.
    result[
        "missing_gross_compensation_flag"
    ] = result[
        "gross_compensation_annual"
    ].isna()


    # Convert the required salary fields into numeric form.
    positive_salary_values = result[
        positive_salary_columns
    ].apply(
        pd.to_numeric,
        errors="coerce"
    )


    # Flag any required salary basis that is zero or negative.
    result[
        "nonpositive_required_salary_flag"
    ] = (

        positive_salary_values
        <= 0

    ).any(
        axis=1
    )


    # Convert Dearness Allowance to numeric.
    dearness_allowance_numeric = pd.to_numeric(

        result[
            "dearness_allowance_monthly"
        ],

        errors="coerce"
    )


    # Dearness Allowance may legitimately be zero,
    # so only negative DA is treated as an exception.
    result[
        "negative_dearness_allowance_flag"
    ] = (

        dearness_allowance_numeric.notna()

        & (
            dearness_allowance_numeric
            < 0
        )
    )


    # We perform robust extreme-outlier testing on:
    #
    # 1. monthly basic salary
    # 2. annual gross compensation
    #
    # and perform it separately within each employee grade.
    for column in [

        "basic_salary_monthly",

        "gross_compensation_annual",
    ]:


        # Convert current salary variable into numeric form.
        numeric_column = pd.to_numeric(

            result[
                column
            ],

            errors="coerce"
        )


        # Calculate first quartile separately within each grade.
        q1 = numeric_column.groupby(

            result[
                "grade"
            ]

        ).transform(

            lambda series:
                series.quantile(
                    0.25
                )
        )


        # Calculate third quartile separately within each grade.
        q3 = numeric_column.groupby(

            result[
                "grade"
            ]

        ).transform(

            lambda series:
                series.quantile(
                    0.75
                )
        )


        # Calculate interquartile range.
        #
        # IQR = Q3 - Q1
        iqr = q3 - q1


        # Calculate the extreme lower diagnostic threshold.
        lower_bound = (

            q1

            - (
                QA_EXTREME_IQR_MULTIPLIER
                * iqr
            )
        )


        # Calculate the extreme upper diagnostic threshold.
        upper_bound = (

            q3

            + (
                QA_EXTREME_IQR_MULTIPLIER
                * iqr
            )
        )


        # Flag observations outside the extreme grade-specific range.
        result[
            f"{column}_extreme_outlier_flag"
        ] = (

            numeric_column.notna()

            & (

                (
                    numeric_column
                    < lower_bound
                )

                | (
                    numeric_column
                    > upper_bound
                )
            )
        )


    # Store current-salary flags in one list.
    salary_flags = [

        "missing_basic_salary_flag",

        "missing_gratuity_wage_flag",

        "missing_pensionable_salary_flag",

        "missing_gross_compensation_flag",

        "nonpositive_required_salary_flag",

        "negative_dearness_allowance_flag",

        "basic_salary_monthly_extreme_outlier_flag",

        "gross_compensation_annual_extreme_outlier_flag",
    ]


    # Select fields needed to understand salary exceptions.
    salary_columns = [

        "employee_id",

        "grade",

        "basic_salary_monthly",

        "dearness_allowance_monthly",

        "eligible_gratuity_wages_monthly",

        "pensionable_salary_annual",

        "gross_compensation_annual",

    ] + salary_flags


    # Keep employees with at least one salary exception.
    details = result.loc[

        result[
            salary_flags
        ].any(
            axis=1
        ),

        salary_columns
    ].copy()


    # Count each salary diagnostic.
    summary = pd.DataFrame({

        "area":
            [
                "employee_salary"
            ]
            * len(
                salary_flags
            ),

        "issue":
            salary_flags,

        "count":
            [
                int(
                    result[
                        flag
                    ].sum()
                )

                for flag in salary_flags
            ],
    })


    # Return detailed exceptions, summary counts and working copy.
    return details, summary, result


