# Define a helper that converts values into readable text
# before they are stored in the audit CSV.
def cleaning_audit_value(value):


    # Treat Python None as a missing value.
    if value is None:

        return "<MISSING>"


    # Try to determine whether pandas considers the value missing.
    try:


        # Convert NaN, NaT and pd.NA into one readable label.
        if pd.isna(value):

            return "<MISSING>"


    # If the value is a datatype for which pd.isna is unsuitable,
    # simply continue without changing it.
    except Exception:

        pass


    # Format pandas dates consistently as YYYY-MM-DD.
    if isinstance(
        value,
        pd.Timestamp
    ):

        return value.strftime(
            "%Y-%m-%d"
        )


    # Format floating-point values cleanly for the audit report.
    if isinstance(
        value,
        (
            float,
            np.floating,
        )
    ):

        return (
            f"{float(value):.6f}"
            .rstrip("0")
            .rstrip(".")
        )


    # Convert all remaining scalar values into text.
    return str(value)


