# Define one reusable function for writing a change into the audit trail.
def log_cleaning_change(
    audit_rows,
    dataset,
    record_key,
    field,
    old_value,
    new_value,
    action,
    method,
    reason,
):


    # Append one structured audit record to our in-memory audit list.
    audit_rows.append({

        # Dataset containing the changed record.
        "dataset":
            dataset,

        # Employee ID, claim ID, salary-history key etc.
        "record_key":
            str(record_key),

        # Field that was changed.
        "field":
            field,

        # Original value before cleaning.
        "old_value":
            cleaning_audit_value(
                old_value
            ),

        # New value after cleaning.
        "new_value":
            cleaning_audit_value(
                new_value
            ),

        # High-level cleaning action.
        "action":
            action,

        # Exact method used.
        "method":
            method,

        # Why the change was considered appropriate.
        "reason":
            reason,

        # Version of the cleaning methodology.
        "cleaning_version":
            CLEANING_VERSION,
    })


# =============================================================================
# SECTION 27 — STATISTICAL RECONSTRUCTION HELPERS
# =============================================================================


# Define a reusable hierarchical-median estimator.
#
# This is used only when an observed or directly reconstructed value
# is unavailable.
def hierarchical_median(
    series,
    df,
    group_levels,
):


    # Start with an empty numerical estimate for every row.
    estimate = pd.Series(

        np.nan,

        index=df.index,

        dtype="float64"
    )


    # Examine increasingly broad peer groups.
    for columns in group_levels:


        # Calculate the median of the target series
        # within the specified peer-group fields.
        cohort_median = series.groupby(

            [
                df[column]
                for column
                in columns
            ],

            dropna=False

        ).transform(
            "median"
        )


        # Use this cohort median only where a narrower
        # earlier estimate was unavailable.
        estimate = estimate.fillna(
            cohort_median
        )


    # If every cohort level failed,
    # use the overall median as the final fallback.
    estimate = estimate.fillna(
        series.median()
    )


    # Return one estimated value for every record.
    return estimate


# -----------------------------------------------------------------------------


# Define a reusable group-mode calculation.
#
# Mode means the most frequently observed categorical value.
def group_mode_transform(
    series,
    df,
    columns,
):


    # Group the target values using the requested peer fields.
    return series.groupby(

        [
            df[column]
            for column
            in columns
        ],

        dropna=False

    ).transform(


        # For each peer group:
        # return the most common observed value.
        lambda group:

            group.mode().iloc[0]

            if not group.mode().empty

            else pd.NA
    )


# -----------------------------------------------------------------------------


# Define a hierarchical categorical-mode estimator.
def hierarchical_mode(
    series,
    df,
    group_levels,
):


    # Start with an empty object-valued estimate.
    estimate = pd.Series(

        pd.NA,

        index=df.index,

        dtype="object"
    )


    # Move from narrow peer groups toward broader peer groups.
    for columns in group_levels:


        # Calculate the modal value for the current grouping level.
        cohort_mode = group_mode_transform(

            series,
            df,
            columns
        )


        # Fill only estimates that are still missing.
        estimate = estimate.fillna(
            cohort_mode
        )


    # If the entire target series contains no observed values,
    # we cannot construct an overall fallback.
    if series.dropna().empty:

        return estimate


    # Otherwise use the overall mode as the final fallback.
    estimate = estimate.fillna(

        series.dropna().mode().iloc[0]
    )


    # Return the completed estimate.
    return estimate


# =============================================================================
# SECTION 28 — DUPLICATE EMPLOYEE QUALITY SCORE
# =============================================================================


# Define a function that assigns a diagnostic penalty score
# to competing duplicate employee records.
#
# Lower score = better-quality record.
def employee_duplicate_quality_score(
    duplicate_group
):


    # Start every duplicate candidate with zero penalty.
    score = pd.Series(

        0.0,

        index=duplicate_group.index
    )


    # Define important fields and the penalty associated
    # with each missing value.
    critical_field_weights = {

        "date_of_birth":
            10,

        "date_of_joining":
            10,

        "basic_salary_monthly":
            6,

        "eligible_gratuity_wages_monthly":
            6,

        "pensionable_salary_annual":
            6,

        "retirement_age":
            4,
    }


    # Examine each critical field.
    for (
        column,
        penalty
    ) in critical_field_weights.items():


        # Add a penalty when the critical field is missing.
        score += (

            duplicate_group[
                column
            ].isna()

            .astype(float)

            * penalty
        )


    # Penalize a joining date occurring on or before Date of Birth.
    score += (

        duplicate_group[
            "date_of_birth"
        ].notna()

        & duplicate_group[
            "date_of_joining"
        ].notna()

        & (
            duplicate_group[
                "date_of_joining"
            ]

            <= duplicate_group[
                "date_of_birth"
            ]
        )

    ).astype(float) * 20


    # Penalize an exit date occurring before joining date.
    score += (

        duplicate_group[
            "exit_date"
        ].notna()

        & duplicate_group[
            "date_of_joining"
        ].notna()

        & (
            duplicate_group[
                "exit_date"
            ]

            < duplicate_group[
                "date_of_joining"
            ]
        )

    ).astype(float) * 20


    # Penalize an Active record containing an exit date.
    score += (

        duplicate_group[
            "employment_status"
        ].eq("Active")

        & duplicate_group[
            "exit_date"
        ].notna()

    ).astype(float) * 5


    # Penalize a non-active record lacking an exit date.
    score += (

        ~duplicate_group[
            "employment_status"
        ].eq("Active")

        & duplicate_group[
            "exit_date"
        ].isna()

    ).astype(float) * 5


    # Penalize a Gratuity member without a Gratuity plan ID.
    score += (

        duplicate_group[
            "gratuity_member_flag"
        ].eq("Yes")

        & duplicate_group[
            "gratuity_plan_id"
        ].isna()

    ).astype(float) * 3


    # Penalize a Superannuation member without a plan ID.
    score += (

        duplicate_group[
            "superannuation_member_flag"
        ].eq("Yes")

        & duplicate_group[
            "superannuation_plan_id"
        ].isna()

    ).astype(float) * 3


    # Penalize a GTI member without a GTI plan ID.
    score += (

        duplicate_group[
            "gti_member_flag"
        ].eq("Yes")

        & duplicate_group[
            "gti_plan_id"
        ].isna()

    ).astype(float) * 3


    # Convert Basic Salary to numeric form.
    basic_salary = pd.to_numeric(

        duplicate_group[
            "basic_salary_monthly"
        ],

        errors="coerce"
    )


    # Convert Dearness Allowance to numeric form.
    dearness_allowance = pd.to_numeric(

        duplicate_group[
            "dearness_allowance_monthly"
        ],

        errors="coerce"
    )


    # Convert Gratuity Eligible Wage to numeric form.
    gratuity_wage = pd.to_numeric(

        duplicate_group[
            "eligible_gratuity_wages_monthly"
        ],

        errors="coerce"
    )


    # Under our synthetic data construction,
    # Basic = Gratuity Eligible Wage - DA.
    expected_basic_salary = (

        gratuity_wage
        - dearness_allowance
    )


    # Measure relative disagreement with that synthetic-data identity.
    salary_relative_difference = (

        (
            basic_salary
            - expected_basic_salary
        ).abs()

        / expected_basic_salary
        .abs()
        .replace(
            0,
            np.nan
        )
    )


    # Penalize materially inconsistent Basic Salary values.
    score += (

        salary_relative_difference
        > 0.05

    ).fillna(
        False
    ).astype(float) * 8


    # Return one quality score for every duplicate candidate row.
    return score


