# SECTION 29 — RESOLVE EMPLOYEE DUPLICATES
# =============================================================================


# Define a function that reduces the raw census
# to one controlled row per employee.
def resolve_employee_duplicates(
    employee,
    audit_rows,
):


    # Work on a copy so the original raw DataFrame remains untouched.
    result = employee.copy()


    # Store the original raw row number.
    #
    # This gives us deterministic traceability during duplicate resolution.
    result[
        "_source_row_number"
    ] = np.arange(
        1,
        len(result) + 1
    )


    # Create a flag identifying employees whose duplicate
    # identity was explicitly resolved.
    result[
        "duplicate_resolved_flag"
    ] = False


    # Store the type of duplicate resolution.
    result[
        "duplicate_resolution_type"
    ] = "None"


    # Create a list that will contain the row index
    # selected for each employee.
    keep_indices = []


    # Group the census by employee identifier.
    for (
        employee_id,
        employee_group
    ) in result.groupby(

        "employee_id",

        dropna=False,

        sort=False
    ):


        # If the employee ID is missing,
        # or appears only once,
        # no duplicate resolution is required.
        if (
            pd.isna(employee_id)
            or len(employee_group) == 1
        ):


            # Preserve all rows in this non-duplicate group.
            keep_indices.extend(
                employee_group.index.tolist()
            )


            # Continue to the next employee.
            continue


        # Find fields containing different values
        # among rows sharing this employee ID.
        differing_columns = [

            column

            for column
            in employee.columns

            if (
                column != "employee_id"

                and employee_group[
                    column
                ].nunique(
                    dropna=False
                ) > 1
            )
        ]


        # If no business field differs,
        # the records are exact duplicates.
        if not differing_columns:


            # Keep the earliest raw source row.
            keep_index = (

                employee_group
                .sort_values(
                    "_source_row_number"
                )
                .index[0]
            )


            # Record duplicate type.
            duplicate_type = "Exact"


            # Document the selection method.
            resolution_method = (
                "Exact duplicate: "
                "retained first source row"
            )


        # Otherwise the duplicate contains conflicting values.
        else:


            # Calculate a data-quality score for every candidate.
            quality_score = (
                employee_duplicate_quality_score(
                    employee_group
                )
            )


            # Convert source-system names into numeric priority.
            source_priority = (

                employee_group[
                    "source_system"
                ]

                .map(
                    SOURCE_PRIORITY
                )

                .fillna(
                    99
                )
            )


            # Build a ranking table.
            ranking = pd.DataFrame({

                "quality_score":
                    quality_score,

                "source_priority":
                    source_priority,

                "source_row":
                    employee_group[
                        "_source_row_number"
                    ],
            })


            # Select the best-ranked duplicate candidate.
            keep_index = (

                ranking
                .sort_values([

                    "quality_score",

                    "source_priority",

                    "source_row",

                ])
                .index[0]
            )


            # Record duplicate type.
            duplicate_type = (
                "Conflicting"
            )


            # Document our hierarchy.
            resolution_method = (
                "Lowest data-quality score, "
                "then source priority, "
                "then original source row"
            )


        # Mark the surviving employee record as duplicate-resolved.
        result.loc[

            keep_index,

            "duplicate_resolved_flag"

        ] = True


        # Store whether the duplicate was exact or conflicting.
        result.loc[

            keep_index,

            "duplicate_resolution_type"

        ] = duplicate_type


        # Add the surviving row to our final row list.
        keep_indices.append(
            keep_index
        )


        # Capture its original source row number for audit purposes.
        kept_source_row = int(

            result.loc[

                keep_index,

                "_source_row_number"
            ]
        )


        # Record every duplicate row that will be removed.
        for drop_index in employee_group.index:


            # Skip the row we decided to retain.
            if drop_index == keep_index:

                continue


            # Write the duplicate decision to the cleaning audit trail.
            log_cleaning_change(

                audit_rows=
                    audit_rows,

                dataset=
                    "employee_census",

                record_key=
                    employee_id,

                field=
                    "__row__",

                old_value=
                    (
                        "source_row="
                        f"{int(result.loc[drop_index, '_source_row_number'])}"
                    ),

                new_value=
                    (
                        "kept_source_row="
                        f"{kept_source_row}"
                    ),

                action=
                    "Drop duplicate row",

                method=
                    resolution_method,

                reason=
                    (
                        f"{duplicate_type} duplicate employee ID; "
                        "differing fields: "
                        f"{', '.join(differing_columns) if differing_columns else 'none'}"
                    ),
            )


    # Keep only the selected employee rows.
    clean_employee = result.loc[

        keep_indices

    ].copy()


    # Restore original source order.
    clean_employee = (
        clean_employee
        .sort_values(
            "_source_row_number"
        )
    )


    # Remove the temporary source-row field.
    clean_employee = (
        clean_employee
        .drop(
            columns=[
                "_source_row_number"
            ]
        )
    )


    # Build a fresh sequential pandas index.
    clean_employee = (
        clean_employee
        .reset_index(
            drop=True
        )
    )


    # Return the one-row-per-employee census.
    return clean_employee


# =============================================================================
# SECTION 30 — CLEAN SALARY HISTORY
# =============================================================================


# Define a function that reconstructs recoverable
# salary-history values.
def clean_salary_history(
    salary,
    audit_rows,
):


    # Copy and chronologically order salary history.
    result = (

        salary
        .copy()
        .sort_values([

            "employee_id",

            "effective_date",

        ])
        .reset_index(
            drop=True
        )
    )


    # Define historical salary variables that must be numeric.
    numeric_columns = [

        "basic_salary_monthly",

        "dearness_allowance_monthly",

        "gratuity_eligible_wages_monthly",

        "pensionable_salary_annual",

        "edli_eligible_wages_monthly",

        "gross_compensation_annual",
    ]


    # Convert every salary variable into numeric form.
    for column in numeric_columns:

        result[column] = pd.to_numeric(

            result[column],

            errors="coerce"
        )


    # Create explicit reconstruction flags.
    result[
        "basic_salary_reconstructed_flag"
    ] = False


    result[
        "gratuity_wage_reconstructed_flag"
    ] = False


    result[
        "pensionable_salary_reconstructed_flag"
    ] = False


    result[
        "edli_wage_reconstructed_flag"
    ] = False


    # -------------------------------------------------------------------------
    # 30.1 — RECONSTRUCT MISSING OR ZERO BASIC SALARY
    # -------------------------------------------------------------------------


    # Identify missing or non-positive Basic Salary.
    bad_basic_salary = (

        result[
            "basic_salary_monthly"
        ].isna()

        | result[
            "basic_salary_monthly"
        ].le(0)
    )


    # Under our synthetic salary construction:
    #
    # Basic Salary
    # =
    # Gratuity Eligible Wage
    # -
    # Dearness Allowance
    reconstructed_basic = (

        result[
            "gratuity_eligible_wages_monthly"
        ]

        - result[
            "dearness_allowance_monthly"
        ]
    )


    # Use this reconstruction only when it produces a positive value.
    use_basic_reconstruction = (

        bad_basic_salary

        & reconstructed_basic.gt(0)
    )


    # Process every recoverable Basic Salary record.
    for index in result.index[

        use_basic_reconstruction
    ]:


        # Capture old value.
        old_value = result.at[

            index,

            "basic_salary_monthly"
        ]


        # Capture reconstructed value.
        new_value = reconstructed_basic.at[
            index
        ]


        # Write the reconstructed Basic Salary.
        result.at[

            index,

            "basic_salary_monthly"

        ] = new_value


        # Set explicit reconstruction flag.
        result.at[

            index,

            "basic_salary_reconstructed_flag"

        ] = True


        # Create a stable salary-history audit key.
        record_key = (

            f"{result.at[index, 'employee_id']}"

            "|"

            f"{result.at[index, 'effective_date'].date()}"
        )


        # Record the reconstruction.
        log_cleaning_change(

            audit_rows,
            "salary_history",
            record_key,
            "basic_salary_monthly",
            old_value,
            new_value,
            "Reconstruct",
            "Gratuity wage - DA",
            (
                "Synthetic salary design identity; "
                "avoids cohort imputation"
            ),
        )


    # -------------------------------------------------------------------------
    # 30.2 — RECONSTRUCT MISSING GRATUITY WAGE
    # -------------------------------------------------------------------------


    # Find missing Gratuity Eligible Wage where Basic and DA are available.
    use_gratuity_reconstruction = (

        result[
            "gratuity_eligible_wages_monthly"
        ].isna()

        & result[
            "basic_salary_monthly"
        ].notna()

        & result[
            "dearness_allowance_monthly"
        ].notna()
    )


    # Reconstruct every recoverable record.
    for index in result.index[

        use_gratuity_reconstruction
    ]:


        # Capture old value.
        old_value = result.at[

            index,

            "gratuity_eligible_wages_monthly"
        ]


        # Apply the synthetic salary identity:
        #
        # Eligible Wage = Basic + DA
        new_value = (

            result.at[
                index,
                "basic_salary_monthly"
            ]

            + result.at[
                index,
                "dearness_allowance_monthly"
            ]
        )


        # Write reconstructed value.
        result.at[

            index,

            "gratuity_eligible_wages_monthly"

        ] = new_value


        # Record explicit reconstruction status.
        result.at[

            index,

            "gratuity_wage_reconstructed_flag"

        ] = True


        # Build audit key.
        record_key = (

            f"{result.at[index, 'employee_id']}"

            "|"

            f"{result.at[index, 'effective_date'].date()}"
        )


        # Write audit record.
        log_cleaning_change(

            audit_rows,
            "salary_history",
            record_key,
            "gratuity_eligible_wages_monthly",
            old_value,
            new_value,
            "Reconstruct",
            "Basic + DA",
            (
                "Synthetic salary design identity; "
                "actual plan wage definition remains separate"
            ),
        )


    # -------------------------------------------------------------------------
    # 30.3 — RECONSTRUCT MISSING HISTORICAL EDLI WAGE
    # -------------------------------------------------------------------------


    # Find missing EDLI wage-base fields.
    use_edli_reconstruction = (

        result[
            "edli_eligible_wages_monthly"
        ].isna()

        & result[
            "gratuity_eligible_wages_monthly"
        ].notna()
    )


    # Process each recoverable EDLI wage record.
    for index in result.index[

        use_edli_reconstruction
    ]:


        # Capture old value.
        old_value = result.at[

            index,

            "edli_eligible_wages_monthly"
        ]


        # Our synthetic history uses the same raw eligible-wage basis.
        new_value = result.at[

            index,

            "gratuity_eligible_wages_monthly"
        ]


        # Write reconstructed EDLI raw wage input.
        result.at[

            index,

            "edli_eligible_wages_monthly"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "edli_wage_reconstructed_flag"

        ] = True


        # Build audit key.
        record_key = (

            f"{result.at[index, 'employee_id']}"

            "|"

            f"{result.at[index, 'effective_date'].date()}"
        )


        # Record the reconstruction.
        log_cleaning_change(

            audit_rows,
            "salary_history",
            record_key,
            "edli_eligible_wages_monthly",
            old_value,
            new_value,
            "Reconstruct",
            "Historical eligible-wage basis",
            (
                "Synthetic raw wage reconstruction only; "
                "statutory EDLI caps and formulas are applied later"
            ),
        )


    # -------------------------------------------------------------------------
    # 30.4 — RECONSTRUCT MISSING PENSIONABLE SALARY
    # -------------------------------------------------------------------------


    # Calculate each historical row's observed pensionable-wage relationship.
    pension_ratio = (

        result[
            "pensionable_salary_annual"
        ]

        / (

            result[
                "gratuity_eligible_wages_monthly"
            ]

            * 12
        )
    )


    # Calculate each employee's median observed relationship.
    employee_pension_ratio = (

        pension_ratio.groupby(

            result[
                "employee_id"
            ]

        ).transform(
            "median"
        )
    )


    # Identify missing Pensionable Salary where own history exists.
    use_pension_reconstruction = (

        result[
            "pensionable_salary_annual"
        ].isna()

        & employee_pension_ratio.notna()

        & result[
            "gratuity_eligible_wages_monthly"
        ].notna()
    )


    # Reconstruct each missing value from the employee's own history.
    for index in result.index[

        use_pension_reconstruction
    ]:


        # Capture old value.
        old_value = result.at[

            index,

            "pensionable_salary_annual"
        ]


        # Apply employee-specific historical pensionable-wage ratio.
        new_value = (

            result.at[
                index,
                "gratuity_eligible_wages_monthly"
            ]

            * 12

            * employee_pension_ratio.at[
                index
            ]
        )


        # Write reconstructed pensionable salary.
        result.at[

            index,

            "pensionable_salary_annual"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "pensionable_salary_reconstructed_flag"

        ] = True


        # Build audit key.
        record_key = (

            f"{result.at[index, 'employee_id']}"

            "|"

            f"{result.at[index, 'effective_date'].date()}"
        )


        # Record reconstruction.
        log_cleaning_change(

            audit_rows,
            "salary_history",
            record_key,
            "pensionable_salary_annual",
            old_value,
            new_value,
            "Reconstruct",
            (
                "Employee historical "
                "pensionable-to-eligible-wage ratio"
            ),
            (
                "Employee's own observed history preferred "
                "to population imputation"
            ),
        )


    # -------------------------------------------------------------------------
    # 30.5 — RECALCULATE SALARY MOVEMENT AFTER RECONSTRUCTION
    # -------------------------------------------------------------------------


    # Calculate cleaned Basic Salary year-on-year growth.
    #
    # g_t = S_t / S_(t-1) - 1
    result[
        "basic_salary_growth_rate_clean"
    ] = (

        result.groupby(
            "employee_id"
        )[
            "basic_salary_monthly"
        ]

        .pct_change(
            fill_method=None
        )
    )


    # Calculate cleaned Gross Compensation year-on-year growth.
    result[
        "gross_comp_growth_rate_clean"
    ] = (

        result.groupby(
            "employee_id"
        )[
            "gross_compensation_annual"
        ]

        .pct_change(
            fill_method=None
        )
    )


    # Preserve unusually large movements for human review.
    #
    # IMPORTANT:
    # We do NOT automatically winsorize or replace them.
    result[
        "unresolved_large_salary_movement_flag"
    ] = (

        result[
            "basic_salary_growth_rate_clean"
        ].notna()

        & (

            (
                result[
                    "basic_salary_growth_rate_clean"
                ]
                > QA_LARGE_SALARY_INCREASE
            )

            | (
                result[
                    "basic_salary_growth_rate_clean"
                ]
                < QA_LARGE_SALARY_DECREASE
            )
        )

    ) | (

        result[
            "gross_comp_growth_rate_clean"
        ].notna()

        & (

            (
                result[
                    "gross_comp_growth_rate_clean"
                ]
                > QA_LARGE_SALARY_INCREASE
            )

            | (
                result[
                    "gross_comp_growth_rate_clean"
                ]
                < QA_LARGE_SALARY_DECREASE
            )
        )
    )


    # Return cleaned salary history.
    return result


# =============================================================================
# SECTION 31 — CLEAN EMPLOYEE DATES, CHRONOLOGY AND STATUS
# =============================================================================


# Define a function that reconstructs employee chronology
# using the hierarchy established in the book.
def clean_employee_dates_and_status(
    employee,
    claims,
    salary_clean,
    audit_rows,
):


    # Work on a copy.
    result = employee.copy()


    # Create explicit cleaning flags.
    result[
        "date_of_birth_imputed_flag"
    ] = False


    result[
        "date_of_joining_reconstructed_flag"
    ] = False


    result[
        "exit_date_reconstructed_flag"
    ] = False


    result[
        "employment_status_reconciled_flag"
    ] = False


    result[
        "exit_reason_reconciled_flag"
    ] = False


    # Record whether DOB was observed or imputed.
    result[
        "date_of_birth_imputation_method"
    ] = "Observed"


    # Record whether DOJ was observed or reconstructed.
    result[
        "date_of_joining_reconstruction_method"
    ] = "Observed"


    # -------------------------------------------------------------------------
    # 31.1 — MISSING DATE OF BIRTH
    # -------------------------------------------------------------------------


    # Calculate observed attained age.
    observed_age = (

        (
            VALUATION_DATE
            - result[
                "date_of_birth"
            ]
        ).dt.days

        / 365.25
    )


    # Keep only plausible observed ages for constructing peer medians.
    valid_age = observed_age.where(

        (
            observed_age >= 18
        )

        & (
            observed_age
            <= QA_MAX_ATTAINED_AGE
        )
    )


    # Estimate age hierarchically:
    #
    # grade + status + occupation
    # then grade + status
    # then grade
    # then overall median.
    estimated_age = hierarchical_median(

        valid_age,

        result,

        [

            [
                "grade",
                "employment_status",
                "occupation_class",
            ],

            [
                "grade",
                "employment_status",
            ],

            [
                "grade",
            ],
        ]
    )


    # Identify records with missing DOB.
    missing_dob = result[
        "date_of_birth"
    ].isna()


    # Convert estimated age back into an approximate Date of Birth.
    estimated_dob = (

        VALUATION_DATE

        - pd.to_timedelta(

            np.rint(
                estimated_age
                * 365.25
            ),

            unit="D"
        )
    ).dt.normalize()


    # Process each missing DOB.
    for index in result.index[
        missing_dob
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "date_of_birth"
        ]


        # Capture imputed DOB.
        new_value = estimated_dob.at[
            index
        ]


        # Write imputed DOB.
        result.at[

            index,

            "date_of_birth"

        ] = new_value


        # Flag that this was not an observed DOB.
        result.at[

            index,

            "date_of_birth_imputed_flag"

        ] = True


        # Record the method explicitly.
        result.at[

            index,

            "date_of_birth_imputation_method"

        ] = "Cohort_Median_Age"


        # Write audit record.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "date_of_birth",
            old_value,
            new_value,
            "Impute",
            "Hierarchical cohort median age",
            (
                "Last-resort documented imputation: "
                "grade + status + occupation, "
                "then broader fallback"
            ),
        )


    # -------------------------------------------------------------------------
    # 31.2 — MISSING OR IMPLAUSIBLE DATE OF JOINING
    # -------------------------------------------------------------------------


    # Recalculate joining age after DOB imputation.
    joining_age = (

        (
            result[
                "date_of_joining"
            ]

            - result[
                "date_of_birth"
            ]
        ).dt.days

        / 365.25
    )


    # Keep only plausible joining ages for peer-group estimation.
    valid_joining_age = joining_age.where(

        (
            joining_age
            >= QA_MIN_JOINING_AGE
        )

        & (
            joining_age
            <= QA_MAX_JOINING_AGE
        )
    )


    # Estimate joining age using increasingly broad cohorts.
    estimated_joining_age = hierarchical_median(

        valid_joining_age,

        result,

        [

            [
                "employment_type",
                "grade",
                "occupation_class",
            ],

            [
                "employment_type",
                "grade",
            ],

            [
                "grade",
            ],
        ]
    )


    # Identify missing or diagnostically implausible joining dates.
    reconstruct_doj = (

        result[
            "date_of_joining"
        ].isna()

        | (
            joining_age
            < QA_MIN_JOINING_AGE
        )

        | (
            joining_age
            > QA_MAX_JOINING_AGE
        )
    )


    # Generate candidate DOJ from DOB plus estimated joining age.
    candidate_doj = (

        result[
            "date_of_birth"
        ]

        + pd.to_timedelta(

            np.rint(
                estimated_joining_age
                * 365.25
            ),

            unit="D"
        )
    )


    # Find earliest salary-history date for every employee.
    first_salary_date = (

        salary_clean
        .groupby(
            "employee_id"
        )[
            "effective_date"
        ]
        .min()
    )


    # Map earliest salary date back to employee master.
    employee_first_salary_date = (

        result[
            "employee_id"
        ]

        .map(
            first_salary_date
        )
    )


    # An employee cannot logically join after a salary-history record exists.
    candidate_doj = candidate_doj.where(

        ~(

            employee_first_salary_date.notna()

            & (
                candidate_doj
                > employee_first_salary_date
            )
        ),

        employee_first_salary_date
    )


    # Calculate one day before known exit date.
    day_before_exit = (

        result[
            "exit_date"
        ]

        - pd.Timedelta(
            days=1
        )
    )


    # A joining date cannot be on or after a known exit date.
    candidate_doj = candidate_doj.where(

        ~(

            result[
                "exit_date"
            ].notna()

            & (
                candidate_doj
                >= result[
                    "exit_date"
                ]
            )
        ),

        day_before_exit
    )


    # A joining date cannot occur after the valuation date.
    candidate_doj = candidate_doj.where(

        candidate_doj
        <= VALUATION_DATE,

        VALUATION_DATE
        - pd.Timedelta(
            days=1
        )
    )


    # Process every DOJ requiring reconstruction.
    for index in result.index[
        reconstruct_doj
    ]:


        # Capture original DOJ.
        old_value = result.at[
            index,
            "date_of_joining"
        ]


        # Capture reconstructed DOJ.
        new_value = candidate_doj.at[
            index
        ]


        # Write reconstructed date.
        result.at[

            index,

            "date_of_joining"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "date_of_joining_reconstructed_flag"

        ] = True


        # Record reconstruction method.
        result.at[

            index,

            "date_of_joining_reconstruction_method"

        ] = "Cohort_Median_Joining_Age"


        # Add audit record.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "date_of_joining",
            old_value,
            new_value,
            "Reconstruct",
            "Hierarchical cohort median joining age",
            (
                "Candidate constrained by salary-history start, "
                "exit date and valuation date"
            ),
        )


    # -------------------------------------------------------------------------
    # 31.3 — CREATE EXPERIENCE-EVENT REFERENCE
    # -------------------------------------------------------------------------


    # Select observed employee Experience events.
    experience_events = claims.loc[

        claims[
            "product_type"
        ].eq("Experience")

        & claims[
            "event_date"
        ].notna(),

        [
            "employee_id",
            "event_date",
            "event_type",
        ]

    ].copy()


    # Keep one actual decrement event per employee.
    experience_events = (

        experience_events
        .drop_duplicates(

            "employee_id",

            keep="last"
        )
        .set_index(
            "employee_id"
        )
    )


    # Map actual event dates into employee master.
    observed_event_date = (

        result[
            "employee_id"
        ]

        .map(
            experience_events[
                "event_date"
            ]
        )
    )


    # Map actual event types into employee master.
    observed_event_type = (

        result[
            "employee_id"
        ]

        .map(
            experience_events[
                "event_type"
            ]
        )
    )


    # -------------------------------------------------------------------------
    # 31.4 — RECOVER MISSING EXIT DATE
    # -------------------------------------------------------------------------


    # Identify non-active employees without exit dates
    # where an observed Experience event exists.
    recover_exit_date = (

        ~result[
            "employment_status"
        ].eq("Active")

        & result[
            "exit_date"
        ].isna()

        & observed_event_date.notna()
    )


    # Recover every available exit date.
    for index in result.index[
        recover_exit_date
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "exit_date"
        ]


        # Use actual Experience event date.
        new_value = observed_event_date.at[
            index
        ]


        # Write recovered exit date.
        result.at[

            index,

            "exit_date"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "exit_date_reconstructed_flag"

        ] = True


        # Audit recovery.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "exit_date",
            old_value,
            new_value,
            "Recover",
            "Claims Experience event date",
            (
                "Observed event history is preferred "
                "to statistical imputation"
            ),
        )


    # -------------------------------------------------------------------------
    # 31.5 — RECONCILE EMPLOYMENT STATUS
    # -------------------------------------------------------------------------


    # Define event-to-employment-status relationship.
    event_to_status = {

        "Withdrawal":
            "Exited",

        "Retirement":
            "Retired",

        "Early Retirement":
            "Early Retired",

        "Death":
            "Deceased",

        "Disability":
            "Disabled",
    }


    # Convert observed Experience event type into expected status.
    status_from_event = (

        observed_event_type
        .map(
            event_to_status
        )
    )


    # Identify stale Active statuses where actual event evidence exists.
    reconcile_status_from_event = (

        result[
            "employment_status"
        ].eq("Active")

        & (

            result[
                "exit_date"
            ].notna()

            | result[
                "exit_reason"
            ].notna()
        )

        & status_from_event.notna()
    )


    # Reconcile each stale status.
    for index in result.index[
        reconcile_status_from_event
    ]:


        # Capture old status.
        old_value = result.at[
            index,
            "employment_status"
        ]


        # Use status implied by actual Experience event.
        new_value = status_from_event.at[
            index
        ]


        # Write reconciled status.
        result.at[

            index,

            "employment_status"

        ] = new_value


        # Flag reconciliation.
        result.at[

            index,

            "employment_status_reconciled_flag"

        ] = True


        # Audit status reconciliation.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "employment_status",
            old_value,
            new_value,
            "Reconcile",
            "Claims Experience event type",
            (
                "Observed event evidence overrides "
                "stale Active status"
            ),
        )


    # Convert recorded exit reason into expected status.
    status_from_exit_reason = (

        result[
            "exit_reason"
        ]

        .map(
            event_to_status
        )
    )


    # If no Experience event exists,
    # use recorded exit reason as secondary evidence.
    reconcile_status_from_reason = (

        result[
            "employment_status"
        ].eq("Active")

        & (

            result[
                "exit_date"
            ].notna()

            | result[
                "exit_reason"
            ].notna()
        )

        & status_from_event.isna()

        & status_from_exit_reason.notna()
    )


    # Process secondary status reconciliations.
    for index in result.index[
        reconcile_status_from_reason
    ]:


        # Capture old status.
        old_value = result.at[
            index,
            "employment_status"
        ]


        # Use status implied by recorded exit reason.
        new_value = status_from_exit_reason.at[
            index
        ]


        # Write status.
        result.at[

            index,

            "employment_status"

        ] = new_value


        # Flag reconciliation.
        result.at[

            index,

            "employment_status_reconciled_flag"

        ] = True


        # Audit the change.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "employment_status",
            old_value,
            new_value,
            "Reconcile",
            "Recorded exit reason",
            (
                "Used only when no observed "
                "Experience event was available"
            ),
        )


    # -------------------------------------------------------------------------
    # 31.6 — RECONCILE EXIT REASON
    # -------------------------------------------------------------------------


    # Define status-to-exit-reason relationship.
    status_to_reason = {

        "Exited":
            "Withdrawal",

        "Retired":
            "Retirement",

        "Early Retired":
            "Early Retirement",

        "Deceased":
            "Death",

        "Disabled":
            "Disability",
    }


    # Calculate expected reason from reconciled status.
    expected_exit_reason = (

        result[
            "employment_status"
        ]

        .map(
            status_to_reason
        )
    )


    # Identify missing or conflicting exit reasons.
    reconcile_exit_reason = (

        expected_exit_reason.notna()

        & (

            result[
                "exit_reason"
            ].isna()

            | (
                result[
                    "exit_reason"
                ]
                != expected_exit_reason
            )
        )
    )


    # Reconcile every inconsistent reason.
    for index in result.index[
        reconcile_exit_reason
    ]:


        # Default to reason implied by employment status.
        new_value = expected_exit_reason.at[
            index
        ]


        # If actual Experience event agrees with the employment status,
        # prefer the observed event label.
        if (

            pd.notna(
                observed_event_type.at[
                    index
                ]
            )

            and status_from_event.at[
                index
            ]

            == result.at[
                index,
                "employment_status"
            ]
        ):

            new_value = (
                observed_event_type.at[
                    index
                ]
            )


        # Capture old exit reason.
        old_value = result.at[
            index,
            "exit_reason"
        ]


        # Write reconciled reason.
        result.at[

            index,

            "exit_reason"

        ] = new_value


        # Flag reconciliation.
        result.at[

            index,

            "exit_reason_reconciled_flag"

        ] = True


        # Audit reconciliation.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "exit_reason",
            old_value,
            new_value,
            "Reconcile",
            (
                "Employment status / "
                "Experience event"
            ),
            (
                "Status and exit reason "
                "must describe the same event"
            ),
        )


    # Return chronologically cleaned employee census.
    return result


# =============================================================================
# SECTION 32 — CLEAN CURRENT EMPLOYEE SALARY
# =============================================================================


# Define a function that reconstructs current salary inputs
# while preserving legitimate outliers whenever possible.
def clean_employee_salary(
    employee,
    salary_clean,
    audit_rows,
):


    # Work on a copy.
    result = employee.copy()


    # Define current salary variables.
    numeric_columns = [

        "basic_salary_monthly",

        "dearness_allowance_monthly",

        "eligible_gratuity_wages_monthly",

        "pensionable_salary_annual",

        "gross_compensation_annual",
    ]


    # Convert them into numeric values.
    for column in numeric_columns:

        result[column] = pd.to_numeric(

            result[column],

            errors="coerce"
        )


    # Create reconstruction flags.
    result[
        "basic_salary_reconstructed_flag"
    ] = False


    result[
        "gratuity_wage_reconstructed_flag"
    ] = False


    result[
        "pensionable_salary_reconstructed_flag"
    ] = False


    result[
        "gross_compensation_reconstructed_flag"
    ] = False


    # -------------------------------------------------------------------------
    # 32.1 — BASIC SALARY
    # -------------------------------------------------------------------------


    # Reconstruct expected Basic Salary from our synthetic salary identity.
    expected_basic_salary = (

        result[
            "eligible_gratuity_wages_monthly"
        ]

        - result[
            "dearness_allowance_monthly"
        ]
    )


    # Measure disagreement between recorded and reconstructed Basic Salary.
    basic_relative_difference = (

        (
            result[
                "basic_salary_monthly"
            ]

            - expected_basic_salary
        ).abs()

        / expected_basic_salary
        .abs()
        .replace(
            0,
            np.nan
        )
    )


    # Repair Basic Salary only if it is missing,
    # non-positive or materially inconsistent with internal data.
    reconstruct_basic = (

        (

            result[
                "basic_salary_monthly"
            ].isna()

            | result[
                "basic_salary_monthly"
            ].le(0)

            | (
                basic_relative_difference
                > 0.05
            )
        )

        & expected_basic_salary.gt(0)
    )


    # Process internal Basic Salary reconstructions.
    for index in result.index[
        reconstruct_basic
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "basic_salary_monthly"
        ]


        # Use internally reconstructed Basic Salary.
        new_value = expected_basic_salary.at[
            index
        ]


        # Write new value.
        result.at[

            index,

            "basic_salary_monthly"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "basic_salary_reconstructed_flag"

        ] = True


        # Audit reconstruction.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "basic_salary_monthly",
            old_value,
            new_value,
            "Reconstruct",
            "Eligible gratuity wage - DA",
            (
                "Synthetic data cross-field identity used "
                "to recover missing or inconsistent Basic Salary"
            ),
        )


    # -------------------------------------------------------------------------
    # 32.2 — BASIC SALARY FALLBACK TO OWN HISTORY
    # -------------------------------------------------------------------------


    # Identify latest cleaned salary-history row for every employee.
    latest_salary_history = (

        salary_clean
        .sort_values([

            "employee_id",

            "effective_date",

        ])
        .groupby(
            "employee_id",
            as_index=False
        )
        .tail(1)
        .set_index(
            "employee_id"
        )
    )


    # Map latest historical Basic Salary into employee census.
    latest_basic_salary = (

        result[
            "employee_id"
        ]

        .map(
            latest_salary_history[
                "basic_salary_monthly"
            ]
        )
    )


    # Use own history only where Basic Salary is still missing.
    recover_basic_from_history = (

        result[
            "basic_salary_monthly"
        ].isna()

        & latest_basic_salary.gt(0)
    )


    # Process historical recoveries.
    for index in result.index[
        recover_basic_from_history
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "basic_salary_monthly"
        ]


        # Use employee's own latest known Basic Salary.
        new_value = latest_basic_salary.at[
            index
        ]


        # Write recovered value.
        result.at[

            index,

            "basic_salary_monthly"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "basic_salary_reconstructed_flag"

        ] = True


        # Audit recovery.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "basic_salary_monthly",
            old_value,
            new_value,
            "Recover",
            "Latest employee salary history",
            (
                "Employee's own historical record "
                "preferred to cohort imputation"
            ),
        )


    # -------------------------------------------------------------------------
    # 32.3 — GRATUITY WAGE
    # -------------------------------------------------------------------------


    # Identify missing Gratuity Eligible Wage.
    reconstruct_gratuity_wage = (

        result[
            "eligible_gratuity_wages_monthly"
        ].isna()

        & result[
            "basic_salary_monthly"
        ].notna()

        & result[
            "dearness_allowance_monthly"
        ].notna()
    )


    # Process every reconstruction.
    for index in result.index[
        reconstruct_gratuity_wage
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "eligible_gratuity_wages_monthly"
        ]


        # Apply synthetic census relationship.
        new_value = (

            result.at[
                index,
                "basic_salary_monthly"
            ]

            + result.at[
                index,
                "dearness_allowance_monthly"
            ]
        )


        # Write reconstructed wage.
        result.at[

            index,

            "eligible_gratuity_wages_monthly"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "gratuity_wage_reconstructed_flag"

        ] = True


        # Audit reconstruction.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "eligible_gratuity_wages_monthly",
            old_value,
            new_value,
            "Reconstruct",
            "Basic + DA",
            (
                "Synthetic census wage-base design; "
                "actual scheme wage definition remains plan-controlled"
            ),
        )


    # -------------------------------------------------------------------------
    # 32.4 — PENSIONABLE SALARY FROM OWN HISTORY
    # -------------------------------------------------------------------------


    # Calculate historical pensionable-to-eligible-wage ratio.
    historical_pension_ratio = (

        salary_clean[
            "pensionable_salary_annual"
        ]

        / (

            salary_clean[
                "gratuity_eligible_wages_monthly"
            ]

            * 12
        )
    )


    # Calculate each employee's median observed ratio.
    employee_pension_ratio = (

        historical_pension_ratio.groupby(

            salary_clean[
                "employee_id"
            ]

        ).median()
    )


    # Map employee-specific ratio into employee census.
    pension_ratio_for_employee = (

        result[
            "employee_id"
        ]

        .map(
            employee_pension_ratio
        )
    )


    # Identify missing Pensionable Salary where own history exists.
    reconstruct_pension_from_history = (

        result[
            "pensionable_salary_annual"
        ].isna()

        & pension_ratio_for_employee.notna()

        & result[
            "eligible_gratuity_wages_monthly"
        ].notna()
    )


    # Process each employee.
    for index in result.index[
        reconstruct_pension_from_history
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "pensionable_salary_annual"
        ]


        # Reconstruct using employee's own historical relationship.
        new_value = (

            result.at[
                index,
                "eligible_gratuity_wages_monthly"
            ]

            * 12

            * pension_ratio_for_employee.at[
                index
            ]
        )


        # Write reconstructed value.
        result.at[

            index,

            "pensionable_salary_annual"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "pensionable_salary_reconstructed_flag"

        ] = True


        # Audit reconstruction.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "pensionable_salary_annual",
            old_value,
            new_value,
            "Reconstruct",
            (
                "Employee historical "
                "pensionable-wage ratio"
            ),
            "Employee's own historical basis retained",
        )


    # -------------------------------------------------------------------------
    # 32.5 — PENSIONABLE SALARY COHORT FALLBACK
    # -------------------------------------------------------------------------


    # Attach employee grade and pension scheme type
    # to historical salary observations.
    historical_salary_with_cohort = (

        salary_clean.merge(

            result[[

                "employee_id",

                "grade",

                "superannuation_scheme_type",

            ]],

            on="employee_id",

            how="left"
        )
    )


    # Calculate historical pension ratio for cohort analysis.
    historical_salary_with_cohort[
        "pension_ratio"
    ] = (

        historical_salary_with_cohort[
            "pensionable_salary_annual"
        ]

        / (

            historical_salary_with_cohort[
                "gratuity_eligible_wages_monthly"
            ]

            * 12
        )
    )


    # Calculate median ratio by pension scheme type and grade.
    scheme_grade_ratio = (

        historical_salary_with_cohort
        .groupby(

            [
                "superannuation_scheme_type",
                "grade",
            ],

            dropna=False

        )[
            "pension_ratio"
        ]
        .median()
    )


    # Calculate broader grade-only fallback.
    grade_ratio = (

        historical_salary_with_cohort
        .groupby(

            "grade",

            dropna=False

        )[
            "pension_ratio"
        ]
        .median()
    )


    # Calculate final overall fallback ratio.
    overall_pension_ratio = (

        historical_salary_with_cohort[
            "pension_ratio"
        ].median()
    )


    # Find employees whose Pensionable Salary remains missing.
    cohort_pension_fallback = (

        result[
            "pensionable_salary_annual"
        ].isna()

        & result[
            "eligible_gratuity_wages_monthly"
        ].notna()
    )


    # Process last-resort cohort imputations.
    for index in result.index[
        cohort_pension_fallback
    ]:


        # Build scheme-type and grade lookup key.
        cohort_key = (

            result.at[
                index,
                "superannuation_scheme_type"
            ],

            result.at[
                index,
                "grade"
            ],
        )


        # Try scheme-type + grade median first.
        selected_ratio = (

            scheme_grade_ratio.get(

                cohort_key,

                np.nan
            )
        )


        # If unavailable, use grade median.
        if pd.isna(
            selected_ratio
        ):

            selected_ratio = (

                grade_ratio.get(

                    result.at[
                        index,
                        "grade"
                    ],

                    np.nan
                )
            )


        # If still unavailable, use overall median.
        if pd.isna(
            selected_ratio
        ):

            selected_ratio = (
                overall_pension_ratio
            )


        # Only impute if a usable ratio exists.
        if pd.notna(
            selected_ratio
        ):


            # Capture old value.
            old_value = result.at[
                index,
                "pensionable_salary_annual"
            ]


            # Calculate cohort-imputed Pensionable Salary.
            new_value = (

                result.at[
                    index,
                    "eligible_gratuity_wages_monthly"
                ]

                * 12

                * selected_ratio
            )


            # Write imputed value.
            result.at[

                index,

                "pensionable_salary_annual"

            ] = new_value


            # Flag reconstruction.
            result.at[

                index,

                "pensionable_salary_reconstructed_flag"

            ] = True


            # Audit last-resort imputation.
            log_cleaning_change(

                audit_rows,
                "employee_census",
                result.at[
                    index,
                    "employee_id"
                ],
                "pensionable_salary_annual",
                old_value,
                new_value,
                "Impute",
                (
                    "Hierarchical cohort median "
                    "pensionable-wage ratio"
                ),
                (
                    "Used only because employee "
                    "had no usable own salary history"
                ),
            )


    # -------------------------------------------------------------------------
    # 32.6 — GROSS COMPENSATION OUTLIER CONTROL
    # -------------------------------------------------------------------------


    # Store current Gross Compensation.
    gross_compensation = result[
        "gross_compensation_annual"
    ]


    # Calculate grade-specific first quartile.
    gross_q1 = gross_compensation.groupby(

        result[
            "grade"
        ]

    ).transform(

        lambda series:
            series.quantile(
                0.25
            )
    )


    # Calculate grade-specific third quartile.
    gross_q3 = gross_compensation.groupby(

        result[
            "grade"
        ]

    ).transform(

        lambda series:
            series.quantile(
                0.75
            )
    )


    # Calculate grade-specific IQR.
    gross_iqr = (
        gross_q3
        - gross_q1
    )


    # Identify only extreme 3-IQR observations.
    extreme_gross_compensation = (

        gross_compensation.notna()

        & (

            (
                gross_compensation

                < (
                    gross_q1
                    - QA_EXTREME_IQR_MULTIPLIER
                    * gross_iqr
                )
            )

            | (
                gross_compensation

                > (
                    gross_q3
                    + QA_EXTREME_IQR_MULTIPLIER
                    * gross_iqr
                )
            )
        )
    )


    # Map latest historical Gross Compensation.
    latest_historical_gross = (

        result[
            "employee_id"
        ]

        .map(
            latest_salary_history[
                "gross_compensation_annual"
            ]
        )
    )


    # Map latest historical Basic Salary.
    latest_historical_basic = (

        result[
            "employee_id"
        ]

        .map(
            latest_salary_history[
                "basic_salary_monthly"
            ]
        )
    )


    # Compare current Gross Compensation with own historical value.
    gross_history_ratio = (

        gross_compensation

        / latest_historical_gross
    )


    # Identify materially inconsistent history relationships.
    material_history_difference = (

        gross_history_ratio.notna()

        & (

            (
                gross_history_ratio
                < QA_HISTORY_RATIO_LOW
            )

            | (
                gross_history_ratio
                > QA_HISTORY_RATIO_HIGH
            )
        )
    )


    # Correct Gross Compensation ONLY when:
    #
    # 1. it is an extreme cross-sectional outlier AND
    # 2. it materially disagrees with the employee's own history.
    reconstruct_gross_compensation = (

        extreme_gross_compensation

        & material_history_difference

        & latest_historical_gross.gt(0)

        & latest_historical_basic.gt(0)

        & result[
            "basic_salary_monthly"
        ].gt(0)
    )


    # Scale historical compensation using current Basic Salary.
    reconstructed_gross = (

        result[
            "basic_salary_monthly"
        ]

        * (

            latest_historical_gross

            / latest_historical_basic
        )
    )


    # Process any genuinely unsupported extreme values.
    for index in result.index[
        reconstruct_gross_compensation
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "gross_compensation_annual"
        ]


        # Capture reconstructed value.
        new_value = reconstructed_gross.at[
            index
        ]


        # Write reconstructed compensation.
        result.at[

            index,

            "gross_compensation_annual"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "gross_compensation_reconstructed_flag"

        ] = True


        # Audit reconstruction.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "gross_compensation_annual",
            old_value,
            new_value,
            "Reconstruct",
            (
                "Own latest history scaled "
                "by current Basic Salary"
            ),
            (
                "Outlier corrected only when both "
                "cross-sectional and own-history diagnostics disagree"
            ),
        )


    # Return cleaned current salary fields.
    return result


# =============================================================================
# SECTION 33 — CLEAN PRODUCT MEMBERSHIP AND PLAN IDS
# =============================================================================


# Define a function that reconciles missing plan identifiers
# while keeping every inferred value explicitly flagged.
def clean_employee_membership(
    employee,
    audit_rows,
):


    # Work on a copy.
    result = employee.copy()


    # Create explicit plan-ID and EDLI reconciliation flags.
    result[
        "gratuity_plan_id_imputed_flag"
    ] = False


    result[
        "superannuation_plan_id_imputed_flag"
    ] = False


    result[
        "gti_plan_id_reconstructed_flag"
    ] = False


    result[
        "edli_eligibility_reconciled_flag"
    ] = False


    # -------------------------------------------------------------------------
    # 33.1 — GRATUITY PLAN ID
    # -------------------------------------------------------------------------


    # Use only observed Gratuity-member plan IDs to construct peer modes.
    observed_gratuity_plan = (

        result[
            "gratuity_plan_id"
        ]

        .where(

            result[
                "gratuity_member_flag"
            ].eq("Yes")
        )
    )


    # Estimate missing plan ID hierarchically.
    estimated_gratuity_plan = hierarchical_mode(

        observed_gratuity_plan,

        result,

        [

            [
                "grade",
                "department",
                "occupation_class",
            ],

            [
                "grade",
                "department",
            ],

            [
                "grade",
            ],
        ]
    )


    # Identify Gratuity members missing a plan ID.
    impute_gratuity_plan = (

        result[
            "gratuity_member_flag"
        ].eq("Yes")

        & result[
            "gratuity_plan_id"
        ].isna()

        & estimated_gratuity_plan.notna()
    )


    # Impute missing synthetic plan IDs.
    for index in result.index[
        impute_gratuity_plan
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "gratuity_plan_id"
        ]


        # Capture estimated plan ID.
        new_value = estimated_gratuity_plan.at[
            index
        ]


        # Write plan ID.
        result.at[

            index,

            "gratuity_plan_id"

        ] = new_value


        # Explicitly flag statistical imputation.
        result.at[

            index,

            "gratuity_plan_id_imputed_flag"

        ] = True


        # Audit plan-ID imputation.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "gratuity_plan_id",
            old_value,
            new_value,
            "Impute",
            "Hierarchical cohort mode",
            (
                "Synthetic-data fallback only; "
                "production plan membership should be confirmed "
                "from enrollment records"
            ),
        )


    # -------------------------------------------------------------------------
    # 33.2 — SUPERANNUATION PLAN ID
    # -------------------------------------------------------------------------


    # Restrict observed Superannuation plan IDs to actual members.
    observed_super_plan = (

        result[
            "superannuation_plan_id"
        ]

        .where(

            result[
                "superannuation_member_flag"
            ].eq("Yes")
        )
    )


    # Estimate within the same DB/DC scheme type first.
    estimated_super_plan = hierarchical_mode(

        observed_super_plan,

        result,

        [

            [
                "superannuation_scheme_type",
                "grade",
                "department",
            ],

            [
                "superannuation_scheme_type",
                "grade",
            ],

            [
                "superannuation_scheme_type",
            ],
        ]
    )


    # Identify members missing Superannuation plan ID.
    impute_super_plan = (

        result[
            "superannuation_member_flag"
        ].eq("Yes")

        & result[
            "superannuation_plan_id"
        ].isna()

        & estimated_super_plan.notna()
    )


    # Impute plan IDs without changing DB/DC scheme classification.
    for index in result.index[
        impute_super_plan
    ]:


        # Capture old plan ID.
        old_value = result.at[
            index,
            "superannuation_plan_id"
        ]


        # Capture estimated plan ID.
        new_value = estimated_super_plan.at[
            index
        ]


        # Write plan ID.
        result.at[

            index,

            "superannuation_plan_id"

        ] = new_value


        # Flag statistical imputation.
        result.at[

            index,

            "superannuation_plan_id_imputed_flag"

        ] = True


        # Audit the change.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "superannuation_plan_id",
            old_value,
            new_value,
            "Impute",
            "Scheme-type-specific cohort mode",
            (
                "Synthetic-data fallback; "
                "existing DB/DC scheme type is preserved"
            ),
        )


    # -------------------------------------------------------------------------
    # 33.3 — GTI PLAN ID
    # -------------------------------------------------------------------------


    # Keep observed GTI plan IDs for covered employees.
    observed_gti_plan = (

        result[
            "gti_plan_id"
        ]

        .where(

            result[
                "gti_member_flag"
            ].eq("Yes")
        )
    )


    # In our synthetic architecture,
    # GTI cover basis maps directly to the designed plan structure.
    estimated_gti_plan = hierarchical_mode(

        observed_gti_plan,

        result,

        [
            [
                "gti_cover_basis",
            ]
        ]
    )


    # Identify covered employees missing GTI plan ID.
    reconstruct_gti_plan = (

        result[
            "gti_member_flag"
        ].eq("Yes")

        & result[
            "gti_plan_id"
        ].isna()

        & estimated_gti_plan.notna()
    )


    # Recover GTI plan ID.
    for index in result.index[
        reconstruct_gti_plan
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "gti_plan_id"
        ]


        # Capture plan ID implied by cover basis.
        new_value = estimated_gti_plan.at[
            index
        ]


        # Write reconstructed plan ID.
        result.at[

            index,

            "gti_plan_id"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "gti_plan_id_reconstructed_flag"

        ] = True


        # Audit reconstruction.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "gti_plan_id",
            old_value,
            new_value,
            "Reconstruct",
            "GTI cover-basis mapping",
            (
                "Cover basis uniquely identifies "
                "the synthetic GTI plan structure"
            ),
        )


    # -------------------------------------------------------------------------
    # 33.4 — PF / EDLI CONSISTENCY
    # -------------------------------------------------------------------------


    # EDLI is provident-fund-linked.
    #
    # Therefore PF = No and EDLI = Yes is internally inconsistent.
    reconcile_edli = (

        ~result[
            "pf_member_flag"
        ].eq("Yes")

        & result[
            "edli_eligible_flag"
        ].eq("Yes")
    )


    # Reconcile inconsistent EDLI flags.
    for index in result.index[
        reconcile_edli
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "edli_eligible_flag"
        ]


        # Set consistent value.
        new_value = "No"


        # Write reconciled eligibility.
        result.at[

            index,

            "edli_eligible_flag"

        ] = new_value


        # Flag reconciliation.
        result.at[

            index,

            "edli_eligibility_reconciled_flag"

        ] = True


        # Audit change.
        log_cleaning_change(

            audit_rows,
            "employee_census",
            result.at[
                index,
                "employee_id"
            ],
            "edli_eligible_flag",
            old_value,
            new_value,
            "Reconcile",
            "PF membership prerequisite",
            (
                "EDLI is provident-fund-linked; "
                "arbitrary EDLI eligibility is not retained"
            ),
        )


    # Return membership-cleaned employee data.
    return result


# =============================================================================
# SECTION 34 — CLEAN CLAIMS AND EXPOSURE HISTORY
# =============================================================================


# Define a function that reconstructs invalid exposure periods
# without fabricating claim amounts.
def clean_claims_history(
    claims,
    employee_clean,
    audit_rows,
):


    # Work on a copy.
    result = claims.copy()


    # Create explicit reconstruction flags.
    result[
        "exposure_start_reconstructed_flag"
    ] = False


    result[
        "exposure_end_reconstructed_flag"
    ] = False


    # Create a flag for claim amounts that cannot be responsibly reconstructed.
    result[
        "unresolved_claim_amount_flag"
    ] = False


    # -------------------------------------------------------------------------
    # 34.1 — REPAIR EXPERIENCE RECORDS WITH MISSING END DATE
    # -------------------------------------------------------------------------


    # For an observed Experience event,
    # exposure naturally ends on the event date.
    experience_event_missing_end = (

        result[
            "product_type"
        ].eq("Experience")

        & result[
            "exposure_end_date"
        ].isna()

        & result[
            "exposure_start_date"
        ].notna()

        & result[
            "event_date"
        ].notna()
    )


    # Recover exposure end from actual event date.
    for index in result.index[
        experience_event_missing_end
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "exposure_end_date"
        ]


        # Use observed event date.
        new_value = result.at[
            index,
            "event_date"
        ]


        # Write reconstructed end date.
        result.at[

            index,

            "exposure_end_date"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "exposure_end_reconstructed_flag"

        ] = True


        # Audit recovery.
        log_cleaning_change(

            audit_rows,
            "claims_history",
            result.at[
                index,
                "claim_event_id"
            ],
            "exposure_end_date",
            old_value,
            new_value,
            "Recover",
            "Observed event date",
            "Exposure ends on observed decrement event",
        )


    # -------------------------------------------------------------------------
    # 34.2 — EXPERIENCE RECORDS WITHOUT EVENT DATE
    # -------------------------------------------------------------------------


    # Find Experience rows whose exposure end is still missing.
    remaining_exposure_end = (

        result[
            "product_type"
        ].eq("Experience")

        & result[
            "exposure_end_date"
        ].isna()

        & result[
            "exposure_start_date"
        ].notna()
    )


    # Calculate calendar year-end corresponding to exposure start.
    calendar_year_end = pd.to_datetime(

        result[
            "exposure_start_date"
        ].dt.year

        .astype(
            "Int64"
        )

        .astype(
            str
        )

        + "-12-31",

        errors="coerce"
    )


    # Exposure cannot extend beyond valuation date.
    exposure_cap = calendar_year_end.where(

        calendar_year_end
        <= VALUATION_DATE,

        VALUATION_DATE
    )


    # Map cleaned employee exit date into claims history.
    employee_exit_date = (

        result[
            "employee_id"
        ]

        .map(

            employee_clean
            .set_index(
                "employee_id"
            )[
                "exit_date"
            ]
        )
    )


    # If employee exits during the exposure period,
    # use the employee's exit date as the exposure cap.
    exposure_cap = exposure_cap.where(

        ~(

            employee_exit_date.notna()

            & (
                employee_exit_date

                >= result[
                    "exposure_start_date"
                ]
            )

            & (
                employee_exit_date

                < exposure_cap
            )
        ),

        employee_exit_date
    )


    # Reconstruct remaining exposure end dates.
    for index in result.index[
        remaining_exposure_end
    ]:


        # Capture old value.
        old_value = result.at[
            index,
            "exposure_end_date"
        ]


        # Use controlled exposure cap.
        new_value = exposure_cap.at[
            index
        ]


        # Write reconstructed end date.
        result.at[

            index,

            "exposure_end_date"

        ] = new_value


        # Flag reconstruction.
        result.at[

            index,

            "exposure_end_reconstructed_flag"

        ] = True


        # Audit reconstruction.
        log_cleaning_change(

            audit_rows,
            "claims_history",
            result.at[
                index,
                "claim_event_id"
            ],
            "exposure_end_date",
            old_value,
            new_value,
            "Reconstruct",
            (
                "Year-end / valuation / "
                "employee-exit cap"
            ),
            (
                "No observed event date "
                "was available"
            ),
        )


    # -------------------------------------------------------------------------
    # 34.3 — BUILD COMMON EXPERIENCE REFERENCE
    # -------------------------------------------------------------------------


    # Select valid common Experience event records.
    experience_reference = result.loc[

        result[
            "product_type"
        ].eq("Experience")

        & result[
            "event_date"
        ].notna(),

        [
            "employee_id",
            "event_date",
            "event_type",
            "exposure_start_date",
            "exposure_end_date",
        ]

    ].copy()


    # Keep one common reference for each employee event.
    experience_reference = (

        experience_reference
        .drop_duplicates([

            "employee_id",
            "event_date",
            "event_type",

        ])
    )


    # Rename exposure fields before joining.
    experience_reference = (

        experience_reference
        .rename(
            columns={

                "exposure_start_date":
                    "reference_start",

                "exposure_end_date":
                    "reference_end",
            }
        )
    )


    # Join common Experience reference to all product claims.
    result = result.merge(

        experience_reference,

        on=[
            "employee_id",
            "event_date",
            "event_type",
        ],

        how="left"
    )


    # -------------------------------------------------------------------------
    # 34.4 — IDENTIFY INVALID PRODUCT CLAIM EXPOSURE
    # -------------------------------------------------------------------------


    # Flag exposure ending before it starts.
    invalid_exposure = (

        result[
            "exposure_start_date"
        ].notna()

        & result[
            "exposure_end_date"
        ].notna()

        & (
            result[
                "exposure_end_date"
            ]

            < result[
                "exposure_start_date"
            ]
        )
    )


    # Also flag events occurring outside their recorded exposure period.
    invalid_exposure = (

        invalid_exposure

        | (

            result[
                "event_date"
            ].notna()

            & result[
                "exposure_start_date"
            ].notna()

            & result[
                "exposure_end_date"
            ].notna()

            & (

                (
                    result[
                        "event_date"
                    ]

                    < result[
                        "exposure_start_date"
                    ]
                )

                | (
                    result[
                        "event_date"
                    ]

                    > result[
                        "exposure_end_date"
                    ]
                )
            )
        )
    )


    # Use common Experience reference only for product-specific rows.
    recover_product_exposure = (

        invalid_exposure

        & ~result[
            "product_type"
        ].eq("Experience")

        & result[
            "reference_start"
        ].notna()

        & result[
            "reference_end"
        ].notna()
    )


    # Repair each product-specific exposure record.
    for index in result.index[
        recover_product_exposure
    ]:


        # Repair exposure start if necessary.
        if (

            result.at[
                index,
                "exposure_start_date"
            ]

            != result.at[
                index,
                "reference_start"
            ]
        ):


            # Capture old start date.
            old_value = result.at[
                index,
                "exposure_start_date"
            ]


            # Use common Experience start date.
            new_value = result.at[
                index,
                "reference_start"
            ]


            # Write recovered start date.
            result.at[

                index,

                "exposure_start_date"

            ] = new_value


            # Flag recovery.
            result.at[

                index,

                "exposure_start_reconstructed_flag"

            ] = True


            # Audit change.
            log_cleaning_change(

                audit_rows,
                "claims_history",
                result.at[
                    index,
                    "claim_event_id"
                ],
                "exposure_start_date",
                old_value,
                new_value,
                "Recover",
                "Matched Experience record",
                (
                    "Product claim exposure aligned "
                    "to common employee event record"
                ),
            )


        # Repair exposure end if necessary.
        if (

            result.at[
                index,
                "exposure_end_date"
            ]

            != result.at[
                index,
                "reference_end"
            ]
        ):


            # Capture old end date.
            old_value = result.at[
                index,
                "exposure_end_date"
            ]


            # Use common Experience end date.
            new_value = result.at[
                index,
                "reference_end"
            ]


            # Write recovered end date.
            result.at[

                index,

                "exposure_end_date"

            ] = new_value


            # Flag recovery.
            result.at[

                index,

                "exposure_end_reconstructed_flag"

            ] = True


            # Audit change.
            log_cleaning_change(

                audit_rows,
                "claims_history",
                result.at[
                    index,
                    "claim_event_id"
                ],
                "exposure_end_date",
                old_value,
                new_value,
                "Recover",
                "Matched Experience record",
                (
                    "Product claim exposure aligned "
                    "to common employee event record"
                ),
            )


    # -------------------------------------------------------------------------
    # 34.5 — CLAIM-AMOUNT GOVERNANCE
    # -------------------------------------------------------------------------


    # Convert claim amount to numeric form.
    claim_amount_numeric = pd.to_numeric(

        result[
            "claim_amount"
        ],

        errors="coerce"
    )


    # Identify Paid or Approved claims lacking a positive claim amount.
    unresolved_claim_amount = (

        result[
            "claim_status"
        ].isin([

            "Paid",

            "Approved",

        ])

        & (

            claim_amount_numeric.isna()

            | claim_amount_numeric.le(0)
        )
    )


    # Flag these claims rather than inventing a financial amount.
    result.loc[

        unresolved_claim_amount,

        "unresolved_claim_amount_flag"

    ] = True


    # -------------------------------------------------------------------------
    # 34.6 — MODEL-USABILITY FLAGS
    # -------------------------------------------------------------------------


    # Mark exposure records structurally usable for later experience modelling.
    result[
        "model_usable_exposure_flag"
    ] = (

        result[
            "exposure_start_date"
        ].notna()

        & result[
            "exposure_end_date"
        ].notna()

        & (
            result[
                "exposure_end_date"
            ]

            >= result[
                "exposure_start_date"
            ]
        )

        & (
            result[
                "exposure_end_date"
            ]

            <= VALUATION_DATE
        )
    )


    # Claim amount is usable unless it is one of our unresolved records.
    result[
        "model_usable_claim_amount_flag"
    ] = (

        ~result[
            "unresolved_claim_amount_flag"
        ]
    )


    # Remove temporary reference columns.
    result = result.drop(

        columns=[

            "reference_start",

            "reference_end",
        ]
    )


    # Return cleaned claims/exposure history.
    return result


# =============================================================================
# SECTION 35 — BUILD UNRESOLVED EXCEPTION REGISTER
# =============================================================================


# Define a function that keeps problems we intentionally did NOT fabricate away.
def build_unresolved_exceptions(
    employee_clean,
    salary_clean,
    claims_clean,
):


    # Create an empty list of unresolved issues.
    unresolved_rows = []


    # -------------------------------------------------------------------------
    # 35.1 — CRITICAL EMPLOYEE FIELDS
    # -------------------------------------------------------------------------


    # Define employee fields required by later actuarial modelling.
    critical_employee_fields = [

        "date_of_birth",

        "date_of_joining",

        "basic_salary_monthly",

        "eligible_gratuity_wages_monthly",

        "pensionable_salary_annual",

        "gross_compensation_annual",
    ]


    # Check every critical field.
    for column in critical_employee_fields:


        # Find remaining missing values.
        missing_records = employee_clean.loc[

            employee_clean[
                column
            ].isna(),

            [
                "employee_id"
            ]
        ]


        # Add every unresolved employee to exception register.
        for row in missing_records.itertuples():


            unresolved_rows.append({

                "dataset":
                    "employee_census",

                "record_key":
                    row.employee_id,

                "issue":
                    f"missing_{column}",

                "severity":
                    "High",

                "note":
                    (
                        "Critical model input remains "
                        "missing after cleaning"
                    ),
            })


    # -------------------------------------------------------------------------
    # 35.2 — ACTIVE EMPLOYEE PAST RECORDED RETIREMENT AGE
    # -------------------------------------------------------------------------


    # Calculate attained age.
    attained_age = (

        (
            VALUATION_DATE

            - employee_clean[
                "date_of_birth"
            ]
        ).dt.days

        / 365.25
    )


    # Convert Retirement Age into numeric form.
    retirement_age = pd.to_numeric(

        employee_clean[
            "retirement_age"
        ],

        errors="coerce"
    )


    # Find employees still Active materially beyond recorded retirement age.
    active_past_retirement = (

        employee_clean[
            "employment_status"
        ].eq("Active")

        & attained_age.notna()

        & retirement_age.notna()

        & (

            attained_age

            > (
                retirement_age
                + QA_RETIREMENT_TOLERANCE_YEARS
            )
        )
    )


    # Preserve these for review rather than automatically retiring them.
    for row in employee_clean.loc[

        active_past_retirement,

        [
            "employee_id"
        ]

    ].itertuples():


        unresolved_rows.append({

            "dataset":
                "employee_census",

            "record_key":
                row.employee_id,

            "issue":
                "active_past_recorded_retirement_age",

            "severity":
                "Review",

            "note":
                (
                    "Do not auto-retire; confirm extension, "
                    "stale status or applicable retirement rule"
                ),
        })


    # -------------------------------------------------------------------------
    # 35.3 — UNRESOLVED PLAN IDS
    # -------------------------------------------------------------------------


    # Define membership field and corresponding required plan ID.
    required_plan_ids = [

        (
            "gratuity_member_flag",
            "gratuity_plan_id",
        ),

        (
            "superannuation_member_flag",
            "superannuation_plan_id",
        ),

        (
            "gti_member_flag",
            "gti_plan_id",
        ),
    ]


    # Check each product.
    for (
        member_column,
        plan_column
    ) in required_plan_ids:


        # Find members still missing plan ID.
        missing_plan = (

            employee_clean[
                member_column
            ].eq("Yes")

            & employee_clean[
                plan_column
            ].isna()
        )


        # Add unresolved plan IDs.
        for row in employee_clean.loc[

            missing_plan,

            [
                "employee_id"
            ]

        ].itertuples():


            unresolved_rows.append({

                "dataset":
                    "employee_census",

                "record_key":
                    row.employee_id,

                "issue":
                    f"unresolved_{plan_column}",

                "severity":
                    "High",

                "note":
                    (
                        "Plan ID required "
                        "before product valuation"
                    ),
            })


    # -------------------------------------------------------------------------
    # 35.4 — LARGE SALARY MOVEMENTS
    # -------------------------------------------------------------------------


    # Preserve large historical salary movements for review.
    unusual_salary_movement = salary_clean[
        "unresolved_large_salary_movement_flag"
    ]


    # Add each movement to exception register.
    for row in salary_clean.loc[

        unusual_salary_movement,

        [
            "employee_id",
            "effective_date",
        ]

    ].itertuples():


        unresolved_rows.append({

            "dataset":
                "salary_history",

            "record_key":
                (
                    f"{row.employee_id}"
                    "|"
                    f"{row.effective_date.date()}"
                ),

            "issue":
                "large_year_on_year_salary_movement",

            "severity":
                "Review",

            "note":
                (
                    "Preserved rather than winsorized; "
                    "verify promotion, correction or genuine pay movement"
                ),
        })


    # -------------------------------------------------------------------------
    # 35.5 — UNRESOLVED CLAIM AMOUNTS
    # -------------------------------------------------------------------------


    # Find Paid/Approved claims without valid positive amounts.
    unresolved_claim_amount = claims_clean[
        "unresolved_claim_amount_flag"
    ]


    # Add each claim to exception register.
    for row in claims_clean.loc[

        unresolved_claim_amount,

        [
            "claim_event_id"
        ]

    ].itertuples():


        unresolved_rows.append({

            "dataset":
                "claims_history",

            "record_key":
                row.claim_event_id,

            "issue":
                (
                    "paid_or_approved_claim_"
                    "without_positive_amount"
                ),

            "severity":
                "High",

            "note":
                (
                    "Claim amount not fabricated; "
                    "exclude from severity analysis until resolved"
                ),
        })


    # -------------------------------------------------------------------------
    # 35.6 — UNUSABLE EXPOSURE
    # -------------------------------------------------------------------------


    # Find any claims/exposure rows that remain structurally unusable.
    unusable_exposure = (

        ~claims_clean[
            "model_usable_exposure_flag"
        ]
    )


    # Add any remaining unusable exposure records.
    for row in claims_clean.loc[

        unusable_exposure,

        [
            "claim_event_id"
        ]

    ].itertuples():


        unresolved_rows.append({

            "dataset":
                "claims_history",

            "record_key":
                row.claim_event_id,

            "issue":
                "unusable_exposure_period",

            "severity":
                "High",

            "note":
                (
                    "Exposure remains invalid "
                    "after reconstruction"
                ),
        })


    # Convert unresolved issues into DataFrame.
    unresolved = pd.DataFrame(

        unresolved_rows,

        columns=[

            "dataset",

            "record_key",

            "issue",

            "severity",

            "note",
        ]
    )


    # Return unresolved exception register.
    return unresolved


# =============================================================================
# SECTION 36 — POST-CLEANING VALIDATION
# =============================================================================


# Define a function that proves whether cleaning actually resolved
# the structural problems we intended to fix.
def build_post_cleaning_validation(
    employee_clean,
    salary_clean,
    claims_clean,
    plan_assets_clean,
    plan_rules_clean,
):


    # Create empty validation result list.
    validation_rows = []


    # Define a helper for adding one validation result.
    def add_validation(
        check,
        exceptions,
        review_only=False,
        note="",
    ):


        # Convert exception count to ordinary integer.
        exception_count = int(
            exceptions
        )


        # A review-only item becomes REVIEW rather than FAIL.
        if (
            review_only
            and exception_count > 0
        ):

            status = "REVIEW"


        # Zero exceptions means PASS.
        elif exception_count == 0:

            status = "PASS"


        # Any other exception is a failure.
        else:

            status = "FAIL"


        # Store validation result.
        validation_rows.append({

            "check":
                check,

            "exceptions":
                exception_count,

            "status":
                status,

            "note":
                note,
        })


    # -------------------------------------------------------------------------
    # EMPLOYEE CHECKS
    # -------------------------------------------------------------------------


    # Confirm one unique row per employee.
    add_validation(

        "employee_id unique",

        employee_clean[
            "employee_id"
        ].duplicated().sum(),

        note=(
            "One row per employee "
            "after duplicate resolution"
        ),
    )


    # Define critical model-input fields.
    critical_fields = [

        "date_of_birth",

        "date_of_joining",

        "basic_salary_monthly",

        "eligible_gratuity_wages_monthly",

        "pensionable_salary_annual",

        "gross_compensation_annual",
    ]


    # Confirm critical employee fields are complete.
    add_validation(

        "critical employee fields complete",

        employee_clean[
            critical_fields
        ].isna().any(
            axis=1
        ).sum(),
    )


    # Recalculate joining age.
    joining_age = (

        (
            employee_clean[
                "date_of_joining"
            ]

            - employee_clean[
                "date_of_birth"
            ]
        ).dt.days

        / 365.25
    )


    # Confirm reconstructed joining ages fall within QA range.
    add_validation(

        "joining age within QA range",

        (

            (
                joining_age
                < QA_MIN_JOINING_AGE
            )

            | (
                joining_age
                > QA_MAX_JOINING_AGE
            )

            | joining_age.isna()

        ).sum(),
    )


    # Active employees should not have exit dates.
    add_validation(

        "active employee has no exit date",

        (

            employee_clean[
                "employment_status"
            ].eq("Active")

            & employee_clean[
                "exit_date"
            ].notna()

        ).sum(),
    )


    # Non-active employees should have an exit date.
    add_validation(

        "non-active employee has exit date",

        (

            ~employee_clean[
                "employment_status"
            ].eq("Active")

            & employee_clean[
                "exit_date"
            ].isna()

        ).sum(),
    )


    # Define expected reason from status.
    expected_reason = (

        employee_clean[
            "employment_status"
        ]

        .map({

            "Exited":
                "Withdrawal",

            "Retired":
                "Retirement",

            "Early Retired":
                "Early Retirement",

            "Deceased":
                "Death",

            "Disabled":
                "Disability",
        })
    )


    # Confirm exit reason agrees with status.
    add_validation(

        "status and exit reason agree",

        (

            expected_reason.notna()

            & employee_clean[
                "exit_reason"
            ].notna()

            & (
                expected_reason

                != employee_clean[
                    "exit_reason"
                ]
            )

        ).sum(),
    )


    # Confirm all Gratuity members have plan IDs.
    add_validation(

        "gratuity members have plan ID",

        (

            employee_clean[
                "gratuity_member_flag"
            ].eq("Yes")

            & employee_clean[
                "gratuity_plan_id"
            ].isna()

        ).sum(),
    )


    # Confirm all Superannuation members have plan IDs.
    add_validation(

        "superannuation members have plan ID",

        (

            employee_clean[
                "superannuation_member_flag"
            ].eq("Yes")

            & employee_clean[
                "superannuation_plan_id"
            ].isna()

        ).sum(),
    )


    # Confirm all GTI members have plan IDs.
    add_validation(

        "GTI members have plan ID",

        (

            employee_clean[
                "gti_member_flag"
            ].eq("Yes")

            & employee_clean[
                "gti_plan_id"
            ].isna()

        ).sum(),
    )


    # Confirm EDLI eligibility is consistent with PF membership.
    add_validation(

        "EDLI eligibility consistent with PF membership",

        (

            ~employee_clean[
                "pf_member_flag"
            ].eq("Yes")

            & employee_clean[
                "edli_eligible_flag"
            ].eq("Yes")

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # SALARY-HISTORY CHECKS
    # -------------------------------------------------------------------------


    # Define core historical salary fields.
    salary_core_fields = [

        "basic_salary_monthly",

        "gratuity_eligible_wages_monthly",

        "pensionable_salary_annual",

        "edli_eligible_wages_monthly",
    ]


    # Convert core salary fields to numeric.
    salary_core_numeric = (

        salary_clean[
            salary_core_fields
        ]

        .apply(
            pd.to_numeric,
            errors="coerce"
        )
    )


    # Confirm core salary history is complete and positive.
    add_validation(

        "salary history core fields complete and positive",

        (

            salary_core_numeric
            .isna()
            .any(
                axis=1
            )

            | (
                salary_core_numeric
                <= 0
            ).any(
                axis=1
            )

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # CLAIMS / EXPOSURE CHECKS
    # -------------------------------------------------------------------------


    # Confirm every exposure record is now structurally usable.
    add_validation(

        "claims exposure periods usable",

        (

            ~claims_clean[
                "model_usable_exposure_flag"
            ]

        ).sum(),
    )


    # Claim amount issue remains REVIEW rather than fabrication.
    add_validation(

        "paid/approved claim amounts resolved",

        claims_clean[
            "unresolved_claim_amount_flag"
        ].sum(),

        review_only=True,

        note=(
            "Unresolved claim amounts "
            "are intentionally not fabricated"
        ),
    )


    # -------------------------------------------------------------------------
    # PLAN-ASSET CHECK
    # -------------------------------------------------------------------------


    # Independently recalculate closing plan assets.
    calculated_closing_assets = (

        plan_assets_clean[
            "opening_plan_assets"
        ]

        + plan_assets_clean[
            "employer_contributions"
        ]

        + plan_assets_clean[
            "employee_contributions"
        ]

        + plan_assets_clean[
            "investment_income"
        ]

        - plan_assets_clean[
            "benefits_paid"
        ]

        - plan_assets_clean[
            "expenses_charges"
        ]
    )


    # Confirm Plan Assets still reconcile after pipeline processing.
    add_validation(

        "plan assets reconcile",

        (

            (

                plan_assets_clean[
                    "closing_plan_assets"
                ]

                - calculated_closing_assets

            ).abs()

            >= 0.01

        ).sum(),
    )


    # Confirm plan-rule IDs remain unique.
    add_validation(

        "plan rule IDs unique",

        plan_rules_clean[
            "rule_id"
        ].duplicated().sum(),
    )


    # Convert all validation results into one table.
    return pd.DataFrame(
        validation_rows
    )


# =============================================================================
# SECTION 37 — BUILD CLEANING SUMMARY
# =============================================================================


# Define a function that creates an executive summary of Pipeline 03.
def build_cleaning_summary(
    raw_data,
    employee_clean,
    salary_clean,
    claims_clean,
    audit_log,
    unresolved,
):


    # Create an empty list.
    summary_rows = []


    # Define a small helper for adding summary metrics.
    def add_metric(
        dataset,
        metric,
        value,
    ):


        # Append one summary row.
        summary_rows.append({

            "dataset":
                dataset,

            "metric":
                metric,

            "value":
                int(value),
        })


    # -------------------------------------------------------------------------
    # EMPLOYEE COUNTS
    # -------------------------------------------------------------------------


    # Record original census rows.
    add_metric(

        "employee_census",

        "raw_rows",

        len(
            raw_data[
                "employee"
            ]
        ),
    )


    # Record cleaned unique employee rows.
    add_metric(

        "employee_census",

        "clean_rows",

        len(
            employee_clean
        ),
    )


    # Record duplicate rows removed.
    add_metric(

        "employee_census",

        "duplicate_rows_removed",

        (
            len(
                raw_data[
                    "employee"
                ]
            )

            - len(
                employee_clean
            )
        ),
    )


    # List employee cleaning flags we want summarized.
    employee_flags = [

        "date_of_birth_imputed_flag",

        "date_of_joining_reconstructed_flag",

        "exit_date_reconstructed_flag",

        "employment_status_reconciled_flag",

        "exit_reason_reconciled_flag",

        "basic_salary_reconstructed_flag",

        "gratuity_wage_reconstructed_flag",

        "pensionable_salary_reconstructed_flag",

        "gross_compensation_reconstructed_flag",

        "gratuity_plan_id_imputed_flag",

        "superannuation_plan_id_imputed_flag",

        "gti_plan_id_reconstructed_flag",

        "edli_eligibility_reconciled_flag",
    ]


    # Add counts for every employee cleaning flag.
    for flag in employee_flags:

        add_metric(

            "employee_census",

            flag,

            employee_clean[
                flag
            ].sum(),
        )


    # -------------------------------------------------------------------------
    # SALARY-HISTORY COUNTS
    # -------------------------------------------------------------------------


    # List salary reconstruction flags.
    salary_flags = [

        "basic_salary_reconstructed_flag",

        "gratuity_wage_reconstructed_flag",

        "pensionable_salary_reconstructed_flag",

        "edli_wage_reconstructed_flag",

        "unresolved_large_salary_movement_flag",
    ]


    # Add salary-history counts.
    for flag in salary_flags:

        add_metric(

            "salary_history",

            flag,

            salary_clean[
                flag
            ].sum(),
        )


    # -------------------------------------------------------------------------
    # CLAIMS COUNTS
    # -------------------------------------------------------------------------


    # List claims reconstruction/review flags.
    claims_flags = [

        "exposure_start_reconstructed_flag",

        "exposure_end_reconstructed_flag",

        "unresolved_claim_amount_flag",
    ]


    # Add claim counts.
    for flag in claims_flags:

        add_metric(

            "claims_history",

            flag,

            claims_clean[
                flag
            ].sum(),
        )


    # Add total number of audit changes.
    add_metric(

        "governance",

        "audit_log_records",

        len(
            audit_log
        ),
    )


    # Add total unresolved review items.
    add_metric(

        "governance",

        "unresolved_exception_records",

        len(
            unresolved
        ),
    )


    # Convert list into DataFrame.
    return pd.DataFrame(
        summary_rows
    )


# =============================================================================
# SECTION 38 — PIPELINE 03 CONTROLLER
# =============================================================================


# Define the main Pipeline 03 execution function.
def run_pipeline_03(
    data,
    eda_results,
):


    # Print visual separator.
    print(
        "\n"
        + "=" * 72
    )


    # Print Pipeline 03 title.
    print(
        "PIPELINE 03 - "
        "CONTROLLED CLEANING & RECONSTRUCTION"
    )


    # Print valuation date.
    print(
        f"Valuation date: "
        f"{VALUATION_DATE.date()}"
    )


    # Print methodology version.
    print(
        f"Cleaning version: "
        f"{CLEANING_VERSION}"
    )


    # Print closing header separator.
    print(
        "=" * 72
    )


    # Create an empty audit-log list.
    audit_rows = []


    # -------------------------------------------------------------------------
    # STEP 38.1 — RESOLVE EMPLOYEE DUPLICATES
    # -------------------------------------------------------------------------


    # Reduce employee master to one controlled row per employee.
    employee_clean = resolve_employee_duplicates(

        data[
            "employee"
        ],

        audit_rows
    )


    # -------------------------------------------------------------------------
    # STEP 38.2 — CLEAN SALARY HISTORY
    # -------------------------------------------------------------------------


    # Reconstruct recoverable historical salary fields first.
    #
    # We clean history before current salary because current salary
    # may legitimately use employee-specific historical information.
    salary_clean = clean_salary_history(

        data[
            "salary"
        ],

        audit_rows
    )


    # -------------------------------------------------------------------------
    # STEP 38.3 — CLEAN EMPLOYEE DATES AND STATUS
    # -------------------------------------------------------------------------


    # Reconcile DOB, DOJ, exit dates, employment status and exit reason.
    employee_clean = (
        clean_employee_dates_and_status(

            employee_clean,

            data[
                "claims"
            ],

            salary_clean,

            audit_rows
        )
    )


    # -------------------------------------------------------------------------
    # STEP 38.4 — CLEAN CURRENT EMPLOYEE SALARY
    # -------------------------------------------------------------------------


    # Reconstruct current compensation fields using
    # internal consistency and own salary history.
    employee_clean = clean_employee_salary(

        employee_clean,

        salary_clean,

        audit_rows
    )


    # -------------------------------------------------------------------------
    # STEP 38.5 — CLEAN PRODUCT MEMBERSHIP
    # -------------------------------------------------------------------------


    # Reconcile missing plan IDs and PF/EDLI consistency.
    employee_clean = clean_employee_membership(

        employee_clean,

        audit_rows
    )


    # -------------------------------------------------------------------------
    # STEP 38.6 — CLEAN CLAIMS AND EXPOSURE
    # -------------------------------------------------------------------------


    # Repair recoverable exposure periods.
    claims_clean = clean_claims_history(

        data[
            "claims"
        ],

        employee_clean,

        audit_rows
    )


    # -------------------------------------------------------------------------
    # STEP 38.7 — PLAN ASSETS AND PLAN RULES
    # -------------------------------------------------------------------------


    # Pipeline 02 found no Plan Asset continuity defects.
    #
    # Therefore preserve the validated values exactly as observed.
    plan_assets_clean = (

        data[
            "assets"
        ].copy()
    )


    # Pipeline 02 found no Plan Rule defects.
    #
    # Therefore preserve the validated rule table exactly as observed.
    plan_rules_clean = (

        data[
            "rules"
        ].copy()
    )


    # -------------------------------------------------------------------------
    # STEP 38.8 — BUILD UNRESOLVED EXCEPTION REGISTER
    # -------------------------------------------------------------------------


    # Keep unresolved review items visible rather than silently fabricating them.
    unresolved = build_unresolved_exceptions(

        employee_clean,

        salary_clean,

        claims_clean
    )


    # -------------------------------------------------------------------------
    # STEP 38.9 — CREATE CHANGE / REVIEW FLAGS
    # -------------------------------------------------------------------------


    # Define employee fields that indicate an actual cleaning change.
    employee_change_flags = [

        "duplicate_resolved_flag",

        "date_of_birth_imputed_flag",

        "date_of_joining_reconstructed_flag",

        "exit_date_reconstructed_flag",

        "employment_status_reconciled_flag",

        "exit_reason_reconciled_flag",

        "basic_salary_reconstructed_flag",

        "gratuity_wage_reconstructed_flag",

        "pensionable_salary_reconstructed_flag",

        "gross_compensation_reconstructed_flag",

        "gratuity_plan_id_imputed_flag",

        "superannuation_plan_id_imputed_flag",

        "gti_plan_id_reconstructed_flag",

        "edli_eligibility_reconciled_flag",
    ]


    # Flag every employee whose processed record differs from raw input.
    employee_clean[
        "cleaning_any_change_flag"
    ] = (

        employee_clean[
            employee_change_flags
        ].any(
            axis=1
        )
    )


    # Define salary-history change fields.
    salary_change_flags = [

        "basic_salary_reconstructed_flag",

        "gratuity_wage_reconstructed_flag",

        "pensionable_salary_reconstructed_flag",

        "edli_wage_reconstructed_flag",
    ]


    # Flag salary-history rows actually changed.
    salary_clean[
        "cleaning_any_change_flag"
    ] = (

        salary_clean[
            salary_change_flags
        ].any(
            axis=1
        )
    )


    # Define claims reconstruction fields.
    claims_change_flags = [

        "exposure_start_reconstructed_flag",

        "exposure_end_reconstructed_flag",
    ]


    # Flag claims/exposure rows actually changed.
    claims_clean[
        "cleaning_any_change_flag"
    ] = (

        claims_clean[
            claims_change_flags
        ].any(
            axis=1
        )
    )


    # -------------------------------------------------------------------------
    # STEP 38.10 — MAP UNRESOLVED REVIEW ITEMS BACK TO DATA
    # -------------------------------------------------------------------------


    # Build employee IDs requiring review.
    employee_review_ids = set(

        unresolved.loc[

            unresolved[
                "dataset"
            ].eq(
                "employee_census"
            ),

            "record_key"

        ].astype(
            str
        )
    )


    # Flag employee records requiring review.
    employee_clean[
        "cleaning_review_flag"
    ] = (

        employee_clean[
            "employee_id"
        ]
        .astype(
            str
        )
        .isin(
            employee_review_ids
        )
    )


    # Build salary-history review keys.
    salary_review_keys = set(

        unresolved.loc[

            unresolved[
                "dataset"
            ].eq(
                "salary_history"
            ),

            "record_key"

        ].astype(
            str
        )
    )


    # Create corresponding key for every salary-history row.
    salary_record_key = (

        salary_clean[
            "employee_id"
        ].astype(
            str
        )

        + "|"

        + salary_clean[
            "effective_date"
        ].dt.date.astype(
            str
        )
    )


    # Flag salary-history records requiring review.
    salary_clean[
        "cleaning_review_flag"
    ] = (

        salary_record_key
        .isin(
            salary_review_keys
        )
    )


    # Build claims IDs requiring review.
    claim_review_ids = set(

        unresolved.loc[

            unresolved[
                "dataset"
            ].eq(
                "claims_history"
            ),

            "record_key"

        ].astype(
            str
        )
    )


    # Flag claims requiring review.
    claims_clean[
        "cleaning_review_flag"
    ] = (

        claims_clean[
            "claim_event_id"
        ]
        .astype(
            str
        )
        .isin(
            claim_review_ids
        )
    )


    # -------------------------------------------------------------------------
    # STEP 38.11 — CREATE AUDIT LOG
    # -------------------------------------------------------------------------


    # Convert accumulated audit records into a DataFrame.
    audit_log = pd.DataFrame(
        audit_rows
    )


    # -------------------------------------------------------------------------
    # STEP 38.12 — POST-CLEANING VALIDATION
    # -------------------------------------------------------------------------


    # Revalidate all major structural controls after cleaning.
    post_cleaning_validation = (
        build_post_cleaning_validation(

            employee_clean,

            salary_clean,

            claims_clean,

            plan_assets_clean,

            plan_rules_clean
        )
    )


    # -------------------------------------------------------------------------
    # STEP 38.13 — CLEANING SUMMARY
    # -------------------------------------------------------------------------


    # Build concise cleaning statistics.
    cleaning_summary = build_cleaning_summary(

        data,

        employee_clean,

        salary_clean,

        claims_clean,

        audit_log,

        unresolved
    )


    # -------------------------------------------------------------------------
    # STEP 38.14 — SAVE PROCESSED DATASETS
    # -------------------------------------------------------------------------


    # Save cleaned employee census.
    employee_clean.to_csv(

        PROCESSED_DATA_DIR
        / "employee_census_clean.csv",

        index=False
    )


    # Save cleaned salary history.
    salary_clean.to_csv(

        PROCESSED_DATA_DIR
        / "salary_history_clean.csv",

        index=False
    )


    # Save cleaned claims history.
    claims_clean.to_csv(

        PROCESSED_DATA_DIR
        / "claims_history_clean.csv",

        index=False
    )


    # Save validated Plan Assets unchanged.
    plan_assets_clean.to_csv(

        PROCESSED_DATA_DIR
        / "plan_assets_clean.csv",

        index=False
    )


    # Save validated Plan Rules unchanged.
    plan_rules_clean.to_csv(

        PROCESSED_DATA_DIR
        / "plan_rules_assumptions_clean.csv",

        index=False
    )


    # -------------------------------------------------------------------------
    # STEP 38.15 — SAVE GOVERNANCE REPORTS
    # -------------------------------------------------------------------------


    # Save complete field-level cleaning audit.
    audit_log.to_csv(

        CLEANING_OUTPUT_DIR
        / "cleaning_audit_log.csv",

        index=False
    )


    # Save summary of cleaning actions.
    cleaning_summary.to_csv(

        CLEANING_OUTPUT_DIR
        / "cleaning_summary.csv",

        index=False
    )


    # Save unresolved exception register.
    unresolved.to_csv(

        CLEANING_OUTPUT_DIR
        / "unresolved_exceptions.csv",

        index=False
    )


    # Save post-cleaning validation results.
    post_cleaning_validation.to_csv(

        CLEANING_OUTPUT_DIR
        / "post_cleaning_validation.csv",

        index=False
    )


    # -------------------------------------------------------------------------
    # STEP 38.16 — CREATE PROCESSED DATASET MANIFEST
    # -------------------------------------------------------------------------


    # Build a compact processed-data inventory.
    processed_manifest = pd.DataFrame([


        {
            "dataset":
                "employee_census_clean.csv",

            "rows":
                len(
                    employee_clean
                ),

            "columns":
                employee_clean.shape[1],

            "status":
                "Cleaned + audit flags",
        },


        {
            "dataset":
                "salary_history_clean.csv",

            "rows":
                len(
                    salary_clean
                ),

            "columns":
                salary_clean.shape[1],

            "status":
                "Cleaned + audit flags",
        },


        {
            "dataset":
                "claims_history_clean.csv",

            "rows":
                len(
                    claims_clean
                ),

            "columns":
                claims_clean.shape[1],

            "status":
                "Cleaned + audit flags",
        },


        {
            "dataset":
                "plan_assets_clean.csv",

            "rows":
                len(
                    plan_assets_clean
                ),

            "columns":
                plan_assets_clean.shape[1],

            "status":
                "Validated; values unchanged",
        },


        {
            "dataset":
                "plan_rules_assumptions_clean.csv",

            "rows":
                len(
                    plan_rules_clean
                ),

            "columns":
                plan_rules_clean.shape[1],

            "status":
                "Validated; values unchanged",
        },
    ])


    # Save manifest.
    processed_manifest.to_csv(

        CLEANING_OUTPUT_DIR
        / "processed_dataset_manifest.csv",

        index=False
    )


    # -------------------------------------------------------------------------
    # STEP 38.17 — TERMINAL SUMMARY
    # -------------------------------------------------------------------------


    # Print heading.
    print(
        "\nCleaning results"
    )


    # Print raw versus cleaned employee row counts.
    print(

        f"  Employee rows:                         "
        f"{len(data['employee']):,} -> "
        f"{len(employee_clean):,}"
    )


    # Print number of duplicate rows removed.
    print(

        f"  Duplicate rows removed:                "
        f"{len(data['employee']) - len(employee_clean):,}"
    )


    # Print DOB imputation count.
    print(

        f"  DOB values imputed:                    "
        f"{employee_clean['date_of_birth_imputed_flag'].sum():,}"
    )


    # Print DOJ reconstruction count.
    print(

        f"  DOJ values reconstructed:              "
        f"{employee_clean['date_of_joining_reconstructed_flag'].sum():,}"
    )


    # Print recovered exit dates.
    print(

        f"  Exit dates recovered:                  "
        f"{employee_clean['exit_date_reconstructed_flag'].sum():,}"
    )


    # Print reconciled employment statuses.
    print(

        f"  Employment statuses reconciled:        "
        f"{employee_clean['employment_status_reconciled_flag'].sum():,}"
    )


    # Print current Basic Salary reconstruction count.
    print(

        f"  Current Basic Salaries reconstructed:  "
        f"{employee_clean['basic_salary_reconstructed_flag'].sum():,}"
    )


    # Print historical Basic Salary reconstruction count.
    print(

        f"  Historical Basic Salaries repaired:    "
        f"{salary_clean['basic_salary_reconstructed_flag'].sum():,}"
    )


    # Print exposure-start reconstruction count.
    print(

        f"  Exposure starts reconstructed:         "
        f"{claims_clean['exposure_start_reconstructed_flag'].sum():,}"
    )


    # Print exposure-end reconstruction count.
    print(

        f"  Exposure ends reconstructed:           "
        f"{claims_clean['exposure_end_reconstructed_flag'].sum():,}"
    )


    # Print total audit records.
    print(

        f"  Cleaning audit records:                "
        f"{len(audit_log):,}"
    )


    # Print unresolved review items.
    print(

        f"  Unresolved/review items:               "
        f"{len(unresolved):,}"
    )


    # Count failed post-cleaning controls.
    post_clean_failures = (

        post_cleaning_validation[
            "status"
        ]
        .eq(
            "FAIL"
        )
        .sum()
    )


    # Count review-only controls.
    post_clean_reviews = (

        post_cleaning_validation[
            "status"
        ]
        .eq(
            "REVIEW"
        )
        .sum()
    )


    # Print validation result.
    print(

        f"\nPost-cleaning validation failures:       "
        f"{post_clean_failures}"
    )


    # Print review count.
    print(

        f"Post-cleaning validation reviews:        "
        f"{post_clean_reviews}"
    )


    # Tell user where cleaned datasets were stored.
    print(

        f"\nProcessed datasets written to:\n"
        f"{PROCESSED_DATA_DIR}"
    )


    # Tell user where audit reports were stored.
    print(

        f"\nCleaning reports written to:\n"
        f"{CLEANING_OUTPUT_DIR}"
    )


    # Confirm Pipeline 03 completion.
    print(

        "\nPipeline 03 complete."
        "\nRaw CSV files remain unchanged."
        "\nAll reconstructed/imputed values are explicitly flagged.\n"
    )


    # -------------------------------------------------------------------------
    # STEP 38.18 — RETURN CLEANED DATA
    # -------------------------------------------------------------------------


    # Create a clean-data dictionary matching our original dataset structure.
    clean_data = {

        "employee":
            employee_clean,

        "salary":
            salary_clean,

        "claims":
            claims_clean,

        "assets":
            plan_assets_clean,

        "rules":
            plan_rules_clean,
    }


    # Return all important Pipeline 03 outputs.
    return {

        "clean_data":
            clean_data,

        "audit_log":
            audit_log,

        "cleaning_summary":
            cleaning_summary,

        "unresolved":
            unresolved,

        "post_cleaning_validation":
            post_cleaning_validation,

        "processed_manifest":
            processed_manifest,
    }

# =============================================================================
