FEATURE_VERSION = "P04-C01"


# Use 365.25 days as the project convention for converting elapsed
# calendar days into approximate fractional years.
#
# The .25 allows approximately for leap years over long durations.
ACTUARIAL_YEAR_DAYS = 365.25


# Create a dedicated Pipeline 04 output folder.
