# =============================================================================
# SECTION 40 — SEGMENTATION DEFINITIONS
# =============================================================================


# -----------------------------------------------------------------------------
# AGE BANDS
# -----------------------------------------------------------------------------
#
# These categories are descriptive segmentation definitions.
#
# They are NOT mortality assumptions and do not change employee age.
# -----------------------------------------------------------------------------


# Define numerical boundaries for age segmentation.
AGE_BINS = [

    # Negative infinity captures anything below age 25.
    -np.inf,

    # Age 25 begins the second category.
    25,

    # Age 35 begins the third category.
    35,

    # Age 45 begins the fourth category.
    45,

    # Age 55 begins the fifth category.
    55,

    # Age 60 begins the final category.
    60,

    # Positive infinity captures every age 60 and above.
    np.inf,
]


# Define human-readable labels corresponding to AGE_BINS.
AGE_LABELS = [

    "<25",

    "25-34",

    "35-44",

    "45-54",

    "55-59",

    "60+",
]


# -----------------------------------------------------------------------------
# SERVICE BANDS
# -----------------------------------------------------------------------------


# Define completed-service segmentation boundaries.
SERVICE_BINS = [

    -np.inf,

    1,

    5,

    10,

    20,

    30,

    np.inf,
]


# Define readable service labels.
SERVICE_LABELS = [

    "<1",

    "1-4",

    "5-9",

    "10-19",

    "20-29",

    "30+",
]


# -----------------------------------------------------------------------------
# ANNUAL GROSS-COMPENSATION BANDS
# -----------------------------------------------------------------------------
#
# Values are expressed in Indian rupees.
#
# L = lakh = 100,000 rupees.
# -----------------------------------------------------------------------------


# Define annual gross-compensation boundaries.
SALARY_BINS = [

    -np.inf,

    500_000,

    1_000_000,

    2_000_000,

    4_000_000,

    6_000_000,

    np.inf,
]


# Define readable salary-band labels.
SALARY_LABELS = [

    "<5L",

    "5L-10L",

    "10L-20L",

    "20L-40L",

    "40L-60L",

    "60L+",
]


# -----------------------------------------------------------------------------
# SMALL SEGMENT REVIEW THRESHOLD
# -----------------------------------------------------------------------------
#
# This is NOT formal actuarial credibility.
#
# It is only a model-governance warning telling us that a descriptive
# segment contains relatively few employees and should not automatically
# receive its own standalone risk assumption.
# -----------------------------------------------------------------------------


# Flag descriptive segments containing fewer than 30 employees.
MIN_SEGMENT_REVIEW_COUNT = 30


# =============================================================================
# SECTION 41 — SAFE DATE-TO-YEAR HELPER
# =============================================================================


# Define a reusable helper that converts elapsed days into fractional years.
def years_between(
    later_date,
    earlier_date,
):


    # Subtract the earlier date from the later date.
    elapsed_days = (

        later_date

        - earlier_date

    ).dt.days


    # Convert elapsed days into approximate fractional years.
    elapsed_years = (

        elapsed_days

        / ACTUARIAL_YEAR_DAYS
    )


    # Return the fractional-year result.
    return elapsed_years


# =============================================================================
# SECTION 42 — SAFE RETIREMENT-DATE HELPER
# =============================================================================


# Define a helper that adds an employee-specific number of whole years
# to a date while safely handling 29 February birthdays.
def add_years_safe(
    date_value,
    years_value,
):


    # If either the date or retirement age is missing,
    # no retirement date can be derived.
    if (
        pd.isna(date_value)
        or pd.isna(years_value)
    ):

        return pd.NaT


    # Convert retirement age to an integer number of years.
    years_integer = int(
        round(
            float(
                years_value
            )
        )
    )


    # Calculate the target retirement year.
    target_year = (

        date_value.year

        + years_integer
    )


    # Try to retain the same month and day.
    try:

        return date_value.replace(
            year=target_year
        )


    # 29 February does not exist in every year.
    #
    # If replacing the year creates an invalid leap-day date,
    # use 28 February in the target year.
    except ValueError:

        return date_value.replace(

            year=target_year,

            month=2,

            day=28
        )


# =============================================================================
# SECTION 43 — EMPLOYEE ACTUARIAL FEATURE ENGINE
# =============================================================================


# Define the function that converts the cleaned employee census
# into the common actuarial feature master.
def build_employee_actuarial_features(
    employee_clean,
):


    # Work on a copy so Pipeline 04 cannot overwrite
    # the cleaned Pipeline 03 dataset.
    result = employee_clean.copy()


    # -------------------------------------------------------------------------
    # 43.1 — STORE VALUATION AND FEATURE VERSION
    # -------------------------------------------------------------------------


    # Store valuation date on every model-ready employee row.
    #
    # This is useful for auditability because age and service are
    # valuation-date-dependent quantities.
    result[
        "feature_valuation_date"
    ] = VALUATION_DATE


    # Store feature-engineering version.
    result[
        "feature_version"
    ] = FEATURE_VERSION


    # -------------------------------------------------------------------------
    # 43.2 — ACTIVE STATUS
    # -------------------------------------------------------------------------


    # Flag employees who are active at the valuation date.
    result[
        "active_at_valuation_flag"
    ] = (

        result[
            "employment_status"
        ].eq(
            "Active"
        )
    )


    # -------------------------------------------------------------------------
    # 43.3 — ATTAINED AGE
    # -------------------------------------------------------------------------


    # Calculate fractional attained age.
    #
    # Formula:
    #
    # Attained Age
    # =
    # (Valuation Date - Date of Birth) / 365.25
    result[
        "attained_age_years"
    ] = years_between(

        pd.Series(

            VALUATION_DATE,

            index=result.index
        ),

        result[
            "date_of_birth"
        ]
    )


    # Determine whether the employee's birthday has occurred
    # during valuation year.
    birthday_not_yet_reached = (

        (
            result[
                "date_of_birth"
            ].dt.month

            > VALUATION_DATE.month
        )

        | (

            (
                result[
                    "date_of_birth"
                ].dt.month

                == VALUATION_DATE.month
            )

            & (

                result[
                    "date_of_birth"
                ].dt.day

                > VALUATION_DATE.day
            )
        )
    )


    # Calculate attained age last birthday.
    #
    # Example:
    #
    # exact age = 43.67
    # age last birthday = 43
    result[
        "attained_age_last_birthday"
    ] = (

        VALUATION_DATE.year

        - result[
            "date_of_birth"
        ].dt.year

        - birthday_not_yet_reached
        .astype(
            "Int64"
        )
    ).astype(
        "Int64"
    )


    # -------------------------------------------------------------------------
    # 43.4 — SERVICE MEASUREMENT DATE
    # -------------------------------------------------------------------------


    # Start by assuming service is measured to the valuation date.
    result[
        "service_measurement_date"
    ] = VALUATION_DATE


    # Identify employees who are no longer active and have an exit date.
    exited_employee = (

        ~result[
            "active_at_valuation_flag"
        ]

        & result[
            "exit_date"
        ].notna()
    )


    # For an employee who has already left,
    # service must stop on the employee's actual exit date.
    result.loc[

        exited_employee,

        "service_measurement_date"

    ] = result.loc[

        exited_employee,

        "exit_date"
    ]


    # -------------------------------------------------------------------------
    # 43.5 — COMPLETED SERVICE
    # -------------------------------------------------------------------------


    # Calculate exact completed service.
    #
    # Formula:
    #
    # Completed Service
    # =
    # (Service Measurement Date - Date of Joining) / 365.25
    result[
        "completed_service_years"
    ] = years_between(

        result[
            "service_measurement_date"
        ],

        result[
            "date_of_joining"
        ]
    )


    # Protect against tiny negative numerical values.
    result[
        "completed_service_years"
    ] = result[
        "completed_service_years"
    ].clip(
        lower=0
    )


    # Calculate completed whole service years.
    #
    # IMPORTANT:
    # This is NOT yet statutory Gratuity qualifying service.
    #
    # Gratuity part-year and cause-specific rules will be applied
    # later by the Gratuity engine.
    result[
        "completed_service_full_years"
    ] = np.floor(

        result[
            "completed_service_years"
        ]

    ).astype(
        "Int64"
    )


    # Calculate fractional portion of the current service year.
    result[
        "completed_service_fraction"
    ] = (

        result[
            "completed_service_years"
        ]

        - result[
            "completed_service_full_years"
        ].astype(
            float
        )
    )


    # -------------------------------------------------------------------------
    # 43.6 — EXPECTED RETIREMENT DATE
    # -------------------------------------------------------------------------


    # Convert retirement age into numeric form.
    result[
        "retirement_age_numeric"
    ] = pd.to_numeric(

        result[
            "retirement_age"
        ],

        errors="coerce"
    )


    # Derive employee-specific expected retirement date.
    result[
        "expected_retirement_date"
    ] = pd.to_datetime([

        add_years_safe(
            date_of_birth,
            retirement_age
        )

        for (
            date_of_birth,
            retirement_age
        )

        in zip(

            result[
                "date_of_birth"
            ],

            result[
                "retirement_age_numeric"
            ]
        )
    ])


    # -------------------------------------------------------------------------
    # 43.7 — REMAINING SERVICE
    # -------------------------------------------------------------------------


    # Calculate raw remaining service from the book relationship:
    #
    # Remaining Service
    # =
    # Retirement Age - Attained Age
    result[
        "remaining_service_years_raw"
    ] = (

        result[
            "retirement_age_numeric"
        ]

        - result[
            "attained_age_years"
        ]
    )


    # For modelling purposes, remaining service cannot be negative.
    model_remaining_service = result[
        "remaining_service_years_raw"
    ].clip(
        lower=0
    )


    # Employees who already exited have no future active service.
    result[
        "remaining_service_years"
    ] = np.where(

        result[
            "active_at_valuation_flag"
        ],

        model_remaining_service,

        0.0
    )


    # Calculate retirement horizon directly from dates as a second
    # independent representation.
    result[
        "years_to_expected_retirement"
    ] = years_between(

        result[
            "expected_retirement_date"
        ],

        pd.Series(

            VALUATION_DATE,

            index=result.index
        )
    )


    # Negative retirement horizons become zero.
    result[
        "years_to_expected_retirement"
    ] = result[
        "years_to_expected_retirement"
    ].clip(
        lower=0
    )


    # Employees who already exited have zero remaining active-service horizon.
    result.loc[

        ~result[
            "active_at_valuation_flag"
        ],

        "years_to_expected_retirement"

    ] = 0.0


    # -------------------------------------------------------------------------
    # 43.8 — ANNUALIZE CURRENT SALARY BASES
    # -------------------------------------------------------------------------


    # Convert monthly Basic Salary into annual Basic Salary.
    result[
        "basic_salary_annual"
    ] = (

        result[
            "basic_salary_monthly"
        ]

        * 12
    )


    # Convert monthly Dearness Allowance into annual DA.
    result[
        "dearness_allowance_annual"
    ] = (

        result[
            "dearness_allowance_monthly"
        ]

        * 12
    )


    # Convert monthly Gratuity Eligible Wage into annual equivalent.
    result[
        "gratuity_eligible_wages_annual"
    ] = (

        result[
            "eligible_gratuity_wages_monthly"
        ]

        * 12
    )


    # -------------------------------------------------------------------------
    # 43.9 — SALARY-STRUCTURE RATIOS
    # -------------------------------------------------------------------------


    # Calculate Dearness Allowance relative to Basic Salary.
    result[
        "da_to_basic_ratio"
    ] = (

        result[
            "dearness_allowance_monthly"
        ]

        / result[
            "basic_salary_monthly"
        ].replace(
            0,
            np.nan
        )
    )


    # Compare annual Pensionable Salary with annual Gratuity wage.
    result[
        "pensionable_to_gratuity_wage_ratio"
    ] = (

        result[
            "pensionable_salary_annual"
        ]

        / result[
            "gratuity_eligible_wages_annual"
        ].replace(
            0,
            np.nan
        )
    )


    # Compare Gross Compensation with annual Basic Salary.
    result[
        "gross_to_basic_ratio"
    ] = (

        result[
            "gross_compensation_annual"
        ]

        / result[
            "basic_salary_annual"
        ].replace(
            0,
            np.nan
        )
    )


    # -------------------------------------------------------------------------
    # 43.10 — AGE SEGMENT
    # -------------------------------------------------------------------------


    # Convert exact age into the predefined age bands.
    result[
        "age_band"
    ] = pd.cut(

        result[
            "attained_age_years"
        ],

        bins=AGE_BINS,

        labels=AGE_LABELS,

        # left-inclusive:
        # age 25 belongs to 25-34 rather than <25.
        right=False
    )


    # -------------------------------------------------------------------------
    # 43.11 — SERVICE SEGMENT
    # -------------------------------------------------------------------------


    # Convert completed service into service bands.
    result[
        "service_band"
    ] = pd.cut(

        result[
            "completed_service_years"
        ],

        bins=SERVICE_BINS,

        labels=SERVICE_LABELS,

        right=False
    )


    # -------------------------------------------------------------------------
    # 43.12 — SALARY SEGMENT
    # -------------------------------------------------------------------------


    # Convert annual Gross Compensation into descriptive salary bands.
    result[
        "salary_band"
    ] = pd.cut(

        result[
            "gross_compensation_annual"
        ],

        bins=SALARY_BINS,

        labels=SALARY_LABELS,

        right=False
    )


    # -------------------------------------------------------------------------
    # 43.13 — PRODUCT MODEL-SCOPE FLAGS
    # -------------------------------------------------------------------------
    #
    # These are membership/scope flags only.
    #
    # They are NOT final statutory or scheme eligibility determinations.
    # -------------------------------------------------------------------------


    # Active employee recorded as a Gratuity member.
    result[
        "active_gratuity_member_flag"
    ] = (

        result[
            "active_at_valuation_flag"
        ]

        & result[
            "gratuity_member_flag"
        ].eq(
            "Yes"
        )
    )


    # Active employee recorded as a Superannuation member.
    result[
        "active_superannuation_member_flag"
    ] = (

        result[
            "active_at_valuation_flag"
        ]

        & result[
            "superannuation_member_flag"
        ].eq(
            "Yes"
        )
    )


    # Active Defined Benefit pension member.
    result[
        "active_db_pension_member_flag"
    ] = (

        result[
            "active_superannuation_member_flag"
        ]

        & result[
            "superannuation_scheme_type"
        ].eq(
            "DB"
        )
    )


    # Active Defined Contribution superannuation member.
    result[
        "active_dc_superannuation_member_flag"
    ] = (

        result[
            "active_superannuation_member_flag"
        ]

        & result[
            "superannuation_scheme_type"
        ].eq(
            "DC"
        )
    )


    # Active employee recorded as EDLI eligible.
    result[
        "active_edli_member_flag"
    ] = (

        result[
            "active_at_valuation_flag"
        ]

        & result[
            "edli_eligible_flag"
        ].eq(
            "Yes"
        )
    )


    # Active employee recorded as a GTI member.
    result[
        "active_gti_member_flag"
    ] = (

        result[
            "active_at_valuation_flag"
        ]

        & result[
            "gti_member_flag"
        ].eq(
            "Yes"
        )
    )


    # -------------------------------------------------------------------------
    # 43.14 — DATA-PROVENANCE STATUS
    # -------------------------------------------------------------------------


    # Start every employee with the best status:
    # source data were validated without Pipeline 03 alteration.
    result[
        "model_input_quality_status"
    ] = "Observed_or_Validated"


    # If Pipeline 03 changed any employee field,
    # clearly identify the row as reconstructed/imputed.
    result.loc[

        result[
            "cleaning_any_change_flag"
        ],

        "model_input_quality_status"

    ] = "Reconstructed_or_Imputed"


    # Any unresolved Pipeline 03 review item receives highest-priority
    # review status.
    result.loc[

        result[
            "cleaning_review_flag"
        ],

        "model_input_quality_status"

    ] = "Review"


    # Return the model-ready employee feature master.
    return result


# =============================================================================
# SECTION 44 — SALARY EXPERIENCE FEATURE ENGINE
# =============================================================================


# Define a function that converts cleaned salary history
# into features suitable for salary-experience analysis.
def build_salary_experience_features(
    salary_clean,
    employee_features,
):


    # Copy salary history and sort records chronologically.
    result = (

        salary_clean
        .copy()
        .sort_values([

            "employee_id",

            "effective_date",
        ])
        .reset_index(
            drop=True
        )
    )


    # -------------------------------------------------------------------------
    # 44.1 — SALARY RECORD SEQUENCE
    # -------------------------------------------------------------------------


    # Number each salary record sequentially within employee.
    result[
        "salary_record_sequence"
    ] = (

        result.groupby(
            "employee_id"
        )
        .cumcount()

        + 1
    )


    # Extract calendar year of each salary observation.
    result[
        "salary_effective_year"
    ] = result[
        "effective_date"
    ].dt.year


    # -------------------------------------------------------------------------
    # 44.2 — PREVIOUS SALARY OBSERVATION
    # -------------------------------------------------------------------------


    # Retrieve previous salary effective date for each employee.
    result[
        "previous_effective_date"
    ] = result.groupby(

        "employee_id"

    )[
        "effective_date"
    ].shift(1)


    # Retrieve previous monthly Basic Salary.
    result[
        "previous_basic_salary_monthly"
    ] = result.groupby(

        "employee_id"

    )[
        "basic_salary_monthly"
    ].shift(1)


    # Retrieve previous annual Gross Compensation.
    result[
        "previous_gross_compensation_annual"
    ] = result.groupby(

        "employee_id"

    )[
        "gross_compensation_annual"
    ].shift(1)


    # -------------------------------------------------------------------------
    # 44.3 — TIME BETWEEN SALARY RECORDS
    # -------------------------------------------------------------------------


    # Calculate elapsed time between consecutive salary observations.
    result[
        "salary_interval_years"
    ] = years_between(

        result[
            "effective_date"
        ],

        result[
            "previous_effective_date"
        ]
    )


    # -------------------------------------------------------------------------
    # 44.4 — PERIOD BASIC-SALARY GROWTH
    # -------------------------------------------------------------------------


    # Calculate observed growth over the full observation interval.
    #
    # Formula:
    #
    # g =
    # Current Salary / Previous Salary - 1
    result[
        "basic_salary_period_growth"
    ] = (

        result[
            "basic_salary_monthly"
        ]

        / result[
            "previous_basic_salary_monthly"
        ].replace(
            0,
            np.nan
        )

        - 1
    )


    # -------------------------------------------------------------------------
    # 44.5 — ANNUALIZED BASIC-SALARY GROWTH
    # -------------------------------------------------------------------------


    # Define records for which annualized growth is mathematically valid.
    valid_basic_annualization = (

        result[
            "salary_interval_years"
        ].gt(0)

        & result[
            "basic_salary_monthly"
        ].gt(0)

        & result[
            "previous_basic_salary_monthly"
        ].gt(0)
    )


    # Initialize annualized Basic Salary growth as missing.
    result[
        "basic_salary_annualized_growth"
    ] = np.nan


    # Apply:
    #
    # annualized growth
    # =
    # (Current / Previous)^(1 / elapsed years) - 1
    result.loc[

        valid_basic_annualization,

        "basic_salary_annualized_growth"

    ] = (

        (

            result.loc[

                valid_basic_annualization,

                "basic_salary_monthly"
            ]

            / result.loc[

                valid_basic_annualization,

                "previous_basic_salary_monthly"
            ]
        )

        ** (

            1

            / result.loc[

                valid_basic_annualization,

                "salary_interval_years"
            ]
        )

        - 1
    )


    # -------------------------------------------------------------------------
    # 44.6 — GROSS-COMPENSATION GROWTH
    # -------------------------------------------------------------------------


    # Calculate period Gross Compensation growth.
    result[
        "gross_comp_period_growth"
    ] = (

        result[
            "gross_compensation_annual"
        ]

        / result[
            "previous_gross_compensation_annual"
        ].replace(
            0,
            np.nan
        )

        - 1
    )


    # Identify valid Gross Compensation annualization records.
    valid_gross_annualization = (

        result[
            "salary_interval_years"
        ].gt(0)

        & result[
            "gross_compensation_annual"
        ].gt(0)

        & result[
            "previous_gross_compensation_annual"
        ].gt(0)
    )


    # Initialize annualized Gross Compensation growth.
    result[
        "gross_comp_annualized_growth"
    ] = np.nan


    # Calculate annualized Gross Compensation growth.
    result.loc[

        valid_gross_annualization,

        "gross_comp_annualized_growth"

    ] = (

        (

            result.loc[

                valid_gross_annualization,

                "gross_compensation_annual"
            ]

            / result.loc[

                valid_gross_annualization,

                "previous_gross_compensation_annual"
            ]
        )

        ** (

            1

            / result.loc[

                valid_gross_annualization,

                "salary_interval_years"
            ]
        )

        - 1
    )


    # -------------------------------------------------------------------------
    # 44.7 — ANNUALIZE HISTORICAL MONTHLY SALARY BASES
    # -------------------------------------------------------------------------


    # Convert historical monthly Basic Salary to annual equivalent.
    result[
        "basic_salary_annual"
    ] = (

        result[
            "basic_salary_monthly"
        ]

        * 12
    )


    # Convert historical Gratuity Eligible Wage to annual equivalent.
    result[
        "gratuity_eligible_wages_annual"
    ] = (

        result[
            "gratuity_eligible_wages_monthly"
        ]

        * 12
    )


    # Convert historical EDLI Eligible Wage to annual equivalent.
    result[
        "edli_eligible_wages_annual"
    ] = (

        result[
            "edli_eligible_wages_monthly"
        ]

        * 12
    )


    # -------------------------------------------------------------------------
    # 44.8 — ATTACH CURRENT WORKFORCE SEGMENT INFORMATION
    # -------------------------------------------------------------------------


    # Keep selected current employee descriptors.
    employee_lookup = employee_features[[

        "employee_id",

        "grade",

        "occupation_class",

        "work_location",

        "employment_type",

        "age_band",

        "service_band",

    ]].copy()


    # Join descriptors to salary-experience observations.
    result = result.merge(

        employee_lookup,

        on="employee_id",

        how="left"
    )


    # -------------------------------------------------------------------------
    # 44.9 — SALARY-GROWTH MODEL-USABILITY FLAG
    # -------------------------------------------------------------------------


    # A salary observation is usable for growth analysis when:
    #
    # 1. it has a previous observation,
    # 2. elapsed time is positive,
    # 3. both salaries are positive,
    # 4. Pipeline 03 has not left the row requiring review.
    result[
        "salary_growth_model_usable_flag"
    ] = (

        valid_basic_annualization

        & ~result[
            "cleaning_review_flag"
        ]
    )


    # Store feature version.
    result[
        "feature_version"
    ] = FEATURE_VERSION


    # Return model-ready salary experience.
    return result


# =============================================================================
# SECTION 45 — DECREMENT EXPOSURE FEATURE ENGINE
# =============================================================================


# Define a function that creates the employee-year dataset
# needed for mortality, withdrawal, disability and retirement modelling.
def build_decrement_exposure_features(
    claims_clean,
    employee_features,
):


    # Keep only common Experience records.
    #
    # Product-specific GTI/EDLI claim rows are not used as separate
    # employee-year exposure observations because that would double-count
    # the same employee event.
    result = claims_clean.loc[

        claims_clean[
            "product_type"
        ].eq(
            "Experience"
        )

    ].copy()


    # Reset row index for a clean model-ready dataset.
    result = result.reset_index(
        drop=True
    )


    # -------------------------------------------------------------------------
    # 45.1 — ATTACH EMPLOYEE DEMOGRAPHIC INFORMATION
    # -------------------------------------------------------------------------


    # Select employee variables required by decrement models.
    employee_lookup = employee_features[[

        "employee_id",

        "date_of_birth",

        "date_of_joining",

        "gender",

        "grade",

        "occupation_class",

        "work_location",

        "employment_type",

    ]].copy()


    # Join demographic and employment fields onto each exposure row.
    result = result.merge(

        employee_lookup,

        on="employee_id",

        how="left"
    )


    # -------------------------------------------------------------------------
    # 45.2 — EMPLOYEE-YEAR EXPOSURE
    # -------------------------------------------------------------------------


    # Calculate inclusive exposure days.
    result[
        "exposure_days_derived"
    ] = (

        (

            result[
                "exposure_end_date"
            ]

            - result[
                "exposure_start_date"
            ]
        ).dt.days

        + 1
    )


    # Convert exposure days into employee-years.
    #
    # Formula:
    #
    # Employee-Year Exposure
    # =
    # Exposure Days / 365.25
    result[
        "employee_year_exposure"
    ] = (

        result[
            "exposure_days_derived"
        ]

        / ACTUARIAL_YEAR_DAYS
    )


    # Extract calendar year for experience reporting.
    result[
        "experience_year"
    ] = result[
        "exposure_start_date"
    ].dt.year


    # -------------------------------------------------------------------------
    # 45.3 — EXPOSURE MIDPOINT
    # -------------------------------------------------------------------------


    # Calculate the midpoint of each observed exposure period.
    result[
        "exposure_midpoint_date"
    ] = (

        result[
            "exposure_start_date"
        ]

        + (

            result[
                "exposure_end_date"
            ]

            - result[
                "exposure_start_date"
            ]

        ) / 2
    )


    # -------------------------------------------------------------------------
    # 45.4 — AGE DURING EXPOSURE
    # -------------------------------------------------------------------------


    # Calculate age at exposure start.
    result[
        "age_at_exposure_start"
    ] = years_between(

        result[
            "exposure_start_date"
        ],

        result[
            "date_of_birth"
        ]
    )


    # Calculate age at exposure midpoint.
    result[
        "age_at_exposure_midpoint"
    ] = years_between(

        result[
            "exposure_midpoint_date"
        ],

        result[
            "date_of_birth"
        ]
    )


    # Calculate age at exposure end.
    result[
        "age_at_exposure_end"
    ] = years_between(

        result[
            "exposure_end_date"
        ],

        result[
            "date_of_birth"
        ]
    )


    # -------------------------------------------------------------------------
    # 45.5 — SERVICE DURING EXPOSURE
    # -------------------------------------------------------------------------


    # Calculate completed service at exposure start.
    result[
        "service_at_exposure_start"
    ] = years_between(

        result[
            "exposure_start_date"
        ],

        result[
            "date_of_joining"
        ]
    ).clip(
        lower=0
    )


    # Calculate completed service at exposure midpoint.
    result[
        "service_at_exposure_midpoint"
    ] = years_between(

        result[
            "exposure_midpoint_date"
        ],

        result[
            "date_of_joining"
        ]
    ).clip(
        lower=0
    )


    # Calculate completed service at exposure end.
    result[
        "service_at_exposure_end"
    ] = years_between(

        result[
            "exposure_end_date"
        ],

        result[
            "date_of_joining"
        ]
    ).clip(
        lower=0
    )


    # -------------------------------------------------------------------------
    # 45.6 — AGE AND SERVICE AT ACTUAL EVENT
    # -------------------------------------------------------------------------


    # Calculate attained age when the event occurred.
    #
    # Rows without an observed event remain NaN.
    result[
        "age_at_event"
    ] = years_between(

        result[
            "event_date"
        ],

        result[
            "date_of_birth"
        ]
    )


    # Calculate completed service when the event occurred.
    result[
        "service_at_event"
    ] = years_between(

        result[
            "event_date"
        ],

        result[
            "date_of_joining"
        ]
    )


    # -------------------------------------------------------------------------
    # 45.7 — EVENT AND CENSORING INDICATORS
    # -------------------------------------------------------------------------


    # Flag whether an observed decrement event occurred.
    result[
        "event_observed_flag"
    ] = result[
        "event_type"
    ].notna().astype(
        int
    )


    # A row with no observed event is right-censored
    # at the end of its observed exposure period.
    result[
        "censored_flag"
    ] = (

        1

        - result[
            "event_observed_flag"
        ]
    )


    # -------------------------------------------------------------------------
    # 45.8 — CAUSE-SPECIFIC EVENT INDICATORS
    # -------------------------------------------------------------------------


    # Death indicator:
    #
    # 1 = Death observed during this exposure period
    # 0 = Otherwise
    result[
        "death_event_flag"
    ] = result[
        "event_type"
    ].eq(
        "Death"
    ).astype(
        int
    )


    # Withdrawal indicator.
    result[
        "withdrawal_event_flag"
    ] = result[
        "event_type"
    ].eq(
        "Withdrawal"
    ).astype(
        int
    )


    # Disability indicator.
    result[
        "disability_event_flag"
    ] = result[
        "event_type"
    ].eq(
        "Disability"
    ).astype(
        int
    )


    # Early Retirement indicator.
    result[
        "early_retirement_event_flag"
    ] = result[
        "event_type"
    ].eq(
        "Early Retirement"
    ).astype(
        int
    )


    # Ordinary Retirement indicator.
    #
    # Retirement is retained in experience reporting even though the
    # later competing active-service model will distinguish how normal
    # retirement enters the projection horizon.
    result[
        "retirement_event_flag"
    ] = result[
        "event_type"
    ].eq(
        "Retirement"
    ).astype(
        int
    )


    # -------------------------------------------------------------------------
    # 45.9 — EXPOSURE SEGMENTATION
    # -------------------------------------------------------------------------


    # Segment exposure using age at midpoint.
    result[
        "exposure_age_band"
    ] = pd.cut(

        result[
            "age_at_exposure_midpoint"
        ],

        bins=AGE_BINS,

        labels=AGE_LABELS,

        right=False
    )


    # Segment exposure using service at midpoint.
    result[
        "exposure_service_band"
    ] = pd.cut(

        result[
            "service_at_exposure_midpoint"
        ],

        bins=SERVICE_BINS,

        labels=SERVICE_LABELS,

        right=False
    )


    # -------------------------------------------------------------------------
    # 45.10 — MODEL-USABILITY FLAG
    # -------------------------------------------------------------------------


    # A decrement exposure row is model-usable when Pipeline 03
    # confirmed its exposure dates and it is not marked for unresolved review.
    result[
        "decrement_model_usable_flag"
    ] = (

        result[
            "model_usable_exposure_flag"
        ]

        & ~result[
            "cleaning_review_flag"
        ]
    )


    # Store feature-engineering version.
    result[
        "feature_version"
    ] = FEATURE_VERSION


    # Return the decrement-modelling dataset.
    return result


# =============================================================================
# SECTION 46 — SEGMENT SIZE DIAGNOSTICS
# =============================================================================


# Define a function that checks whether descriptive employee
# segmentation produces very small cells.
def build_segment_summary(
    employee_features,
):


    # Create an empty list to hold one summary per segmentation dimension.
    reports = []


    # Define segmentation dimensions required by the book/framework.
    segment_columns = [

        "age_band",

        "service_band",

        "salary_band",

        "occupation_class",

        "grade",

        "work_location",
    ]


    # Examine each segmentation variable separately.
    #
    # We deliberately avoid creating an enormous cross-product such as:
    #
    # Age x Service x Grade x Location x Occupation
    #
    # because extremely small cells would encourage overfitting.
    for column in segment_columns:


        # Count employees within each segment.
        report = (

            employee_features
            .groupby(

                column,

                observed=True,

                dropna=False
            )

            .agg(

                # Total employee records in the segment.
                employee_count=(
                    "employee_id",
                    "count",
                ),

                # Number of active employees.
                active_employee_count=(
                    "active_at_valuation_flag",
                    "sum",
                ),
            )

            .reset_index()
        )


        # Rename the segment value into a common field name.
        report = report.rename(

            columns={
                column:
                    "segment_value"
            }
        )


        # Store which segmentation dimension is represented.
        report.insert(

            0,

            "segment_dimension",

            column
        )


        # Flag descriptive cells with fewer than 30 employees.
        #
        # This is a review flag, not formal credibility.
        report[
            "small_cell_review_flag"
        ] = (

            report[
                "employee_count"
            ]

            < MIN_SEGMENT_REVIEW_COUNT
        )


        # Add this segmentation report to our list.
        reports.append(
            report
        )


    # Combine all segmentation dimensions into one table.
    segment_summary = pd.concat(

        reports,

        ignore_index=True
    )


    # Return the segmentation summary.
    return segment_summary


# =============================================================================
# SECTION 47 — CRUDE EXPERIENCE-RATE ENGINE
# =============================================================================


# Define a function that calculates descriptive historical event rates.
#
# IMPORTANT:
#
# These are crude observed rates only.
#
# They are NOT the final decrement probabilities used in valuation.
def build_crude_experience_rates(
    exposure_features,
):


    # Keep only model-usable employee-year exposure.
    usable = exposure_features.loc[

        exposure_features[
            "decrement_model_usable_flag"
        ]

    ].copy()


    # -------------------------------------------------------------------------
    # 47.1 — YEARLY EXPOSURE DENOMINATOR
    # -------------------------------------------------------------------------


    # Sum employee-year exposure by calendar year.
    yearly_exposure = usable.groupby(

        "experience_year",

        dropna=False

    ).agg(

        employee_year_exposure=(
            "employee_year_exposure",
            "sum",
        ),

        exposed_employees=(
            "employee_id",
            "nunique",
        ),

    ).reset_index()


    # Define the event types we want to summarize.
    event_types = [

        "Death",

        "Withdrawal",

        "Disability",

        "Early Retirement",

        "Retirement",
    ]


    # Create a list containing yearly cause-specific rate tables.
    yearly_reports = []


    # Calculate one rate table for each event type.
    for event_type in event_types:


        # Count observed events of this type by year.
        event_counts = (

            usable.loc[

                usable[
                    "event_type"
                ].eq(
                    event_type
                )

            ]

            .groupby(
                "experience_year"
            )

            .size()

            .rename(
                "event_count"
            )

            .reset_index()
        )


        # Join event counts to the complete exposure denominator.
        report = yearly_exposure.merge(

            event_counts,

            on="experience_year",

            how="left"
        )


        # Years with no events receive zero events.
        report[
            "event_count"
        ] = report[
            "event_count"
        ].fillna(
            0
        ).astype(
            int
        )


        # Store decrement type.
        report[
            "event_type"
        ] = event_type


        # Apply the book's descriptive formula:
        #
        # Crude Rate
        # =
        # Events / Employee-Year Exposure
        report[
            "crude_observed_rate"
        ] = (

            report[
                "event_count"
            ]

            / report[
                "employee_year_exposure"
            ].replace(
                0,
                np.nan
            )
        )


        # Express the same rate per 1,000 employee-years
        # for easier management interpretation.
        report[
            "rate_per_1000_employee_years"
        ] = (

            report[
                "crude_observed_rate"
            ]

            * 1000
        )


        # Add this decrement table to the list.
        yearly_reports.append(
            report
        )


    # Combine all yearly decrement-rate tables.
    yearly_rates = pd.concat(

        yearly_reports,

        ignore_index=True
    )


    # -------------------------------------------------------------------------
    # 47.2 — OVERALL EXPERIENCE RATES
    # -------------------------------------------------------------------------


    # Calculate total model-usable employee-year exposure.
    total_exposure = usable[
        "employee_year_exposure"
    ].sum()


    # Count distinct employees represented in experience data.
    total_employees = usable[
        "employee_id"
    ].nunique()


    # Create a list for overall event rates.
    overall_rows = []


    # Calculate one overall rate for each decrement.
    for event_type in event_types:


        # Count events of this type.
        event_count = int(

            usable[
                "event_type"
            ]
            .eq(
                event_type
            )
            .sum()
        )


        # Calculate crude overall rate.
        crude_rate = (

            event_count

            / total_exposure

            if total_exposure > 0

            else np.nan
        )


        # Store overall rate.
        overall_rows.append({

            "experience_year":
                "All",

            "employee_year_exposure":
                total_exposure,

            "exposed_employees":
                total_employees,

            "event_count":
                event_count,

            "event_type":
                event_type,

            "crude_observed_rate":
                crude_rate,

            "rate_per_1000_employee_years":
                crude_rate * 1000,
        })


    # Convert overall rates into a DataFrame.
    overall_rates = pd.DataFrame(
        overall_rows
    )


    # Combine yearly and overall rates.
    crude_rates = pd.concat(

        [
            yearly_rates,
            overall_rates,
        ],

        ignore_index=True
    )


    # Return complete descriptive experience-rate table.
    return crude_rates


# =============================================================================
# SECTION 48 — FEATURE VALIDATION
# =============================================================================


# Define a function that validates mathematical feature construction
# before any actuarial probability model is allowed to run.
def build_feature_validation(
    employee_features,
    salary_features,
    exposure_features,
):


    # Create an empty validation result list.
    validation_rows = []


    # Define a small helper for recording validation checks.
    def add_validation(
        check,
        exceptions,
        note="",
    ):


        # Convert exception count into ordinary integer.
        exception_count = int(
            exceptions
        )


        # Zero exceptions means the control passes.
        status = (

            "PASS"

            if exception_count == 0

            else "FAIL"
        )


        # Add the result.
        validation_rows.append({

            "check":
                check,

            "exceptions":
                exception_count,

            "status":
                status,

            "note":
                note,
        })


    # -------------------------------------------------------------------------
    # 48.1 — EMPLOYEE FEATURE CONTROLS
    # -------------------------------------------------------------------------


    # Confirm one model-ready record per employee.
    add_validation(

        "employee feature employee_id unique",

        employee_features[
            "employee_id"
        ].duplicated().sum(),
    )


    # Confirm derived attained ages exist and fall in plausible range.
    add_validation(

        "attained age within model range",

        (

            employee_features[
                "attained_age_years"
            ].isna()

            | (
                employee_features[
                    "attained_age_years"
                ]
                < 0
            )

            | (
                employee_features[
                    "attained_age_years"
                ]
                > QA_MAX_ATTAINED_AGE
            )

        ).sum(),
    )


    # Confirm completed service is never negative.
    add_validation(

        "completed service non-negative",

        (

            employee_features[
                "completed_service_years"
            ]

            < 0

        ).sum(),
    )


    # Confirm remaining service is never negative.
    add_validation(

        "remaining service non-negative",

        (

            employee_features[
                "remaining_service_years"
            ]

            < 0

        ).sum(),
    )


    # Confirm exited employees have zero future service.
    add_validation(

        "non-active employee remaining service equals zero",

        (

            ~employee_features[
                "active_at_valuation_flag"
            ]

            & (
                employee_features[
                    "remaining_service_years"
                ]
                != 0
            )

        ).sum(),
    )


    # Independently verify annual Basic Salary calculation.
    add_validation(

        "annual basic equals monthly basic x 12",

        (

            (

                employee_features[
                    "basic_salary_annual"
                ]

                - (
                    employee_features[
                        "basic_salary_monthly"
                    ]
                    * 12
                )

            ).abs()

            > 0.01

        ).sum(),
    )


    # Independently verify annual Gratuity wage calculation.
    add_validation(

        "annual gratuity wage equals monthly wage x 12",

        (

            (

                employee_features[
                    "gratuity_eligible_wages_annual"
                ]

                - (
                    employee_features[
                        "eligible_gratuity_wages_monthly"
                    ]
                    * 12
                )

            ).abs()

            > 0.01

        ).sum(),
    )


    # Confirm DB model-scope flag cannot be true
    # unless Superannuation member scope is also true.
    add_validation(

        "DB scope is subset of superannuation scope",

        (

            employee_features[
                "active_db_pension_member_flag"
            ]

            & ~employee_features[
                "active_superannuation_member_flag"
            ]

        ).sum(),
    )


    # Confirm DC model-scope flag cannot be true
    # unless Superannuation member scope is also true.
    add_validation(

        "DC scope is subset of superannuation scope",

        (

            employee_features[
                "active_dc_superannuation_member_flag"
            ]

            & ~employee_features[
                "active_superannuation_member_flag"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 48.2 — SALARY FEATURE CONTROLS
    # -------------------------------------------------------------------------


    # A usable salary-growth observation must have positive time interval.
    add_validation(

        "usable salary growth has positive interval",

        (

            salary_features[
                "salary_growth_model_usable_flag"
            ]

            & (
                salary_features[
                    "salary_interval_years"
                ]
                <= 0
            )

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 48.3 — EXPOSURE FEATURE CONTROLS
    # -------------------------------------------------------------------------


    # Model-usable exposure must be strictly positive.
    add_validation(

        "model-usable exposure is positive",

        (

            exposure_features[
                "decrement_model_usable_flag"
            ]

            & (
                exposure_features[
                    "employee_year_exposure"
                ]
                <= 0
            )

        ).sum(),
    )


    # Our experience file is annualized by design,
    # so a single record should not materially exceed one calendar year.
    add_validation(

        "single exposure record not greater than one year",

        (

            exposure_features[
                "decrement_model_usable_flag"
            ]

            & (
                exposure_features[
                    "employee_year_exposure"
                ]
                > 1.01
            )

        ).sum(),

        note=(
            "Annual synthetic experience-record design"
        ),
    )


    # Event-observed and censored indicators must sum to exactly one.
    add_validation(

        "event observed plus censored equals one",

        (

            (

                exposure_features[
                    "event_observed_flag"
                ]

                + exposure_features[
                    "censored_flag"
                ]

            ) != 1

        ).sum(),
    )


    # Cause-specific indicators cannot exceed one event per exposure row.
    cause_indicator_sum = (

        exposure_features[

            [
                "death_event_flag",
                "withdrawal_event_flag",
                "disability_event_flag",
                "early_retirement_event_flag",
                "retirement_event_flag",
            ]

        ].sum(
            axis=1
        )
    )


    # Confirm at most one observed cause is attached to an employee-year record.
    add_validation(

        "maximum one event cause per exposure row",

        (
            cause_indicator_sum
            > 1
        ).sum(),
    )


    # Confirm that any observed event corresponds to exactly one known cause.
    add_validation(

        "observed event maps to one known cause",

        (

            exposure_features[
                "event_observed_flag"
            ].eq(1)

            & cause_indicator_sum.ne(1)

        ).sum(),
    )


    # Convert all validation results into one DataFrame.
    return pd.DataFrame(
        validation_rows
    )


# =============================================================================
# SECTION 49 — FEATURE MANIFEST
# =============================================================================


# Define a function that documents the three model-ready datasets.
def build_feature_manifest(
    employee_features,
    salary_features,
    exposure_features,
):


    # Create a compact data inventory.
    return pd.DataFrame([


        # Employee actuarial feature master.
        {
            "dataset":
                "employee_actuarial_features.csv",

            "rows":
                len(
                    employee_features
                ),

            "columns":
                employee_features.shape[1],

            "feature_version":
                FEATURE_VERSION,

            "purpose":
                (
                    "Age, service, retirement horizon, "
                    "salary bases, segmentation and product scope"
                ),
        },


        # Salary experience dataset.
        {
            "dataset":
                "salary_experience_features.csv",

            "rows":
                len(
                    salary_features
                ),

            "columns":
                salary_features.shape[1],

            "feature_version":
                FEATURE_VERSION,

            "purpose":
                (
                    "Historical salary movement and "
                    "annualized salary-growth experience"
                ),
        },


        # Decrement exposure dataset.
        {
            "dataset":
                "decrement_exposure_features.csv",

            "rows":
                len(
                    exposure_features
                ),

            "columns":
                exposure_features.shape[1],

            "feature_version":
                FEATURE_VERSION,

            "purpose":
                (
                    "Employee-year exposure, age/service duration, "
                    "events and censoring for decrement models"
                ),
        },
    ])


# =============================================================================
# SECTION 50 — PIPELINE 04 CONTROLLER
# =============================================================================


# Define the main function that runs Pipeline 04.
def run_pipeline_04(
    cleaning_results,
):


    # Print opening separator.
    print(
        "\n"
        + "=" * 72
    )


    # Print Pipeline 04 title.
    print(
        "PIPELINE 04 - "
        "DERIVED ACTUARIAL FEATURES"
    )


    # Print valuation date.
    print(
        f"Valuation date: "
        f"{VALUATION_DATE.date()}"
    )


    # Print feature version.
    print(
        f"Feature version: "
        f"{FEATURE_VERSION}"
    )


    # Print closing separator.
    print(
        "=" * 72
    )


    # -------------------------------------------------------------------------
    # STEP 50.1 — RETRIEVE CLEAN PIPELINE 03 DATA
    # -------------------------------------------------------------------------


    # Retrieve the clean-data dictionary returned by Pipeline 03.
    clean_data = cleaning_results[
        "clean_data"
    ]


    # -------------------------------------------------------------------------
    # STEP 50.2 — BUILD EMPLOYEE ACTUARIAL FEATURES
    # -------------------------------------------------------------------------


    # Convert cleaned employee census into model-ready employee features.
    employee_features = (
        build_employee_actuarial_features(

            clean_data[
                "employee"
            ]
        )
    )


    # -------------------------------------------------------------------------
    # STEP 50.3 — BUILD SALARY EXPERIENCE FEATURES
    # -------------------------------------------------------------------------


    # Convert cleaned salary history into model-ready salary experience.
    salary_features = (
        build_salary_experience_features(

            clean_data[
                "salary"
            ],

            employee_features
        )
    )


    # -------------------------------------------------------------------------
    # STEP 50.4 — BUILD DECREMENT EXPOSURE FEATURES
    # -------------------------------------------------------------------------


    # Convert cleaned Experience records into employee-year model data.
    exposure_features = (
        build_decrement_exposure_features(

            clean_data[
                "claims"
            ],

            employee_features
        )
    )


    # -------------------------------------------------------------------------
    # STEP 50.5 — BUILD EMPLOYEE SEGMENT SUMMARY
    # -------------------------------------------------------------------------


    # Analyze age, service, salary, occupation, grade and location segment sizes.
    segment_summary = build_segment_summary(

        employee_features
    )


    # -------------------------------------------------------------------------
    # STEP 50.6 — BUILD CRUDE EXPERIENCE RATES
    # -------------------------------------------------------------------------


    # Calculate descriptive events divided by employee-year exposure.
    crude_experience_rates = (
        build_crude_experience_rates(

            exposure_features
        )
    )


    # -------------------------------------------------------------------------
    # STEP 50.7 — VALIDATE ALL DERIVED FEATURES
    # -------------------------------------------------------------------------


    # Run independent mathematical controls.
    feature_validation = (
        build_feature_validation(

            employee_features,

            salary_features,

            exposure_features
        )
    )


    # -------------------------------------------------------------------------
    # STEP 50.8 — CREATE FEATURE MANIFEST
    # -------------------------------------------------------------------------


    # Document model-ready dataset dimensions and purposes.
    feature_manifest = build_feature_manifest(

        employee_features,

        salary_features,

        exposure_features
    )


    # -------------------------------------------------------------------------
    # STEP 50.9 — SAVE MODEL-READY DATASETS
    # -------------------------------------------------------------------------


    # Save employee actuarial feature master.
    employee_features.to_csv(

        MODEL_READY_DATA_DIR
        / "employee_actuarial_features.csv",

        index=False
    )


    # Save salary-experience feature dataset.
    salary_features.to_csv(

        MODEL_READY_DATA_DIR
        / "salary_experience_features.csv",

        index=False
    )


    # Save decrement-exposure feature dataset.
    exposure_features.to_csv(

        MODEL_READY_DATA_DIR
        / "decrement_exposure_features.csv",

        index=False
    )


    # -------------------------------------------------------------------------
    # STEP 50.10 — SAVE PIPELINE 04 REPORTS
    # -------------------------------------------------------------------------


    # Save segment-size diagnostics.
    segment_summary.to_csv(

        FEATURE_OUTPUT_DIR
        / "segment_summary.csv",

        index=False
    )


    # Save crude historical event rates.
    crude_experience_rates.to_csv(

        FEATURE_OUTPUT_DIR
        / "crude_experience_rates.csv",

        index=False
    )


    # Save mathematical feature validation.
    feature_validation.to_csv(

        FEATURE_OUTPUT_DIR
        / "feature_validation.csv",

        index=False
    )


    # Save model-ready dataset manifest.
    feature_manifest.to_csv(

        FEATURE_OUTPUT_DIR
        / "feature_manifest.csv",

        index=False
    )


    # -------------------------------------------------------------------------
    # STEP 50.11 — TERMINAL SUMMARY
    # -------------------------------------------------------------------------


    # Print feature-dataset dimensions.
    print(
        "\nModel-ready datasets"
    )


    # Print employee feature dimensions.
    print(

        f"  Employee actuarial features:        "
        f"{len(employee_features):,} rows x "
        f"{employee_features.shape[1]} columns"
    )


    # Print salary feature dimensions.
    print(

        f"  Salary experience features:         "
        f"{len(salary_features):,} rows x "
        f"{salary_features.shape[1]} columns"
    )


    # Print decrement exposure dimensions.
    print(

        f"  Decrement exposure features:        "
        f"{len(exposure_features):,} rows x "
        f"{exposure_features.shape[1]} columns"
    )


    # Print active employee count.
    print(

        f"\nActive employees at valuation:        "
        f"{employee_features['active_at_valuation_flag'].sum():,}"
    )


    # Print active Gratuity member count.
    print(

        f"Active Gratuity members:              "
        f"{employee_features['active_gratuity_member_flag'].sum():,}"
    )


    # Print active DB pension member count.
    print(

        f"Active DB Pension members:            "
        f"{employee_features['active_db_pension_member_flag'].sum():,}"
    )


    # Print active DC member count.
    print(

        f"Active DC Superannuation members:     "
        f"{employee_features['active_dc_superannuation_member_flag'].sum():,}"
    )


    # Print active EDLI member count.
    print(

        f"Active EDLI members:                  "
        f"{employee_features['active_edli_member_flag'].sum():,}"
    )


    # Print active GTI member count.
    print(

        f"Active GTI members:                   "
        f"{employee_features['active_gti_member_flag'].sum():,}"
    )


    # Print total model-usable employee-year exposure.
    total_exposure = (

        exposure_features.loc[

            exposure_features[
                "decrement_model_usable_flag"
            ],

            "employee_year_exposure"

        ].sum()
    )


    # Display total employee-year exposure.
    print(

        f"\nModel-usable employee-year exposure:  "
        f"{total_exposure:,.2f}"
    )


    # Count feature validation failures.
    feature_failures = (

        feature_validation[
            "status"
        ]
        .eq(
            "FAIL"
        )
        .sum()
    )


    # Display validation result.
    print(

        f"\nFeature validation failures:          "
        f"{feature_failures}"
    )


    # Count descriptive segmentation cells requiring review.
    small_segments = (

        segment_summary[
            "small_cell_review_flag"
        ].sum()
    )


    # Display small-cell review count.
    print(

        f"Small descriptive segments to review: "
        f"{small_segments}"
    )


    # Tell user where model-ready datasets were written.
    print(

        f"\nModel-ready datasets written to:\n"
        f"{MODEL_READY_DATA_DIR}"
    )


    # Tell user where Pipeline 04 reports were written.
    print(

        f"\nFeature reports written to:\n"
        f"{FEATURE_OUTPUT_DIR}"
    )


    # Confirm completion.
    print(

        "\nPipeline 04 complete."
        "\nNo decrement probabilities, future benefits or liabilities "
        "have been calculated yet.\n"
    )


    # -------------------------------------------------------------------------
    # STEP 50.12 — RETURN MODEL-READY DATA
    # -------------------------------------------------------------------------


    # Return every major Pipeline 04 object.
    return {

        "employee_features":
            employee_features,

        "salary_features":
            salary_features,

        "exposure_features":
            exposure_features,

        "segment_summary":
            segment_summary,

        "crude_experience_rates":
            crude_experience_rates,

        "feature_validation":
            feature_validation,

        "feature_manifest":
            feature_manifest,
    }


