# =============================================================================
# SECTION 56 — BOOLEAN VALUE PARSER
# =============================================================================


# Define a helper that converts CSV Boolean-like values
# into genuine Python True / False values.
def parse_boolean_rule_value(
    value,
):


    # Preserve a missing value as missing.
    if pd.isna(
        value
    ):

        return pd.NA


    # If the value is already Boolean,
    # simply convert it to an ordinary Python bool.
    if isinstance(

        value,

        (
            bool,
            np.bool_,
        )
    ):

        return bool(
            value
        )


    # Convert any remaining input to lowercase text.
    text_value = (

        str(
            value
        )

        .strip()

        .lower()
    )


    # Accept common representations of True.
    if text_value in {

        "true",

        "1",

        "yes",

        "y",
    }:

        return True


    # Accept common representations of False.
    if text_value in {

        "false",

        "0",

        "no",

        "n",
    }:

        return False


    # Anything else is not a valid Boolean rule value.
    return pd.NA


# =============================================================================
# SECTION 57 — PREPARE TYPED RULE CATALOGUE
# =============================================================================


# Define the function that converts the generic CSV parameter_value field
# into controlled Numeric, Text and Boolean representations.
def prepare_typed_rule_catalogue(
    rules,
):


    # Work on a copy so Pipeline 05 cannot modify
    # the cleaned Pipeline 03 rule table.
    result = rules.copy()


    # Preserve the original source parameter value exactly as supplied.
    result[
        "parameter_value_source"
    ] = result[
        "parameter_value"
    ]


    # -------------------------------------------------------------------------
    # 57.1 — INITIALIZE TYPED VALUE COLUMNS
    # -------------------------------------------------------------------------


    # Numeric parameters will be stored here.
    result[
        "numeric_value"
    ] = np.nan


    # Text parameters will be stored here.
    result[
        "text_value"
    ] = pd.NA


    # Boolean parameters will be stored here.
    result[
        "boolean_value"
    ] = pd.NA


    # -------------------------------------------------------------------------
    # 57.2 — IDENTIFY DECLARED VALUE TYPES
    # -------------------------------------------------------------------------


    # Identify Numeric rule rows.
    numeric_mask = result[
        "value_type"
    ].eq(
        "Numeric"
    )


    # Identify Text rule rows.
    text_mask = result[
        "value_type"
    ].eq(
        "Text"
    )


    # Identify Boolean rule rows.
    boolean_mask = result[
        "value_type"
    ].eq(
        "Boolean"
    )


    # -------------------------------------------------------------------------
    # 57.3 — PARSE NUMERIC VALUES
    # -------------------------------------------------------------------------


    # Convert declared Numeric parameters into actual numbers.
    #
    # Invalid numeric text becomes NaN and is later caught by validation.
    result.loc[

        numeric_mask,

        "numeric_value"

    ] = pd.to_numeric(

        result.loc[

            numeric_mask,

            "parameter_value"
        ],

        errors="coerce"
    )


    # -------------------------------------------------------------------------
    # 57.4 — PARSE TEXT VALUES
    # -------------------------------------------------------------------------


    # Convert declared Text parameters into trimmed strings.
    result.loc[

        text_mask,

        "text_value"

    ] = (

        result.loc[

            text_mask,

            "parameter_value"
        ]

        .astype(
            "string"
        )

        .str.strip()
    )


    # -------------------------------------------------------------------------
    # 57.5 — PARSE BOOLEAN VALUES
    # -------------------------------------------------------------------------


    # Convert declared Boolean parameters into genuine True / False values.
    result.loc[

        boolean_mask,

        "boolean_value"

    ] = result.loc[

        boolean_mask,

        "parameter_value"

    ].apply(
        parse_boolean_rule_value
    )


    # -------------------------------------------------------------------------
    # 57.6 — VALUE-PARSING VALIDATION
    # -------------------------------------------------------------------------


    # Initialize every row as unsuccessful until proven valid.
    result[
        "value_parse_success_flag"
    ] = False


    # Numeric values parse successfully when numeric_value is present.
    result.loc[

        numeric_mask,

        "value_parse_success_flag"

    ] = result.loc[

        numeric_mask,

        "numeric_value"

    ].notna()


    # Text values parse successfully when non-missing and non-blank.
    result.loc[

        text_mask,

        "value_parse_success_flag"

    ] = (

        result.loc[

            text_mask,

            "text_value"
        ].notna()

        & result.loc[

            text_mask,

            "text_value"
        ].ne(
            ""
        )
    )


    # Boolean values parse successfully when True or False was recognized.
    result.loc[

        boolean_mask,

        "value_parse_success_flag"

    ] = result.loc[

        boolean_mask,

        "boolean_value"

    ].notna()


    # -------------------------------------------------------------------------
    # 57.7 — EFFECTIVE-DATE SELECTION
    # -------------------------------------------------------------------------


    # A rule is active when:
    #
    # effective_from <= valuation date
    #
    # AND
    #
    # effective_to is blank
    # OR
    # effective_to >= valuation date.
    result[
        "active_at_valuation_flag"
    ] = (

        (

            result[
                "effective_from"
            ].isna()

            | (
                result[
                    "effective_from"
                ]
                <= VALUATION_DATE
            )
        )

        & (

            result[
                "effective_to"
            ].isna()

            | (
                result[
                    "effective_to"
                ]
                >= VALUATION_DATE
            )
        )
    )


    # -------------------------------------------------------------------------
    # 57.8 — FORMULA-TEMPLATE CONTROL
    # -------------------------------------------------------------------------


    # Confirm each formula template is registered
    # in our controlled formula-template dictionary.
    result[
        "formula_supported_flag"
    ] = result[
        "formula_template"
    ].isin(
        FORMULA_TEMPLATE_REGISTRY
    )


    # -------------------------------------------------------------------------
    # 57.9 — EDLI STATUTORY LOCK
    # -------------------------------------------------------------------------


    # EDLI is treated as statutory/date-sensitive.
    result[
        "statutory_locked_flag"
    ] = result[
        "product_type"
    ].eq(
        "EDLI"
    )


    # A parameter is effectively dashboard-editable only when:
    #
    # 1. source rule says Yes, AND
    # 2. it is not part of the statutory EDLI rule set.
    result[
        "effective_dashboard_editable_flag"
    ] = (

        result[
            "dashboard_editable_flag"
        ].eq(
            "Yes"
        )

        & ~result[
            "statutory_locked_flag"
        ]
    )


    # -------------------------------------------------------------------------
    # 57.10 — CREATE A HUMAN-READABLE VALUE
    # -------------------------------------------------------------------------


    # Define a helper for displaying the typed value consistently.
    def build_display_value(
        row,
    ):


        # Numeric values are shown compactly.
        if row[
            "value_type"
        ] == "Numeric":


            # Invalid numeric input receives an explicit warning label.
            if pd.isna(
                row[
                    "numeric_value"
                ]
            ):

                return "<INVALID>"


            # Display numeric values without unnecessary trailing zeros.
            return (
                f"{float(row['numeric_value']):.12g}"
            )


        # Boolean values become True or False.
        if row[
            "value_type"
        ] == "Boolean":


            # Invalid Boolean input receives an explicit warning.
            if pd.isna(
                row[
                    "boolean_value"
                ]
            ):

                return "<INVALID>"


            # Return readable Boolean value.
            return str(
                bool(
                    row[
                        "boolean_value"
                    ]
                )
            )


        # Text values are returned as text.
        if pd.notna(
            row[
                "text_value"
            ]
        ):

            return str(
                row[
                    "text_value"
                ]
            )


        # Missing Text value is explicitly identified.
        return "<INVALID>"


    # Apply the display helper to every rule.
    result[
        "parameter_value_display"
    ] = result.apply(

        build_display_value,

        axis=1
    )


    # Return the typed rule catalogue.
    return result


# =============================================================================
# SECTION 58 — SELECT ACTIVE RULES
# =============================================================================


# Define a function that keeps only rules effective on the valuation date.
def select_active_plan_rules(
    typed_rules,
):


    # Select only active rule rows.
    active_rules = typed_rules.loc[

        typed_rules[
            "active_at_valuation_flag"
        ]

    ].copy()


    # Reset the pandas row index for a clean working table.
    active_rules = active_rules.reset_index(
        drop=True
    )


    # Return active rules.
    return active_rules


# =============================================================================
# SECTION 59 — RETRIEVE ONE PLAN PARAMETER
# =============================================================================


# Define the central parameter-retrieval function.
#
# Later actuarial engines will call this function instead of manually
# searching the CSV every time they need a plan parameter.
def get_plan_parameter(
    active_rules,
    plan_id,
    parameter_name,
    default=None,
):


    # Select the requested plan and parameter.
    match = active_rules.loc[

        active_rules[
            "plan_id"
        ].eq(
            plan_id
        )

        & active_rules[
            "parameter_name"
        ].eq(
            parameter_name
        )

    ]


    # If no active rule exists,
    # return the supplied default value.
    if len(
        match
    ) == 0:

        return default


    # More than one active value for the same plan/parameter
    # is a governance failure because the model would not know which one to use.
    if len(
        match
    ) != 1:

        raise ValueError(

            "Expected exactly one active rule for "
            f"{plan_id} / {parameter_name}, "
            f"found {len(match)}."
        )


    # Extract the unique rule row.
    rule = match.iloc[
        0
    ]


    # Return Numeric values as Python float.
    if rule[
        "value_type"
    ] == "Numeric":

        return float(
            rule[
                "numeric_value"
            ]
        )


    # Return Boolean values as Python bool.
    if rule[
        "value_type"
    ] == "Boolean":

        return bool(
            rule[
                "boolean_value"
            ]
        )


    # Return Text values as Python string.
    return str(
        rule[
            "text_value"
        ]
    )


# =============================================================================
# SECTION 60 — CONTROLLED DASHBOARD OVERRIDE ENGINE
# =============================================================================


# Define a helper that parses one future dashboard override
# according to the parameter's declared datatype.
def parse_override_value(
    value,
    value_type,
):


    # -------------------------------------------------------------------------
    # NUMERIC OVERRIDE
    # -------------------------------------------------------------------------


    if value_type == "Numeric":


        # Attempt numeric conversion.
        parsed_value = pd.to_numeric(

            pd.Series(
                [
                    value
                ]
            ),

            errors="coerce"

        ).iloc[
            0
        ]


        # Reject invalid numeric input.
        if pd.isna(
            parsed_value
        ):

            raise ValueError(

                f"Invalid Numeric override: {value}"
            )


        # Return Python float.
        return float(
            parsed_value
        )


    # -------------------------------------------------------------------------
    # BOOLEAN OVERRIDE
    # -------------------------------------------------------------------------


    if value_type == "Boolean":


        # Parse Boolean using the same controlled parser.
        parsed_value = parse_boolean_rule_value(
            value
        )


        # Reject invalid Boolean input.
        if pd.isna(
            parsed_value
        ):

            raise ValueError(

                f"Invalid Boolean override: {value}"
            )


        # Return Python bool.
        return bool(
            parsed_value
        )


    # -------------------------------------------------------------------------
    # TEXT OVERRIDE
    # -------------------------------------------------------------------------


    if value_type == "Text":


        # Reject missing or blank text.
        if (

            pd.isna(
                value
            )

            or str(
                value
            ).strip() == ""
        ):

            raise ValueError(
                "Text override cannot be blank."
            )


        # Return trimmed string.
        return str(
            value
        ).strip()


    # Reject an unsupported datatype.
    raise ValueError(

        f"Unsupported value_type: {value_type}"
    )


# -----------------------------------------------------------------------------


# Define the function that will later allow Streamlit
# to apply controlled plan-parameter changes.
def apply_controlled_rule_overrides(
    active_rules,
    override_table=None,
):


    # Work on a copy.
    result = active_rules.copy()


    # Preserve the original base value.
    result[
        "base_parameter_value_display"
    ] = result[
        "parameter_value_display"
    ]


    # No override has been applied initially.
    result[
        "override_applied_flag"
    ] = False


    # Store the future source of any override.
    result[
        "override_source"
    ] = pd.NA


    # If no override table is supplied,
    # simply return the base plan rules.
    if (

        override_table is None

        or len(
            override_table
        ) == 0
    ):

        return result


    # Define columns required in a future override table.
    required_override_columns = {

        "plan_id",

        "parameter_name",

        "override_value",
    }


    # Validate override-table structure.
    if not required_override_columns.issubset(
        override_table.columns
    ):

        raise ValueError(

            "Override table must contain: "
            "plan_id, parameter_name, override_value."
        )


    # Examine each requested override.
    for override in override_table.itertuples(
        index=False
    ):


        # Find the unique active rule being changed.
        matching_indices = result.index[

            result[
                "plan_id"
            ].eq(
                override.plan_id
            )

            & result[
                "parameter_name"
            ].eq(
                override.parameter_name
            )

        ].tolist()


        # The requested plan/parameter must exist exactly once.
        if len(
            matching_indices
        ) != 1:

            raise ValueError(

                "Override target must identify exactly one "
                f"active rule: {override.plan_id} / "
                f"{override.parameter_name}"
            )


        # Get the unique row index.
        index = matching_indices[
            0
        ]


        # Reject any parameter that is not explicitly editable.
        if not bool(

            result.at[

                index,

                "effective_dashboard_editable_flag"
            ]
        ):

            raise ValueError(

                f"Parameter is locked and cannot be overridden: "
                f"{override.plan_id} / "
                f"{override.parameter_name}"
            )


        # Read the parameter's declared datatype.
        value_type = result.at[

            index,

            "value_type"
        ]


        # Parse the proposed value safely.
        parsed_override = parse_override_value(

            override.override_value,

            value_type
        )


        # -------------------------------------------------------------
        # WRITE NUMERIC OVERRIDE
        # -------------------------------------------------------------


        if value_type == "Numeric":

            result.at[

                index,

                "numeric_value"

            ] = parsed_override


            result.at[

                index,

                "parameter_value_display"

            ] = f"{float(parsed_override):.12g}"


        # -------------------------------------------------------------
        # WRITE BOOLEAN OVERRIDE
        # -------------------------------------------------------------


        elif value_type == "Boolean":

            result.at[

                index,

                "boolean_value"

            ] = parsed_override


            result.at[

                index,

                "parameter_value_display"

            ] = str(
                bool(
                    parsed_override
                )
            )


        # -------------------------------------------------------------
        # WRITE TEXT OVERRIDE
        # -------------------------------------------------------------


        else:

            result.at[

                index,

                "text_value"

            ] = parsed_override


            result.at[

                index,

                "parameter_value_display"

            ] = str(
                parsed_override
            )


        # Record that an override was actually applied.
        result.at[

            index,

            "override_applied_flag"

        ] = True


        # Record future override source.
        result.at[

            index,

            "override_source"

        ] = "Dashboard_or_Scenario"


    # Return the selected rule set.
    return result


# =============================================================================
# SECTION 61 — BUILD FORMULA REGISTRY REPORT
# =============================================================================


# Define a function that converts our Python formula-template dictionary
# into a DataFrame that can be saved as project documentation.
def build_formula_template_registry():

    
    # Create one output row for every registered formula template.
    rows = []


    # Loop through the controlled registry.
    for (
        formula_template,
        metadata
    ) in FORMULA_TEMPLATE_REGISTRY.items():


        # Add one documentation row.
        rows.append({

            "formula_template":
                formula_template,

            "formula_family":
                metadata[
                    "formula_family"
                ],

            "purpose":
                metadata[
                    "purpose"
                ],

            # Formula templates are never directly editable.
            "formula_template_editable_flag":
                False,

            "rule_engine_version":
                RULE_ENGINE_VERSION,
        })


    # Convert documentation rows into a DataFrame.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# SECTION 62 — BUILD PLAN INVENTORY
# =============================================================================


# Define a function that summarizes the active architecture
# of every employee-benefit plan.
def build_plan_inventory(
    active_rules,
):


    # Create an empty list for one row per plan.
    rows = []


    # Group active rules by unique plan and product.
    for (
        plan_id,
        product_type
    ), plan_rules in active_rules.groupby(

        [
            "plan_id",
            "product_type",
        ]
    ):


        # Collect all formula templates used by this plan.
        formula_templates = sorted(

            plan_rules[
                "formula_template"
            ]

            .dropna()

            .unique()
        )


        # Add one plan-level inventory row.
        rows.append({

            # Plan identifier.
            "plan_id":
                plan_id,

            # Product represented by plan.
            "product_type":
                product_type,

            # Number of active rule rows.
            "active_rule_count":
                len(
                    plan_rules
                ),

            # Number of distinct parameters.
            "parameter_count":
                plan_rules[
                    "parameter_name"
                ].nunique(),

            # Number of parameters the dashboard may change.
            "editable_parameter_count":
                int(

                    plan_rules[
                        "effective_dashboard_editable_flag"
                    ].sum()
                ),

            # Number of locked parameters.
            "locked_parameter_count":
                int(

                    (
                        ~plan_rules[
                            "effective_dashboard_editable_flag"
                        ]
                    ).sum()
                ),

            # Number of calculation templates used.
            "formula_template_count":
                len(
                    formula_templates
                ),

            # Human-readable formula list.
            "formula_templates":
                " | ".join(
                    formula_templates
                ),

            # EDLI statutory plans will be fully locked.
            "statutory_locked_plan_flag":
                bool(

                    plan_rules[
                        "statutory_locked_flag"
                    ].all()
                ),

            # Store rule-engine version.
            "rule_engine_version":
                RULE_ENGINE_VERSION,
        })


    # Convert list into a DataFrame.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# SECTION 63 — REQUIRED-PARAMETER VALIDATION
# =============================================================================


# Define a function that proves every plan contains
# the parameters required by its calculation architecture.
def build_required_parameter_validation(
    active_rules,
):


    # Create an empty output list.
    rows = []


    # Examine every active plan separately.
    for (
        plan_id,
        product_type
    ), plan_rules in active_rules.groupby(

        [
            "plan_id",
            "product_type",
        ]
    ):


        # Start with product-specific required parameters.
        required_parameters = list(

            REQUIRED_PARAMETERS_BY_PRODUCT.get(

                product_type,

                []
            )
        )


        # GTI requirements depend on selected cover structure.
        if product_type == "GTI":


            # Retrieve this plan's GTI cover basis.
            cover_basis = get_plan_parameter(

                active_rules,

                plan_id,

                "cover_basis",

                default=None
            )


            # Every GTI plan needs common parameters.
            required_parameters = list(

                GTI_COMMON_REQUIRED_PARAMETERS
            )


            # Add cover-structure-specific parameters.
            required_parameters += list(

                GTI_COVER_REQUIRED_PARAMETERS.get(

                    cover_basis,

                    []
                )
            )


        # Store actual parameter names in this plan.
        actual_parameters = set(

            plan_rules[
                "parameter_name"
            ]
        )


        # Find required parameters not present in the plan.
        missing_parameters = [

            parameter

            for parameter
            in required_parameters

            if parameter
            not in actual_parameters
        ]


        # Add one plan-level validation row.
        rows.append({

            "plan_id":
                plan_id,

            "product_type":
                product_type,

            "required_parameter_count":
                len(
                    required_parameters
                ),

            "active_parameter_count":
                len(
                    actual_parameters
                ),

            "missing_required_parameter_count":
                len(
                    missing_parameters
                ),

            "missing_required_parameters":
                ", ".join(
                    missing_parameters
                ),

            "required_parameters_complete_flag":
                len(
                    missing_parameters
                ) == 0,
        })


    # Return validation table.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# SECTION 64 — NUMERIC PARAMETER DOMAIN VALIDATION
# =============================================================================


# Define a function that checks mathematical validity
# of important numeric parameter values.
def build_parameter_domain_validation(
    active_rules,
):


    # Create an empty list.
    rows = []


    # Parameters mathematically constrained to the closed interval [0, 1].
    closed_unit_interval_parameters = {

        "disability_annual_q",

        "employer_contribution_rate",

        "employee_contribution_rate",

        "annual_charges_rate",

        "accrual_rate",

        "spouse_pension_percentage",

        "pf_component_rate",
    }


    # Gross premium loading must be less than one because:
    #
    # Gross Premium
    # =
    # Adjusted Expected Claims / (1 - loading)
    #
    # loading = 1 would make the denominator zero.
    open_upper_unit_interval_parameters = {

        "gross_premium_loading_rate",
    }


    # Growth/discount assumptions must remain greater than -1
    # so the compounding base 1 + rate remains positive.
    compounding_rate_parameters = {

        "salary_escalation_rate",

        "discount_rate",

        "expected_investment_return",

        "pension_escalation_rate",
    }


    # Parameters that must be strictly positive.
    positive_parameters = {

        "benefit_days",

        "divisor_days",

        "mortality_c",

        "weibull_eta",

        "weibull_k",

        "retirement_age",

        "salary_multiple",

        "credibility_confidence_z",

        "credibility_tolerance_k",

        "wage_factor",

        "wage_ceiling_monthly",

        "pf_component_cap",

        "illustrative_minimum_benefit",

        "illustrative_maximum_benefit",

        "part_a_minimum_floor",

        "flat_sum_assured",

        "free_cover_limit",

        "minimum_cover",

        "maximum_cover",

        "E1_cover",

        "E2_cover",

        "E3_cover",

        "E4_cover",

        "E5_cover",

        "E6_cover",

        "E7_cover",

        "E8_cover",
    }


    # Parameters that may equal zero but cannot be negative.
    nonnegative_parameters = {

        "vesting_years_resignation",

        "part_year_rounding_threshold_months",

        "mortality_A",

        "mortality_B",

        "continuity_gap_days",
    }


    # Examine every active rule.
    for rule in active_rules.itertuples():


        # Domain checks below apply only to Numeric parameters.
        if rule.value_type != "Numeric":

            continue


        # Capture numeric parameter value.
        value = rule.numeric_value


        # Start with no additional hard constraint.
        valid = True


        # Store a human-readable mathematical rule.
        domain_rule = (
            "No additional hard domain rule"
        )


        # -------------------------------------------------------------
        # CLOSED UNIT INTERVAL
        # -------------------------------------------------------------


        if rule.parameter_name in (
            closed_unit_interval_parameters
        ):

            valid = (

                pd.notna(
                    value
                )

                and 0
                <= value
                <= 1
            )


            domain_rule = (
                "0 <= value <= 1"
            )


        # -------------------------------------------------------------
        # [0, 1) INTERVAL
        # -------------------------------------------------------------


        elif rule.parameter_name in (
            open_upper_unit_interval_parameters
        ):

            valid = (

                pd.notna(
                    value
                )

                and 0
                <= value
                < 1
            )


            domain_rule = (
                "0 <= value < 1"
            )


        # -------------------------------------------------------------
        # COMPOUNDING RATE
        # -------------------------------------------------------------


        elif rule.parameter_name in (
            compounding_rate_parameters
        ):

            valid = (

                pd.notna(
                    value
                )

                and value > -1
            )


            domain_rule = (
                "value > -1 so 1 + rate remains positive"
            )


        # -------------------------------------------------------------
        # STRICTLY POSITIVE
        # -------------------------------------------------------------


        elif rule.parameter_name in (
            positive_parameters
        ):

            valid = (

                pd.notna(
                    value
                )

                and value > 0
            )


            domain_rule = (
                "value > 0"
            )


        # -------------------------------------------------------------
        # NONNEGATIVE
        # -------------------------------------------------------------


        elif rule.parameter_name in (
            nonnegative_parameters
        ):

            valid = (

                pd.notna(
                    value
                )

                and value >= 0
            )


            domain_rule = (
                "value >= 0"
            )


        # Add numeric-domain result.
        rows.append({

            "plan_id":
                rule.plan_id,

            "product_type":
                rule.product_type,

            "parameter_name":
                rule.parameter_name,

            "numeric_value":
                value,

            "domain_rule":
                domain_rule,

            "domain_valid_flag":
                bool(
                    valid
                ),
        })


    # Convert all ordinary numeric checks into a DataFrame.
    validation = pd.DataFrame(
        rows
    )


    # -------------------------------------------------------------------------
    # 64.1 — GTI MINIMUM / MAXIMUM COVER RELATIONSHIP
    # -------------------------------------------------------------------------


    # Examine every active GTI plan.
    for plan_id in active_rules.loc[

        active_rules[
            "product_type"
        ].eq(
            "GTI"
        ),

        "plan_id"

    ].unique():


        # Identify GTI cover structure.
        cover_basis = get_plan_parameter(

            active_rules,

            plan_id,

            "cover_basis",

            default=None
        )


        # Salary-multiple GTI uses minimum and maximum cover limits.
        if cover_basis == "Salary Multiple":


            # Retrieve minimum cover.
            minimum_cover = get_plan_parameter(

                active_rules,

                plan_id,

                "minimum_cover"
            )


            # Retrieve maximum cover.
            maximum_cover = get_plan_parameter(

                active_rules,

                plan_id,

                "maximum_cover"
            )


            # Validate ordering.
            validation.loc[

                len(
                    validation
                )

            ] = {

                "plan_id":
                    plan_id,

                "product_type":
                    "GTI",

                "parameter_name":
                    "minimum_cover <= maximum_cover",

                "numeric_value":
                    np.nan,

                "domain_rule":
                    "minimum_cover <= maximum_cover",

                "domain_valid_flag":
                    bool(
                        minimum_cover
                        <= maximum_cover
                    ),
            }


    # Return mathematical-domain validation.
    return validation


# =============================================================================
# SECTION 65 — FORMULA / PRODUCT VALIDATION
# =============================================================================


# Define a function that checks whether each rule's formula template
# is appropriate for its product.
def build_formula_product_validation(
    active_rules,
):


    # Create one validation row per active rule.
    rows = []


    # Examine every active rule.
    for rule in active_rules.itertuples():


        # Retrieve the set of allowed formula templates for this product.
        allowed_templates = (

            ALLOWED_FORMULAS_BY_PRODUCT.get(

                rule.product_type,

                set()
            )
        )


        # Add validation result.
        rows.append({

            "plan_id":
                rule.plan_id,

            "product_type":
                rule.product_type,

            "parameter_name":
                rule.parameter_name,

            "formula_template":
                rule.formula_template,

            "formula_product_valid_flag":
                rule.formula_template
                in allowed_templates,
        })


    # Return validation table.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# SECTION 66 — SALARY / COLUMN REFERENCE VALIDATION
# =============================================================================


# Define a function that checks whether a rule referring to a data column
# points to an actual employee model-ready field.
def build_column_reference_validation(
    active_rules,
    employee_features,
):


    # Select rules whose unit explicitly says the parameter
    # represents a DataFrame column name.
    column_rules = active_rules.loc[

        active_rules[
            "unit"
        ].eq(
            "column"
        )

    ].copy()


    # The selected text value is the referenced employee field.
    column_rules[
        "referenced_column"
    ] = column_rules[
        "text_value"
    ].astype(
        "string"
    )


    # Validate that the referenced field exists.
    column_rules[
        "column_reference_valid_flag"
    ] = column_rules[
        "referenced_column"
    ].isin(
        employee_features.columns
    )


    # Return compact report.
    return column_rules[[

        "plan_id",

        "product_type",

        "parameter_name",

        "referenced_column",

        "formula_template",

        "column_reference_valid_flag",
    ]]


# =============================================================================
# SECTION 67 — PLAN PARAMETER MATRIX
# =============================================================================


# Define a function that converts the long-format rule table
# into one human-readable wide row per plan.
def build_plan_parameter_matrix(
    active_rules,
):


    # Pivot:
    #
    # rows   = plan
    # columns = parameter_name
    # values = resolved parameter value
    matrix = active_rules.pivot_table(

        index=[

            "plan_id",

            "product_type",
        ],

        columns=
            "parameter_name",

        values=
            "parameter_value_display",

        aggfunc=
            "first"
    )


    # Convert plan identifiers back into ordinary columns.
    matrix = matrix.reset_index()


    # Remove the pandas columns-axis label created by pivot_table.
    matrix = matrix.rename_axis(
        None,
        axis=1
    )


    # Return wide plan matrix.
    return matrix


# =============================================================================
# SECTION 68 — DASHBOARD PARAMETER CATALOGUE
# =============================================================================


# Define a function that tells our future Streamlit dashboard
# exactly which assumptions are editable and which must remain locked.
def build_dashboard_parameter_catalogue(
    active_rules,
):


    # Work on a copy.
    result = active_rules.copy()


    # The current rule value becomes the base case.
    result[
        "base_parameter_value"
    ] = result[
        "base_parameter_value_display"
    ]


    # The currently selected value is the base case
    # because Pipeline 05 is not applying a scenario override.
    result[
        "selected_parameter_value"
    ] = result[
        "parameter_value_display"
    ]


    # No dashboard override has been applied during this batch run.
    result[
        "override_applied_flag"
    ] = result[
        "override_applied_flag"
    ].fillna(
        False
    )


    # -------------------------------------------------------------------------
    # 68.1 — DETERMINE FUTURE STREAMLIT CONTROL TYPE
    # -------------------------------------------------------------------------


    # Default every parameter to a locked display.
    result[
        "input_control_type"
    ] = "locked_display"


    # Editable Numeric parameters will use number inputs.
    result.loc[

        result[
            "effective_dashboard_editable_flag"
        ]

        & result[
            "value_type"
        ].eq(
            "Numeric"
        ),

        "input_control_type"

    ] = "number_input"


    # Editable Boolean parameters will use checkboxes.
    result.loc[

        result[
            "effective_dashboard_editable_flag"
        ]

        & result[
            "value_type"
        ].eq(
            "Boolean"
        ),

        "input_control_type"

    ] = "checkbox"


    # Editable Text parameters will use controlled selection,
    # not arbitrary executable formula text.
    result.loc[

        result[
            "effective_dashboard_editable_flag"
        ]

        & result[
            "value_type"
        ].eq(
            "Text"
        ),

        "input_control_type"

    ] = "controlled_select"


    # Formula template itself remains locked.
    result[
        "formula_template_editable_flag"
    ] = False


    # Return the dashboard configuration table.
    return result[[

        "plan_id",

        "product_type",

        "rule_category",

        "parameter_name",

        "base_parameter_value",

        "selected_parameter_value",

        "value_type",

        "unit",

        "formula_template",

        "effective_dashboard_editable_flag",

        "statutory_locked_flag",

        "input_control_type",

        "formula_template_editable_flag",

        "source_reference",
    ]]


# =============================================================================
# SECTION 69 — EMPLOYEE-PLAN ASSIGNMENT ENGINE
# =============================================================================


# Define the function that connects active employees
# to their applicable product plans.
def build_employee_plan_assignments(
    employee_features,
    active_rules,
    plan_inventory,
):


    # Create a list that will hold one table per product.
    assignment_tables = []


    # -------------------------------------------------------------------------
    # 69.1 — GRATUITY
    # -------------------------------------------------------------------------


    # Select active Gratuity members.
    gratuity = employee_features.loc[

        employee_features[
            "active_gratuity_member_flag"
        ],

        [

            "employee_id",

            "gratuity_plan_id",

            "model_input_quality_status",

            "grade",

            "age_band",

            "service_band",
        ]

    ].copy()


    # Standardize the product-specific plan column to generic plan_id.
    gratuity = gratuity.rename(

        columns={

            "gratuity_plan_id":
                "plan_id"
        }
    )


    # Store the corresponding product.
    gratuity[
        "product_type"
    ] = "Gratuity"


    # Document where the plan assignment came from.
    gratuity[
        "plan_assignment_method"
    ] = "Employee gratuity_plan_id"


    # Add Gratuity assignments.
    assignment_tables.append(
        gratuity
    )


    # -------------------------------------------------------------------------
    # 69.2 — DEFINED BENEFIT PENSION
    # -------------------------------------------------------------------------


    # Select active DB Pension members.
    db_pension = employee_features.loc[

        employee_features[
            "active_db_pension_member_flag"
        ],

        [

            "employee_id",

            "superannuation_plan_id",

            "model_input_quality_status",

            "grade",

            "age_band",

            "service_band",
        ]

    ].copy()


    # Standardize plan column.
    db_pension = db_pension.rename(

        columns={

            "superannuation_plan_id":
                "plan_id"
        }
    )


    # Store DB product type.
    db_pension[
        "product_type"
    ] = "DB_Pension"


    # Document assignment source.
    db_pension[
        "plan_assignment_method"
    ] = "Employee superannuation_plan_id"


    # Add DB assignments.
    assignment_tables.append(
        db_pension
    )


    # -------------------------------------------------------------------------
    # 69.3 — DEFINED CONTRIBUTION SUPERANNUATION
    # -------------------------------------------------------------------------


    # Select active DC members.
    dc_superannuation = employee_features.loc[

        employee_features[
            "active_dc_superannuation_member_flag"
        ],

        [

            "employee_id",

            "superannuation_plan_id",

            "model_input_quality_status",

            "grade",

            "age_band",

            "service_band",
        ]

    ].copy()


    # Standardize plan column.
    dc_superannuation = dc_superannuation.rename(

        columns={

            "superannuation_plan_id":
                "plan_id"
        }
    )


    # Store DC product type.
    dc_superannuation[
        "product_type"
    ] = "DC_Superannuation"


    # Document assignment source.
    dc_superannuation[
        "plan_assignment_method"
    ] = "Employee superannuation_plan_id"


    # Add DC assignments.
    assignment_tables.append(
        dc_superannuation
    )


    # -------------------------------------------------------------------------
    # 69.4 — EDLI
    # -------------------------------------------------------------------------


    # Obtain distinct EDLI plans effective at valuation date.
    active_edli_plan_ids = active_rules.loc[

        active_rules[
            "product_type"
        ].eq(
            "EDLI"
        ),

        "plan_id"

    ].dropna().unique()


    # Because the employee master does not carry a free-form EDLI plan ID,
    # exactly one statutory rule set should be effective on the valuation date.
    if len(
        active_edli_plan_ids
    ) == 1:

        current_edli_plan_id = (
            active_edli_plan_ids[
                0
            ]
        )


    # If zero or multiple statutory EDLI plans are active,
    # leave the assignment unresolved so validation fails visibly.
    else:

        current_edli_plan_id = pd.NA


    # Select active EDLI-covered employees.
    edli = employee_features.loc[

        employee_features[
            "active_edli_member_flag"
        ],

        [

            "employee_id",

            "model_input_quality_status",

            "grade",

            "age_band",

            "service_band",
        ]

    ].copy()


    # Assign the single effective statutory EDLI rule.
    edli[
        "plan_id"
    ] = current_edli_plan_id


    # Store product type.
    edli[
        "product_type"
    ] = "EDLI"


    # Record assignment method.
    edli[
        "plan_assignment_method"
    ] = (
        "Current effective-date statutory EDLI rule"
    )


    # Add EDLI assignments.
    assignment_tables.append(
        edli
    )


    # -------------------------------------------------------------------------
    # 69.5 — GROUP TERM INSURANCE
    # -------------------------------------------------------------------------


    # Select active GTI members.
    gti = employee_features.loc[

        employee_features[
            "active_gti_member_flag"
        ],

        [

            "employee_id",

            "gti_plan_id",

            "model_input_quality_status",

            "grade",

            "age_band",

            "service_band",
        ]

    ].copy()


    # Standardize plan column.
    gti = gti.rename(

        columns={

            "gti_plan_id":
                "plan_id"
        }
    )


    # Store product type.
    gti[
        "product_type"
    ] = "GTI"


    # Document assignment source.
    gti[
        "plan_assignment_method"
    ] = "Employee gti_plan_id"


    # Add GTI assignments.
    assignment_tables.append(
        gti
    )


    # -------------------------------------------------------------------------
    # 69.6 — COMBINE ALL PRODUCTS
    # -------------------------------------------------------------------------


    # Stack all employee-product assignments into one long table.
    assignments = pd.concat(

        assignment_tables,

        ignore_index=True
    )


    # -------------------------------------------------------------------------
    # 69.7 — ATTACH PLAN METADATA
    # -------------------------------------------------------------------------


    # Join plan inventory to prove the plan exists
    # and belongs to the expected product.
    assignments = assignments.merge(

        plan_inventory,

        on=[

            "plan_id",

            "product_type",
        ],

        how="left",

        indicator=True
    )


    # A plan assignment is valid only when:
    #
    # 1. plan_id exists, AND
    # 2. plan/product combination exists in the active plan inventory.
    assignments[
        "plan_assignment_valid_flag"
    ] = (

        assignments[
            "plan_id"
        ].notna()

        & assignments[
            "_merge"
        ].eq(
            "both"
        )
    )


    # Remove temporary merge diagnostic.
    assignments = assignments.drop(

        columns=[
            "_merge"
        ]
    )


    # Store rule-engine version on each employee-product assignment.
    assignments[
        "rule_engine_version"
    ] = RULE_ENGINE_VERSION


    # Return the long employee-plan map.
    return assignments


# =============================================================================
# SECTION 70 — ASSUMPTION CONSISTENCY REPORT
# =============================================================================


# Define a report that deliberately keeps financial assumptions
# in separate conceptual columns.
def build_assumption_consistency_report(
    active_rules,
):


    # Create an empty list for one row per plan.
    rows = []


    # Examine each plan.
    for (
        plan_id,
        product_type
    ), plan_rules in active_rules.groupby(

        [
            "plan_id",
            "product_type",
        ]
    ):


        # Add the major financial assumptions if applicable.
        rows.append({

            "plan_id":
                plan_id,

            "product_type":
                product_type,

            # Salary growth affects future salary-linked amounts.
            "salary_escalation_rate":
                get_plan_parameter(

                    active_rules,

                    plan_id,

                    "salary_escalation_rate",

                    default=np.nan
                ),

            # Discount rate values future DB cash flows today.
            "discount_rate":
                get_plan_parameter(

                    active_rules,

                    plan_id,

                    "discount_rate",

                    default=np.nan
                ),

            # Investment return accumulates DC corpus/assets.
            "expected_investment_return":
                get_plan_parameter(

                    active_rules,

                    plan_id,

                    "expected_investment_return",

                    default=np.nan
                ),

            # Pension escalation increases post-retirement pension.
            "pension_escalation_rate":
                get_plan_parameter(

                    active_rules,

                    plan_id,

                    "pension_escalation_rate",

                    default=np.nan
                ),

            # GTI loading converts adjusted expected claims into premium.
            "gross_premium_loading_rate":
                get_plan_parameter(

                    active_rules,

                    plan_id,

                    "gross_premium_loading_rate",

                    default=np.nan
                ),

            # Preserve the conceptual rule from the book.
            "consistency_note":
                (
                    "Financial assumptions remain conceptually separate; "
                    "no equality constraint is imposed."
                ),
        })


    # Return one row per plan.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# SECTION 71 — SPECIAL PRODUCT GOVERNANCE VALIDATION
# =============================================================================


# Define additional checks that arise from specific product architecture.
def build_special_product_governance_validation(
    active_rules,
):


    # Create output list.
    rows = []


    # -------------------------------------------------------------------------
    # 71.1 — EDLI ACTIVE RULE SET
    # -------------------------------------------------------------------------


    # Count active EDLI plans.
    active_edli_plans = active_rules.loc[

        active_rules[
            "product_type"
        ].eq(
            "EDLI"
        ),

        "plan_id"

    ].dropna().unique()


    # Exactly one current EDLI plan should be active.
    edli_plan_count_valid = (

        len(
            active_edli_plans
        ) == 1
    )


    # Save the validation.
    rows.append({

        "check":
            "Exactly one active EDLI plan for employee assignment",

        "exceptions":
            (
                0
                if edli_plan_count_valid
                else 1
            ),

        "status":
            (
                "PASS"
                if edli_plan_count_valid
                else "FAIL"
            ),

        "note":
            (
                "EDLI is assigned from the effective-date statutory rule set."
            ),
    })


    # If exactly one EDLI plan exists, inspect its statutory-calculator flag.
    if edli_plan_count_valid:


        # Retrieve plan identifier.
        edli_plan_id = active_edli_plans[
            0
        ]


        # Retrieve the rule requiring official calculator verification.
        official_calculator_required = get_plan_parameter(

            active_rules,

            edli_plan_id,

            "official_calculator_required",

            default=False
        )


        # Validate that official calculator verification remains required.
        official_calculator_valid = (

            official_calculator_required
            is True
        )


        # Save validation.
        rows.append({

            "check":
                "EDLI official calculator required flag is True",

            "exceptions":
                (
                    0
                    if official_calculator_valid
                    else 1
                ),

            "status":
                (
                    "PASS"
                    if official_calculator_valid
                    else "FAIL"
                ),

            "note":
                (
                    "Synthetic mechanics do not override official "
                    "date-sensitive EDLI processing."
                ),
        })


    # -------------------------------------------------------------------------
    # 71.2 — GTI COVER-BASIS / FORMULA RELATIONSHIP
    # -------------------------------------------------------------------------


    # Define the formula architecture required by each GTI cover type.
    expected_gti_formula = {

        "Flat":
            "gti_flat_cover",

        "Salary Multiple":
            "gti_salary_multiple",

        "Grade Based":
            "gti_grade_based",
    }


    # Examine every GTI plan.
    for plan_id in active_rules.loc[

        active_rules[
            "product_type"
        ].eq(
            "GTI"
        ),

        "plan_id"

    ].unique():


        # Retrieve selected cover basis.
        cover_basis = get_plan_parameter(

            active_rules,

            plan_id,

            "cover_basis",

            default=None
        )


        # Determine required controlled formula template.
        expected_template = (

            expected_gti_formula.get(
                cover_basis
            )
        )


        # Collect formula templates actually present in the plan.
        actual_templates = set(

            active_rules.loc[

                active_rules[
                    "plan_id"
                ].eq(
                    plan_id
                ),

                "formula_template"

            ]
        )


        # Validate correct cover architecture.
        cover_formula_valid = (

            expected_template
            is not None

            and expected_template
            in actual_templates
        )


        # Save plan-specific GTI validation.
        rows.append({

            "check":
                (
                    f"{plan_id} cover basis maps "
                    "to controlled formula template"
                ),

            "exceptions":
                (
                    0
                    if cover_formula_valid
                    else 1
                ),

            "status":
                (
                    "PASS"
                    if cover_formula_valid
                    else "FAIL"
                ),

            "note":
                (
                    f"cover_basis={cover_basis}; "
                    f"expected_template={expected_template}"
                ),
        })


    # Return special product governance table.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# SECTION 72 — MASTER PLAN-RULE VALIDATION
# =============================================================================


# Define the final Pipeline 05 validation table.
def build_plan_rule_validation(
    typed_rules,
    active_rules,
    required_parameter_validation,
    parameter_domain_validation,
    formula_product_validation,
    column_reference_validation,
    employee_plan_assignments,
):


    # Create validation-result list.
    validation_rows = []


    # Define a reusable helper for adding one validation result.
    def add_validation(
        check,
        exceptions,
        note="",
    ):


        # Convert count to ordinary integer.
        exception_count = int(
            exceptions
        )


        # Zero exceptions means PASS.
        status = (

            "PASS"

            if exception_count == 0

            else "FAIL"
        )


        # Store validation row.
        validation_rows.append({

            "check":
                check,

            "exceptions":
                exception_count,

            "status":
                status,

            "note":
                note,
        })


    # -------------------------------------------------------------------------
    # 72.1 — RULE ID UNIQUENESS
    # -------------------------------------------------------------------------


    # Every rule_id should identify one rule.
    add_validation(

        "rule_id is unique",

        typed_rules[
            "rule_id"
        ].duplicated().sum(),
    )


    # -------------------------------------------------------------------------
    # 72.2 — VALUE TYPE LABELS
    # -------------------------------------------------------------------------


    # Validate declared value-type labels.
    add_validation(

        "value_type is supported",

        (

            ~typed_rules[
                "value_type"
            ].isin(
                SUPPORTED_VALUE_TYPES
            )

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 72.3 — EDITABILITY LABELS
    # -------------------------------------------------------------------------


    # Validate source Yes / No dashboard labels.
    add_validation(

        "dashboard_editable_flag is supported",

        (

            ~typed_rules[
                "dashboard_editable_flag"
            ].isin(
                SUPPORTED_EDITABILITY_VALUES
            )

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 72.4 — PARAMETER VALUE PARSING
    # -------------------------------------------------------------------------


    # Confirm parameter values parse according to declared datatype.
    add_validation(

        "rule values parse by declared value_type",

        (

            ~typed_rules[
                "value_parse_success_flag"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 72.5 — FORMULA REGISTRY
    # -------------------------------------------------------------------------


    # Confirm every formula template is registered.
    add_validation(

        "formula templates are registered",

        (

            ~typed_rules[
                "formula_supported_flag"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 72.6 — ACTIVE RULE CONFLICT
    # -------------------------------------------------------------------------


    # More than one active rule for the same plan/parameter is ambiguous.
    active_rule_conflicts = (

        active_rules.duplicated(

            [

                "plan_id",

                "parameter_name",
            ],

            keep=False
        )
    )


    # Validate uniqueness of current parameter values.
    add_validation(

        "one active rule per plan and parameter",

        active_rule_conflicts.sum(),
    )


    # -------------------------------------------------------------------------
    # 72.7 — REQUIRED PARAMETERS
    # -------------------------------------------------------------------------


    # Count plans missing required parameters.
    add_validation(

        "required parameters complete",

        (

            ~required_parameter_validation[
                "required_parameters_complete_flag"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 72.8 — NUMERIC DOMAINS
    # -------------------------------------------------------------------------


    # Count mathematically invalid numeric parameters.
    add_validation(

        "numeric parameter domains valid",

        (

            ~parameter_domain_validation[
                "domain_valid_flag"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 72.9 — PRODUCT / FORMULA RELATIONSHIP
    # -------------------------------------------------------------------------


    # Ensure formula templates belong to the correct product.
    add_validation(

        "formula templates match product",

        (

            ~formula_product_validation[
                "formula_product_valid_flag"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 72.10 — COLUMN REFERENCES
    # -------------------------------------------------------------------------


    # Ensure salary-basis rules refer to actual model-ready columns.
    add_validation(

        "column-based parameters reference valid employee fields",

        (

            ~column_reference_validation[
                "column_reference_valid_flag"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 72.11 — EMPLOYEE PLAN ASSIGNMENT
    # -------------------------------------------------------------------------


    # Every employee-product record must connect to a valid active plan.
    add_validation(

        "employee plan assignments valid",

        (

            ~employee_plan_assignments[
                "plan_assignment_valid_flag"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 72.12 — EDLI DASHBOARD LOCK
    # -------------------------------------------------------------------------


    # No EDLI statutory parameter may be freely dashboard-editable.
    add_validation(

        "EDLI rules remain dashboard locked",

        active_rules.loc[

            active_rules[
                "product_type"
            ].eq(
                "EDLI"
            ),

            "effective_dashboard_editable_flag"

        ].sum(),

        note=(
            "EDLI is effective-date/statutory rather than "
            "a freely user-designed benefit formula."
        ),
    )


    # -------------------------------------------------------------------------
    # 72.13 — SOURCE REFERENCES
    # -------------------------------------------------------------------------


    # Every current active rule should contain a source/reference note.
    missing_source_reference = (

        active_rules[
            "source_reference"
        ].isna()

        | active_rules[
            "source_reference"
        ]
        .astype(
            "string"
        )
        .str.strip()
        .eq(
            ""
        )
    )


    # Validate rule provenance.
    add_validation(

        "active rules have source reference",

        missing_source_reference.sum(),
    )


    # Return complete Pipeline 05 validation report.
    return pd.DataFrame(
        validation_rows
    )


# =============================================================================
# SECTION 73 — PLAN-RULE GOVERNANCE SUMMARY
# =============================================================================


# Define a compact governance summary for README/dashboard reporting.
def build_plan_rule_governance_summary(
    active_rules,
    plan_inventory,
    employee_plan_assignments,
):


    # Calculate active plan count.
    active_plan_count = plan_inventory[
        "plan_id"
    ].nunique()


    # Calculate number of editable active parameters.
    editable_parameter_count = int(

        active_rules[
            "effective_dashboard_editable_flag"
        ].sum()
    )


    # Calculate number of locked active parameters.
    locked_parameter_count = int(

        (
            ~active_rules[
                "effective_dashboard_editable_flag"
            ]
        ).sum()
    )


    # Count EDLI statutory rules.
    edli_rule_count = int(

        active_rules[
            "product_type"
        ].eq(
            "EDLI"
        ).sum()
    )


    # Build governance metrics.
    return pd.DataFrame([


        {
            "metric":
                "valuation_date",

            "value":
                str(
                    VALUATION_DATE.date()
                ),
        },


        {
            "metric":
                "rule_engine_version",

            "value":
                RULE_ENGINE_VERSION,
        },


        {
            "metric":
                "active_rule_rows",

            "value":
                len(
                    active_rules
                ),
        },


        {
            "metric":
                "active_plans",

            "value":
                active_plan_count,
        },


        {
            "metric":
                "formula_templates_in_use",

            "value":
                active_rules[
                    "formula_template"
                ].nunique(),
        },


        {
            "metric":
                "dashboard_editable_parameters",

            "value":
                editable_parameter_count,
        },


        {
            "metric":
                "locked_parameters",

            "value":
                locked_parameter_count,
        },


        {
            "metric":
                "EDLI_statutory_locked_rules",

            "value":
                edli_rule_count,
        },


        {
            "metric":
                "employee_product_assignments",

            "value":
                len(
                    employee_plan_assignments
                ),
        },
    ])


# =============================================================================
# SECTION 74 — PIPELINE 05 CONTROLLER
# =============================================================================


# Define the main Pipeline 05 execution function.
def run_pipeline_05(
    cleaning_results,
    feature_results,
):


    # Print opening separator.
    print(
        "\n"
        + "=" * 72
    )


    # Print pipeline title.
    print(
        "PIPELINE 05 - "
        "DYNAMIC PLAN RULES & ACTUARIAL ASSUMPTIONS"
    )


    # Print valuation date.
    print(
        f"Valuation date: "
        f"{VALUATION_DATE.date()}"
    )


    # Print rule-engine version.
    print(
        f"Rule engine version: "
        f"{RULE_ENGINE_VERSION}"
    )


    # Print closing separator.
    print(
        "=" * 72
    )


    # -------------------------------------------------------------------------
    # STEP 74.1 — RETRIEVE CLEAN RULE DATA
    # -------------------------------------------------------------------------


    # Retrieve cleaned Pipeline 03 plan rules.
    clean_rules = (

        cleaning_results[
            "clean_data"
        ][
            "rules"
        ]
    )


    # Retrieve Pipeline 04 employee actuarial features.
    employee_features = (

        feature_results[
            "employee_features"
        ]
    )


    # -------------------------------------------------------------------------
    # STEP 74.2 — TYPE AND VERSION THE RULE TABLE
    # -------------------------------------------------------------------------


    # Convert generic CSV values into controlled datatypes.
    typed_rules = prepare_typed_rule_catalogue(

        clean_rules
    )


    # -------------------------------------------------------------------------
    # STEP 74.3 — SELECT RULES EFFECTIVE AT VALUATION DATE
    # -------------------------------------------------------------------------


    # Keep only rules applicable on 1 September 2026.
    active_rules = select_active_plan_rules(

        typed_rules
    )


    # -------------------------------------------------------------------------
    # STEP 74.4 — APPLY CONTROLLED OVERRIDES
    # -------------------------------------------------------------------------


    # Pipeline 05 base run uses no override table.
    #
