    # =============================================================================
# PIPELINE 09 - EDLI AND GROUP TERM INSURANCE ENGINE
# =============================================================================
#
# PURPOSE
# -------
#
# Pipeline 09 contains two death-benefit engines that must remain
# conceptually separate:
#
#     1. Employees' Deposit Linked Insurance (EDLI)
#     2. Group Term Insurance (GTI)
#
# EDLI is a statutory provident-fund-linked death benefit.
#
# GTI is an employer-designed insured death cover.
#
# The same death can trigger both benefits, but they must never be
# combined into one formula or one financial quantity.
#
#
# EDLI LOGIC
# ----------
#
# Current rule set
#     ->
# date-sensitive statutory parameters
#     ->
# wage component
#     ->
# Average Progressive Balance component where available
#     ->
# continuity test
#     ->
# official calculator review
#
#
# GTI LOGIC
# ---------
#
# Employee
#     ->
# employer-designed Sum Assured
#     ->
# mortality probability
#     ->
# expected claims
#     ->
# historical Actual-to-Expected
#     ->
# credibility
#     ->
# experience factor
#     ->
# fresh expected claim cost
#     ->
# gross premium
#
#
# IMPORTANT MODEL GOVERNANCE
# --------------------------
#
# Pipeline 09 does NOT fabricate:
#
#     - Average Progressive Balance,
#     - EDLI continuity history,
#     - historical EDLI rules before the current stored effective date,
#     - occupation loadings not present in the controlled rule table,
#     - reinsurance costs not present in the controlled rule table.
#
# Missing information is explicitly flagged instead.
#
# =============================================================================


# Store the formal Pipeline 09 model version.
P09_VERSION = "P09-C01"


# Create the dedicated Pipeline 09 report directory.
P09_OUTPUT_DIR = (
    PROJECT_ROOT
    / "Outputs"
    / "09_edli_gti"
)


# Create that folder if necessary.
P09_OUTPUT_DIR.mkdir(
    parents=True,
    exist_ok=True,
)


# Define a numerical tolerance for reconciliation tests.
P09_TOLERANCE = 1e-8


# =============================================================================
# P09 HELPER 01 - NORMALISE TEXT
# =============================================================================


# Define a reusable text-normalisation helper.
def p09_normalise_text(
    value,
):


    # Convert missing values into empty text.
    if pd.isna(
        value
    ):

        return ""


    # Convert the value to lower-case text.
    text = str(
        value
    ).strip().lower()


    # Remove spaces, hyphens and underscores.
    #
    # This allows labels such as:
    #
    # "Salary Multiple"
    # "salary_multiple"
    # "SALARY-MULTIPLE"
    #
    # to be interpreted consistently.
    return "".join(

        character

        for character in text

        if character.isalnum()
    )


# =============================================================================
# P09 HELPER 02 - BOOLEAN INTERPRETATION
# =============================================================================


# Define a safe Boolean converter.
def p09_to_bool(
    value,
):


    # Preserve real Boolean values directly.
    if isinstance(
        value,
        (
            bool,
            np.bool_,
        ),
    ):

        return bool(
            value
        )


    # Convert other values into normalised text.
    text = p09_normalise_text(
        value
    )


    # Recognise common positive representations.
    return text in {

        "true",

        "yes",

        "y",

        "1",

        "active",

        "covered",
    }


# =============================================================================
# P09 HELPER 03 - FIND FIRST AVAILABLE COLUMN
# =============================================================================


# Define a reusable function that searches several possible column names.
def p09_first_existing_column(
    dataframe,
    candidates,
    required=False,
):


    # Test candidate names one by one.
    for column in candidates:


        # Return the first available field.
        if column in dataframe.columns:

            return column


    # Stop transparently when a mandatory field is absent.
    if required:

        raise KeyError(

            "Pipeline 09 could not find any of these required columns: "
            f"{candidates}"
        )


    # Optional fields may legitimately be unavailable.
    return None


# =============================================================================
# P09 HELPER 04 - COMBINE GOVERNANCE STATUS MESSAGES
# =============================================================================


# Define a helper that combines several model-status messages.
def p09_combine_status(
    *statuses,
):


    # Keep meaningful non-OK messages only.
    messages = [

        str(
            status
        )

        for status in statuses

        if status
        not in {

            None,

            "",

            "OK",
        }
    ]


    # Remove duplicate messages while keeping their original order.
    messages = list(

        dict.fromkeys(
            messages
        )
    )


    # No exception means the row is clean.
    if len(
        messages
    ) == 0:

        return "OK"


    # Otherwise join all relevant governance messages.
    return " | ".join(
        messages
    )


# =============================================================================
# P09 HELPER 05 - SAFE OPTIONAL PLAN PARAMETER
# =============================================================================


# Define a non-failing rule lookup for optional parameters.
def p09_optional_parameter(
    lookup,
    plan_id,
    parameter_name,
    default=np.nan,
):


    # Create the plan/parameter dictionary key.
    key = (

        plan_id,

        parameter_name,
    )


    # Return stored value when available.
    if key in lookup:

        return lookup[
            key
        ]


    # Otherwise return the stated default.
    return default


# =============================================================================
# P09 HELPER 06 - CLAIM ACCEPTANCE FLAG
# =============================================================================


# Define a helper for determining whether a monetary claim
# should be treated as an accepted/paid claim amount.
def p09_claim_amount_accepted(
    status,
    amount,
):


    # Convert the claim amount safely.
    amount_numeric = pd.to_numeric(

        pd.Series(
            [amount]
        ),

        errors="coerce"

    ).iloc[
        0
    ]


    # Missing or non-positive amounts create no paid claim cost.
    if (
        pd.isna(
            amount_numeric
        )

        or amount_numeric <= 0
    ):

        return False


    # Normalise claim status.
    status_text = p09_normalise_text(
        status
    )


    # Explicitly rejected claim statuses are not paid claims.
    if status_text in {

        "denied",

        "rejected",

        "cancelled",

        "canceled",
    }:

        return False


    # Otherwise a positive recorded claim amount is treated
    # as an accepted monetary claim for experience analysis.
    return True


# =============================================================================
# P09 SECTION 01 - IDENTIFY CURRENT EDLI RULE SET
# =============================================================================


# Define a strict helper that finds the single active EDLI plan.
def p09_get_current_edli_plan_id(
    active_rules,
):


    # Extract active EDLI plan identifiers.
    edli_plan_ids = (

        active_rules.loc[

            active_rules[
                "product_type"
            ].eq(
                "EDLI"
            ),

            "plan_id"

        ]

        .dropna()

        .astype(
            str
        )

        .unique()
    )


    # Pipeline 09 expects exactly one current statutory EDLI rule set.
    if len(
        edli_plan_ids
    ) != 1:

        raise ValueError(

            "Pipeline 09 expected exactly one active EDLI statutory "
            f"plan but found {len(edli_plan_ids)}."
        )


    # Return that statutory plan ID.
    return edli_plan_ids[
        0
    ]


# =============================================================================
# P09 SECTION 02 - BUILD EDLI EMPLOYEE STATUTORY BASIS
# =============================================================================


# Define the current EDLI employee-benefit basis.
def build_edli_employee_basis(
    employee_features,
    active_rules,
):


    # -------------------------------------------------------------------------
    # 02.1 - IDENTIFY THE CURRENT EDLI PLAN
    # -------------------------------------------------------------------------


    # Resolve the single effective EDLI rule set.
    edli_plan_id = p09_get_current_edli_plan_id(

        active_rules
    )


    # Build a typed plan-parameter lookup using the Pipeline 05 helper.
    lookup = build_plan_parameter_lookup(

        active_rules
    )


    # -------------------------------------------------------------------------
    # 02.2 - RETRIEVE EDLI STATUTORY PARAMETERS
    # -------------------------------------------------------------------------


    # Retrieve wage multiplication factor.
    wage_factor = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "wage_factor"
    )


    # Retrieve monthly wage ceiling.
    wage_ceiling = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "wage_ceiling_monthly"
    )


    # Retrieve provident-fund balance percentage.
    pf_component_rate = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "pf_component_rate"
    )


    # Retrieve maximum provident-fund component.
    pf_component_cap = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "pf_component_cap"
    )


    # Retrieve illustrative qualifying minimum for Part B.
    illustrative_minimum = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "illustrative_minimum_benefit"
    )


    # Retrieve illustrative overall maximum.
    illustrative_maximum = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "illustrative_maximum_benefit"
    )


    # Retrieve the current Part A minimum floor.
    part_a_floor = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "part_a_minimum_floor"
    )


    # Retrieve allowable continuity-gap parameter.
    continuity_gap_days = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "continuity_gap_days"
    )


    # Retrieve official-calculator governance flag.
    official_calculator_required = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "official_calculator_required"
    )


    # -------------------------------------------------------------------------
    # 02.3 - FIND ACTIVE EDLI MEMBERS
    # -------------------------------------------------------------------------


    # Confirm that Pipeline 04 created the active EDLI membership flag.
    edli_member_column = p09_first_existing_column(

        employee_features,

        [
            "active_edli_member_flag",
        ],

        required=True,
    )


    # Convert membership values safely into Booleans.
    edli_member_mask = employee_features[

        edli_member_column

    ].apply(
        p09_to_bool
    )


    # Keep active EDLI members.
    result = employee_features.loc[

        edli_member_mask

    ].copy()


    # Attach the effective statutory plan identifier.
    result[
        "edli_plan_id"
    ] = edli_plan_id


    # -------------------------------------------------------------------------
    # 02.4 - IDENTIFY WAGE INPUT
    # -------------------------------------------------------------------------


    # Prefer a genuine 12-month average wage field when one exists.
    wage_column = p09_first_existing_column(

        result,

        [

            "average_edli_wages_12m",

            "average_edli_wage_12m",

            "edli_average_wages_12m",

            "edli_eligible_wages_monthly",

            "current_edli_eligible_wages_monthly",
        ],

        required=True,
    )


    # Convert wage input into numeric form.
    result[
        "edli_wage_input_monthly"
    ] = pd.to_numeric(

        result[
            wage_column
        ],

        errors="coerce"
    )


    # Store which source column was used.
    result[
        "edli_wage_source_column"
    ] = wage_column


    # Determine whether this is a true historical twelve-month average.
    true_average_wage_flag = (

        "12m"
        in p09_normalise_text(
            wage_column
        )

        or "average"
        in p09_normalise_text(
            wage_column
        )
    )


    # Record wage-source governance status.
    wage_status = (

        "OK"

        if true_average_wage_flag

        else "REVIEW_CURRENT_WAGE_USED_AS_12M_PROXY"
    )


    # -------------------------------------------------------------------------
    # 02.5 - IDENTIFY AVERAGE PROGRESSIVE BALANCE
    # -------------------------------------------------------------------------


    # Search for the official-style Average Progressive Balance field.
    apb_column = p09_first_existing_column(

        result,

        [

            "average_progressive_balance",

            "average_progressive_balance_12m",

            "edli_average_progressive_balance",

            "pf_average_progressive_balance_12m",
        ],

        required=False,
    )


    # Use APB when available.
    if apb_column is not None:


        # Convert APB into numeric form.
        result[
            "average_progressive_balance"
        ] = pd.to_numeric(

            result[
                apb_column
            ],

            errors="coerce"
        )


        # Store APB source.
        result[
            "average_progressive_balance_source"
        ] = apb_column


    # Otherwise preserve the data limitation explicitly.
    else:


        # Create a missing APB field.
        result[
            "average_progressive_balance"
        ] = np.nan


        # Document missing source.
        result[
            "average_progressive_balance_source"
        ] = "NOT_AVAILABLE"


    # -------------------------------------------------------------------------
    # 02.6 - IDENTIFY CONTINUITY INFORMATION
    # -------------------------------------------------------------------------


    # Search for an explicit twelve-month EDLI continuity field.
    continuity_column = p09_first_existing_column(

        result,

        [

            "edli_continuous_service_12m_flag",

            "continuous_service_12m_flag",

            "edli_continuity_flag",
        ],

        required=False,
    )


    # Use actual continuity data when available.
    if continuity_column is not None:


        # Convert continuity values into Boolean form.
        result[
            "edli_continuity_qualifies"
        ] = result[

            continuity_column

        ].apply(
            p09_to_bool
        )


        # Mark the field as known.
        result[
            "edli_continuity_known_flag"
        ] = True


        # Store source.
        result[
            "edli_continuity_source"
        ] = continuity_column


    # Otherwise do not infer continuity from simple service duration.
    else:


        # Store missing continuity as pandas nullable Boolean.
        result[
            "edli_continuity_qualifies"
        ] = pd.Series(

            pd.NA,

            index=result.index,

            dtype="boolean"
        )


        # Mark continuity as unknown.
        result[
            "edli_continuity_known_flag"
        ] = False


        # Store source description.
        result[
            "edli_continuity_source"
        ] = "NOT_AVAILABLE"


    # -------------------------------------------------------------------------
    # 02.7 - STORE GOVERNED EDLI PARAMETERS
    # -------------------------------------------------------------------------


    # Store wage factor beside employee calculations.
    result[
        "edli_wage_factor"
    ] = wage_factor


    # Store wage ceiling.
    result[
        "edli_wage_ceiling_monthly"
    ] = wage_ceiling


    # Store PF component rate.
    result[
        "edli_pf_component_rate"
    ] = pf_component_rate


    # Store PF component cap.
    result[
        "edli_pf_component_cap"
    ] = pf_component_cap


    # Store illustrative qualifying minimum.
    result[
        "edli_illustrative_minimum_benefit"
    ] = illustrative_minimum


    # Store illustrative maximum.
    result[
        "edli_illustrative_maximum_benefit"
    ] = illustrative_maximum


    # Store Part A current minimum floor.
    result[
        "edli_part_a_minimum_floor"
    ] = part_a_floor


    # Store continuity-gap parameter.
    result[
        "edli_continuity_gap_days"
    ] = continuity_gap_days


    # Store official-calculator requirement.
    result[
        "official_calculator_required_flag"
    ] = bool(
        official_calculator_required
    )


    # -------------------------------------------------------------------------
    # 02.8 - CAPPED WAGE
    # -------------------------------------------------------------------------


    # Apply statutory monthly wage ceiling.
    result[
        "edli_capped_monthly_wage"
    ] = np.minimum(

        result[
            "edli_wage_input_monthly"
        ],

        wage_ceiling
    )


    # Prevent negative wages.
    result[
        "edli_capped_monthly_wage"
    ] = result[
        "edli_capped_monthly_wage"
    ].clip(
        lower=0.0
    )


    # -------------------------------------------------------------------------
    # 02.9 - PART B WAGE COMPONENT
    # -------------------------------------------------------------------------


    # Calculate:
    #
    # wage factor
    # x
    # capped monthly wage
    result[
        "edli_part_b_wage_component"
    ] = (

        wage_factor

        * result[
            "edli_capped_monthly_wage"
        ]
    )


    # -------------------------------------------------------------------------
    # 02.10 - PART B PROVIDENT-FUND COMPONENT
    # -------------------------------------------------------------------------


    # Calculate the PF component only when APB exists.
    result[
        "edli_part_b_pf_component"
    ] = np.where(

        result[
            "average_progressive_balance"
        ].notna(),

        np.minimum(

            pf_component_rate

            * result[
                "average_progressive_balance"
            ],

            pf_component_cap
        ),

        np.nan
    )


    # -------------------------------------------------------------------------
    # 02.11 - PART B RAW BENEFIT WHEN APB EXISTS
    # -------------------------------------------------------------------------


    # Calculate raw Part B before minimum/maximum limits.
    result[
        "edli_part_b_raw"
    ] = (

        result[
            "edli_part_b_wage_component"
        ]

        + result[
            "edli_part_b_pf_component"
        ]
    )


    # -------------------------------------------------------------------------
    # 02.12 - BOUNDED PART B WHEN ALL INPUTS EXIST
    # -------------------------------------------------------------------------


    # Start the calculated Part B as missing.
    result[
        "edli_part_b_if_continuity_qualifies"
    ] = np.nan


    # Identify rows containing APB.
    apb_available = result[
        "average_progressive_balance"
    ].notna()


    # Apply qualifying minimum and maximum.
    result.loc[

        apb_available,

        "edli_part_b_if_continuity_qualifies"

    ] = (

        result.loc[

            apb_available,

            "edli_part_b_raw"
        ]

        .clip(

            lower=illustrative_minimum,

            upper=illustrative_maximum
        )
    )


    # -------------------------------------------------------------------------
    # 02.13 - PART B RANGE WHEN APB IS UNAVAILABLE
    # -------------------------------------------------------------------------


    # Lowest possible PF component is zero.
    #
    # Therefore the lower qualifying Part B estimate is the wage component
    # subject to the current qualifying minimum and maximum.
    result[
        "edli_part_b_lower_if_qualifying"
    ] = (

        result[
            "edli_part_b_wage_component"
        ]

        .clip(

            lower=illustrative_minimum,

            upper=illustrative_maximum
        )
    )


    # Highest possible PF component is the controlled PF component cap.
    result[
        "edli_part_b_upper_if_qualifying"
    ] = (

        result[
            "edli_part_b_wage_component"
        ]

        + pf_component_cap
    )


    # Apply the overall qualifying maximum.
    result[
        "edli_part_b_upper_if_qualifying"
    ] = result[

        "edli_part_b_upper_if_qualifying"

    ].clip(

        lower=illustrative_minimum,

        upper=illustrative_maximum
    )


    # -------------------------------------------------------------------------
    # 02.14 - APPLY KNOWN CONTINUITY CONDITION
    # -------------------------------------------------------------------------


    # Where continuity is explicitly known to fail,
    # the stored current-rule Part B becomes zero.
    continuity_known_failure = (

        result[
            "edli_continuity_known_flag"
        ]

        & (
            result[
                "edli_continuity_qualifies"
            ]
            == False
        )
    )


    # Apply zero Part B for those known failures.
    result.loc[

        continuity_known_failure,

        "edli_part_b_if_continuity_qualifies"

    ] = 0.0


    # -------------------------------------------------------------------------
    # 02.15 - DO NOT FABRICATE PART A
    # -------------------------------------------------------------------------


    # The current controlled rule table stores a Part A minimum floor,
    # but not the complete date-specific Part A statutory formula.
    #
    # Therefore Pipeline 09 records the floor but does NOT pretend that
    # the floor itself is the complete Part A benefit.
    result[
        "edli_part_a_modelled_benefit"
    ] = np.nan


    # -------------------------------------------------------------------------
    # 02.16 - DO NOT FABRICATE FINAL EDLI BENEFIT
    # -------------------------------------------------------------------------


    # The official benefit is:
    #
    # max(Part A, Part B)
    #
    # and is date-sensitive.
    #
    # Because the complete Part A formula / official calculator output
    # and APB / continuity are not guaranteed to exist in our synthetic
    # census, the final official benefit remains unavailable here.
    result[
        "edli_official_benefit"
    ] = np.nan


    # -------------------------------------------------------------------------
    # 02.17 - MODEL GOVERNANCE STATUS
    # -------------------------------------------------------------------------


    # Build one transparent status for every EDLI employee.
    def build_employee_edli_status(
        row,
    ):


        # Start with possible wage-source review.
        row_wage_status = wage_status


        # APB status.
        apb_status = (

            "OK"

            if pd.notna(
                row[
                    "average_progressive_balance"
                ]
            )

            else "REVIEW_AVERAGE_PROGRESSIVE_BALANCE_UNAVAILABLE"
        )


        # Continuity status.
        continuity_status = (

            "OK"

            if bool(
                row[
                    "edli_continuity_known_flag"
                ]
            )

            else "REVIEW_CONTINUITY_INFORMATION_UNAVAILABLE"
        )


        # Official calculator status.
        calculator_status = (

            "OFFICIAL_CALCULATOR_REQUIRED"

            if bool(
                official_calculator_required
            )

            else "OK"
        )


        # Combine all governance messages.
        return p09_combine_status(

            row_wage_status,

            apb_status,

            continuity_status,

            calculator_status
        )


    # Apply employee-level governance status.
    result[
        "edli_model_status"
    ] = result.apply(

        build_employee_edli_status,

        axis=1
    )


    # Store Pipeline version.
    result[
        "pipeline_09_version"
    ] = P09_VERSION


    # Return employee-level EDLI basis.
    return result


# =============================================================================
# P09 SECTION 03 - EDLI PLAN SUMMARY
# =============================================================================


# Define a management-level EDLI summary.
def build_edli_plan_summary(
    edli_employee_basis,
):


    # Return empty summary if no covered members exist.
    if edli_employee_basis.empty:

        return pd.DataFrame()


    # Build one row for the current statutory rule set.
    summary = pd.DataFrame([{


        # Plan identifier.
        "plan_id":
            edli_employee_basis[
                "edli_plan_id"
            ].iloc[
                0
            ],


        # Active covered employees.
        "active_edli_members":
            edli_employee_basis[
                "employee_id"
            ].nunique(),


        # Number of members with APB data.
        "apb_available_members":
            int(

                edli_employee_basis[
                    "average_progressive_balance"
                ].notna().sum()
            ),


        # Number with continuity data.
        "continuity_known_members":
            int(

                edli_employee_basis[
                    "edli_continuity_known_flag"
                ].sum()
            ),


        # Total capped wages for exposure monitoring.
        "total_capped_monthly_wages":
            float(

                edli_employee_basis[
                    "edli_capped_monthly_wage"
                ].sum()
            ),


        # Total wage component.
        "total_part_b_wage_component":
            float(

                edli_employee_basis[
                    "edli_part_b_wage_component"
                ].sum()
            ),


        # Aggregate qualifying lower-range Part B exposure.
        "aggregate_part_b_lower_if_qualifying":
            float(

                edli_employee_basis[
                    "edli_part_b_lower_if_qualifying"
                ].sum()
            ),


        # Aggregate qualifying upper-range Part B exposure.
        "aggregate_part_b_upper_if_qualifying":
            float(

                edli_employee_basis[
                    "edli_part_b_upper_if_qualifying"
                ].sum()
            ),


        # Official calculator flag.
        "official_calculator_required":
            bool(

                edli_employee_basis[
                    "official_calculator_required_flag"
                ].iloc[
                    0
                ]
            ),


        # Explicitly state that this is not total official benefit.
        "benefit_output_status":
            (
                "ILLUSTRATIVE_COMPONENTS_ONLY_"
                "OFFICIAL_CALCULATOR_GOVERNS"
            ),


        # Pipeline version.
        "pipeline_09_version":
            P09_VERSION,
    }])


    # Return EDLI plan summary.
    return summary


# =============================================================================
# P09 SECTION 04 - EDLI HISTORICAL CLAIM/RULE-DATE REVIEW
# =============================================================================


# Define historical EDLI claim governance analysis.
def build_edli_claim_review(
    claims_clean,
    active_rules,
):


    # Resolve current EDLI plan.
    edli_plan_id = p09_get_current_edli_plan_id(

        active_rules
    )


    # Build rule lookup.
    lookup = build_plan_parameter_lookup(

        active_rules
    )


    # Retrieve current maximum.
    current_maximum = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "illustrative_maximum_benefit"
    )


    # Retrieve current Part A minimum floor.
    current_part_a_floor = require_lookup_parameter(

        lookup,

        edli_plan_id,

        "part_a_minimum_floor"
    )


    # Determine current rule effective date from active rules.
    edli_rule_rows = active_rules.loc[

        active_rules[
            "product_type"
        ].eq(
            "EDLI"
        )

    ].copy()


    # Parse effective-from date.
    edli_rule_rows[
        "_effective_from"
    ] = pd.to_datetime(

        edli_rule_rows[
            "effective_from"
        ],

        errors="coerce"
    )


    # Use the earliest start date for this current controlled rule set.
    current_rule_effective_from = edli_rule_rows[

        "_effective_from"

    ].min()


    # Filter EDLI claim-history records.
    result = claims_clean.loc[

        claims_clean[
            "product_type"
        ].astype(
            str
        ).str.upper().eq(
            "EDLI"
        )

    ].copy()


    # Return empty table when no EDLI claim history exists.
    if result.empty:

        return result


    # Parse event date.
    result[
        "event_date"
    ] = pd.to_datetime(

        result[
            "event_date"
        ],

        errors="coerce"
    )


    # Convert claim amount.
    result[
        "claim_amount"
    ] = pd.to_numeric(

        result[
            "claim_amount"
        ],

        errors="coerce"
    )


    # Identify Death events.
    result[
        "death_event_flag"
    ] = result[
        "event_type"
    ].apply(

        lambda value:
            "death"
            in p09_normalise_text(
                value
            )
    )


    # Identify accepted monetary claim amounts.
    result[
        "accepted_claim_amount_flag"
    ] = result.apply(

        lambda row:
            p09_claim_amount_accepted(

                row[
                    "claim_status"
                ],

                row[
                    "claim_amount"
                ]
            ),

        axis=1
    )


    # Determine whether the currently stored statutory rule is
    # chronologically applicable to the historical event.
    result[
        "current_rule_date_applicable_flag"
    ] = (

        result[
            "event_date"
        ]

        >= current_rule_effective_from
    )


    # Store current controlled effective date.
    result[
        "current_rule_effective_from"
    ] = current_rule_effective_from


    # Store current benefit ceiling.
    result[
        "current_rule_maximum_benefit"
    ] = current_maximum


    # Store current Part A minimum floor.
    result[
        "current_rule_part_a_minimum_floor"
    ] = current_part_a_floor


    # Create review status.
    def build_claim_review_status(
        row,
    ):


        # Missing event date prevents rule selection.
        if pd.isna(
            row[
                "event_date"
            ]
        ):

            return "REVIEW_EVENT_DATE_MISSING"


        # Historical claims before the stored rule require
        # their own historical rule set.
        if not bool(

            row[
                "current_rule_date_applicable_flag"
            ]
        ):

            return "REVIEW_HISTORICAL_EDLI_RULE_REQUIRED"


        # Non-death events are outside EDLI claim payment.
        if not bool(
            row[
                "death_event_flag"
            ]
        ):

            return "NON_DEATH_EVENT"


        # Accepted claim above the current controlled maximum needs review.
        if (

            bool(
                row[
                    "accepted_claim_amount_flag"
                ]
            )

            and pd.notna(
                row[
                    "claim_amount"
                ]
            )

            and row[
                "claim_amount"
            ]
            > current_maximum
        ):

            return "REVIEW_CLAIM_ABOVE_CURRENT_RULE_MAXIMUM"


        # Otherwise retain the claim as a current-rule reviewable record.
        return "CURRENT_RULE_DATE_RANGE_OK"


    # Apply review status.
    result[
        "edli_claim_review_status"
    ] = result.apply(

        build_claim_review_status,

        axis=1
    )


    # Store Pipeline version.
    result[
        "pipeline_09_version"
    ] = P09_VERSION


    # Return historical EDLI review.
    return result


# =============================================================================
# P09 SECTION 05 - BUILD CURRENT GTI EMPLOYEE RISK BASIS
# =============================================================================


# Define current one-year GTI Sum Assured and expected-risk basis.
def build_gti_employee_risk_basis(
    employee_features,
    active_rules,
    decrement_results,
):


    # Build plan lookup.
    lookup = build_plan_parameter_lookup(

        active_rules
    )


    # -------------------------------------------------------------------------
    # 05.1 - SELECT ACTIVE GTI MEMBERS
    # -------------------------------------------------------------------------


    # Locate active GTI membership flag.
    gti_member_column = p09_first_existing_column(

        employee_features,

        [
            "active_gti_member_flag",
        ],

        required=True,
    )


    # Create Boolean membership mask.
    gti_member_mask = employee_features[

        gti_member_column

    ].apply(
        p09_to_bool
    )


    # Keep active GTI members.
    result = employee_features.loc[

        gti_member_mask

    ].copy()


    # Confirm GTI plan identifier.
    gti_plan_column = p09_first_existing_column(

        result,

        [
            "gti_plan_id",
        ],

        required=True,
    )


    # Standardise plan identifier.
    result[
        "plan_id"
    ] = result[

        gti_plan_column

    ].astype(
        str
    )


    # -------------------------------------------------------------------------
    # 05.2 - ATTACH PIPELINE 06 GTI MORTALITY
    # -------------------------------------------------------------------------


    # Retrieve Pipeline 06 product mortality table.
    product_mortality = decrement_results.get(

        "product_mortality",

        pd.DataFrame()
    )


    # Start mortality fields as missing.
    result[
        "q_death_1y"
    ] = np.nan


    result[
        "gti_mortality_source"
    ] = "DIRECT_PLAN_RULE_CALCULATION"


    # Use Pipeline 06 GTI mortality where available.
    if (

        isinstance(
            product_mortality,
            pd.DataFrame
        )

        and not product_mortality.empty
    ):


        # Keep GTI mortality rows only.
        gti_mortality = product_mortality.loc[

            product_mortality[
                "product_type"
            ].eq(
                "GTI"
            ),

            [

                "employee_id",

                "plan_id",

                "q_death_standalone_1y",
            ]

        ].copy()


        # Rename probability field.
        gti_mortality = gti_mortality.rename(

            columns={

                "q_death_standalone_1y":
                    "_pipeline06_q_death"
            }
        )


        # Merge Pipeline 06 mortality.
        result = result.merge(

            gti_mortality,

            on=[

                "employee_id",

                "plan_id",
            ],

            how="left"
        )


        # Use Pipeline 06 probability where present.
        pipeline06_available = result[

            "_pipeline06_q_death"

        ].notna()


        # Copy probability.
        result.loc[

            pipeline06_available,

            "q_death_1y"

        ] = result.loc[

            pipeline06_available,

            "_pipeline06_q_death"
        ]


        # Store source.
        result.loc[

            pipeline06_available,

            "gti_mortality_source"

        ] = "PIPELINE_06_GTI_MORTALITY"


    # -------------------------------------------------------------------------
    # 05.3 - INITIALISE COVER AND PRICING FIELDS
    # -------------------------------------------------------------------------


    # Create output columns.
    result[
        "cover_basis"
    ] = pd.NA


    result[
        "salary_basis_column"
    ] = pd.NA


    result[
        "salary_basis_amount"
    ] = np.nan


    result[
        "sum_assured"
    ] = np.nan


    result[
        "free_cover_limit"
    ] = np.nan


    result[
        "gross_premium_loading_rate"
    ] = np.nan


    result[
        "mortality_A"
    ] = np.nan


    result[
        "mortality_B"
    ] = np.nan


    result[
        "mortality_c"
    ] = np.nan


    result[
        "gti_cover_status"
    ] = "OK"


    # -------------------------------------------------------------------------
    # 05.4 - CALCULATE EACH GTI PLAN
    # -------------------------------------------------------------------------


    # Process one employer-designed GTI plan at a time.
    for plan_id in result[

        "plan_id"

    ].dropna().unique():


        # Identify employees in this plan.
        mask = result[
            "plan_id"
        ].eq(
            plan_id
        )


        # Retrieve cover design.
        cover_basis = require_lookup_parameter(

            lookup,

            plan_id,

            "cover_basis"
        )


        # Retrieve commercial loading rate.
        loading_rate = require_lookup_parameter(

            lookup,

            plan_id,

            "gross_premium_loading_rate"
        )


        # Retrieve free-cover limit.
        free_cover_limit = require_lookup_parameter(

            lookup,

            plan_id,

            "free_cover_limit"
        )


        # Retrieve mortality parameters.
        mortality_A = require_lookup_parameter(

            lookup,

            plan_id,

            "mortality_A"
        )


        mortality_B = require_lookup_parameter(

            lookup,

            plan_id,

            "mortality_B"
        )


        mortality_c = require_lookup_parameter(

            lookup,

            plan_id,

            "mortality_c"
        )


        # Store plan parameters.
        result.loc[

            mask,

            "cover_basis"

        ] = cover_basis


        result.loc[

            mask,

            "free_cover_limit"

        ] = free_cover_limit


        result.loc[

            mask,

            "gross_premium_loading_rate"

        ] = loading_rate


        result.loc[

            mask,

            "mortality_A"

        ] = mortality_A


        result.loc[

            mask,

            "mortality_B"

        ] = mortality_B


        result.loc[

            mask,

            "mortality_c"

        ] = mortality_c


        # Normalise cover basis.
        basis = p09_normalise_text(

            cover_basis
        )


        # ---------------------------------------------------------------------
        # FLAT COVER
        # ---------------------------------------------------------------------


        if basis == "flat":


            # Retrieve flat Sum Assured.
            flat_sum_assured = require_lookup_parameter(

                lookup,

                plan_id,

                "flat_sum_assured"
            )


            # Apply the same amount to every employee in the plan.
            result.loc[

                mask,

                "sum_assured"

            ] = flat_sum_assured


            # No salary basis is needed.
            result.loc[

                mask,

                "salary_basis_column"

            ] = "NOT_APPLICABLE"


        # ---------------------------------------------------------------------
        # SALARY-MULTIPLE COVER
        # ---------------------------------------------------------------------


        elif basis == "salarymultiple":


            # Retrieve salary basis column.
            salary_basis = require_lookup_parameter(

                lookup,

                plan_id,

                "salary_basis"
            )


            # Confirm that the employee dataset contains that field.
            if salary_basis not in result.columns:

                raise KeyError(

                    "GTI salary basis missing from employee features: "
                    f"{plan_id} / {salary_basis}"
                )


            # Retrieve salary multiple.
            salary_multiple = require_lookup_parameter(

                lookup,

                plan_id,

                "salary_multiple"
            )


            # Retrieve minimum cover.
            minimum_cover = require_lookup_parameter(

                lookup,

                plan_id,

                "minimum_cover"
            )


            # Retrieve maximum cover.
            maximum_cover = require_lookup_parameter(

                lookup,

                plan_id,

                "maximum_cover"
            )


            # Convert salary to numeric.
            salary_amount = pd.to_numeric(

                result.loc[

                    mask,

                    salary_basis
                ],

                errors="coerce"
            )


            # Store salary basis.
            result.loc[

                mask,

                "salary_basis_column"

            ] = salary_basis


            # Store salary amount.
            result.loc[

                mask,

                "salary_basis_amount"

            ] = salary_amount


            # Calculate raw salary-multiple cover.
            raw_cover = (

                salary_amount

                * salary_multiple
            )


            # Apply minimum and maximum cover.
            result.loc[

                mask,

                "sum_assured"

            ] = raw_cover.clip(

                lower=minimum_cover,

                upper=maximum_cover
            )


            # Flag missing salary values.
            missing_salary_mask = (

                mask

                & result[
                    "salary_basis_amount"
                ].isna()
            )


            # Store review status.
            result.loc[

                missing_salary_mask,

                "gti_cover_status"

            ] = "REVIEW_GTI_SALARY_BASIS_MISSING"


        # ---------------------------------------------------------------------
        # GRADE-BASED COVER
        # ---------------------------------------------------------------------


        elif basis == "gradebased":


            # Confirm grade field.
            grade_column = p09_first_existing_column(

                result,

                [
                    "grade",
                ],

                required=True,
            )


            # Process employees in this plan individually
            # because each grade has a separate controlled rule.
            for row_index in result.loc[

                mask

            ].index:


                # Read employee grade.
                grade_value = result.at[

                    row_index,

                    grade_column
                ]


                # Normalise grade text but preserve E1/E2 etc.
                grade_text = str(

                    grade_value

                ).strip().upper()


                # Build the rule parameter name.
                grade_parameter = (

                    f"{grade_text}_cover"
                )


                # Retrieve grade-specific cover.
                grade_cover = p09_optional_parameter(

                    lookup,

                    plan_id,

                    grade_parameter,

                    default=np.nan
                )


                # Store grade cover when available.
                if pd.notna(
                    grade_cover
                ):


                    result.at[

                        row_index,

                        "sum_assured"

                    ] = grade_cover


                # Otherwise flag missing grade mapping.
                else:


                    result.at[

                        row_index,

                        "gti_cover_status"

                    ] = (

                        "REVIEW_GRADE_COVER_MAPPING_UNAVAILABLE"
                    )


            # No salary basis is required.
            result.loc[

                mask,

                "salary_basis_column"

            ] = "NOT_APPLICABLE"


        # ---------------------------------------------------------------------
        # UNSUPPORTED COVER DESIGN
        # ---------------------------------------------------------------------


        else:


            # Stop instead of silently inventing another design.
            raise ValueError(

                "Unsupported GTI cover basis: "
                f"{plan_id} / {cover_basis}"
            )


        # ---------------------------------------------------------------------
        # 05.5 - DIRECT MORTALITY FALLBACK
        # ---------------------------------------------------------------------


        # Identify employees still missing Pipeline 06 mortality.
        missing_mortality = (

            mask

            & result[
                "q_death_1y"
            ].isna()
        )


        # Recalculate mortality directly from governed GTI parameters.
        if missing_mortality.any():


            # Extract current ages.
            ages = result.loc[

                missing_mortality,

                "attained_age_years"

            ].to_numpy(
                dtype=float
            )


            # Calculate exact one-year probability.
            result.loc[

                missing_mortality,

                "q_death_1y"

            ] = gompertz_makeham_death_probability(

                ages,

                1.0,

                mortality_A,

                mortality_B,

                mortality_c
            )


            # Record transparent fallback source.
            result.loc[

                missing_mortality,

                "gti_mortality_source"

            ] = "DIRECT_GTI_PLAN_RULE_MORTALITY"


    # -------------------------------------------------------------------------
    # 05.6 - CURRENT ONE-YEAR EXPOSURE
    # -------------------------------------------------------------------------


    # For the current one-year quotation each active covered member
    # contributes one year of prospective exposure.
    result[
        "current_quote_exposure_years"
    ] = 1.0


    # -------------------------------------------------------------------------
    # 05.7 - EXPECTED DEATH COUNT
    # -------------------------------------------------------------------------


    # Calculate:
    #
    # Exposure x q
    result[
        "fresh_expected_death_count"
    ] = (

        result[
            "current_quote_exposure_years"
        ]

        * result[
            "q_death_1y"
        ]
    )


    # -------------------------------------------------------------------------
    # 05.8 - FRESH EXPECTED CLAIM COST
    # -------------------------------------------------------------------------


    # Calculate:
    #
    # Exposure x q x Sum Assured
    result[
        "fresh_expected_claim_cost"
    ] = (

        result[
            "current_quote_exposure_years"
        ]

        * result[
            "q_death_1y"
        ]

        * result[
            "sum_assured"
        ]
    )


    # -------------------------------------------------------------------------
    # 05.9 - FREE-COVER-LIMIT UNDERWRITING
    # -------------------------------------------------------------------------


    # Identify employees whose cover exceeds free-cover limit.
    result[
        "underwriting_referral_flag"
    ] = (

        result[
            "sum_assured"
        ]

        > result[
            "free_cover_limit"
        ]
    )


    # Calculate amount above free-cover limit.
    result[
        "cover_above_free_cover_limit"
    ] = np.maximum(

        result[
            "sum_assured"
        ]

        - result[
            "free_cover_limit"
        ],

        0.0
    )


    # -------------------------------------------------------------------------
    # 05.10 - EXPECTED CLAIM RATE PER INR 1,000 COVER
    # -------------------------------------------------------------------------


    # Calculate pure expected mortality cost per INR 1,000 Sum Assured.
    result[
        "fresh_expected_claim_rate_per_1000"
    ] = np.where(

        result[
            "sum_assured"
        ] > 0,

        result[
            "fresh_expected_claim_cost"
        ]

        / result[
            "sum_assured"
        ]

        * 1000.0,

        np.nan
    )


    # Store Pipeline version.
    result[
        "pipeline_09_version"
    ] = P09_VERSION


    # Return current GTI risk basis.
    return result


# =============================================================================
# P09 SECTION 06 - HISTORICAL GTI ACTUAL-TO-EXPECTED EXPERIENCE
# =============================================================================


# Define historical GTI exposure and A/E engine.
def build_gti_historical_experience(
    claims_clean,
    employee_features,
    active_rules,
):


    # Build typed plan lookup.
    lookup = build_plan_parameter_lookup(

        active_rules
    )


    # -------------------------------------------------------------------------
    # 06.1 - FILTER GTI HISTORY
    # -------------------------------------------------------------------------


    # Keep GTI historical exposure/event records.
    history = claims_clean.loc[

        claims_clean[
            "product_type"
        ].astype(
            str
        ).str.upper().eq(
            "GTI"
        )

    ].copy()


    # Return empty structures when no GTI history exists.
    if history.empty:

        return (
            history,
            pd.DataFrame()
        )


    # -------------------------------------------------------------------------
    # 06.2 - PARSE DATES
    # -------------------------------------------------------------------------


    # Convert exposure start date.
    history[
        "exposure_start_date"
    ] = pd.to_datetime(

        history[
            "exposure_start_date"
        ],

        errors="coerce"
    )


    # Convert exposure end date.
    history[
        "exposure_end_date"
    ] = pd.to_datetime(

        history[
            "exposure_end_date"
        ],

        errors="coerce"
    )


    # Convert event date.
    history[
        "event_date"
    ] = pd.to_datetime(

        history[
            "event_date"
        ],

        errors="coerce"
    )


    # If exposure end is missing but an event date exists,
    # use event date as the observed exposure end.
    history[
        "_effective_exposure_end"
    ] = history[

        "exposure_end_date"

    ].fillna(

        history[
            "event_date"
        ]
    )


    # -------------------------------------------------------------------------
    # 06.3 - EMPLOYEE-YEAR EXPOSURE
    # -------------------------------------------------------------------------


    # Calculate exposure duration in years.
    history[
        "exposure_years"
    ] = (

        (

            history[
                "_effective_exposure_end"
            ]

            - history[
                "exposure_start_date"
            ]

        ).dt.days

        / 365.25
    )


    # Negative exposure is invalid.
    history.loc[

        history[
            "exposure_years"
        ] < 0,

        "exposure_years"

    ] = np.nan


    # -------------------------------------------------------------------------
    # 06.4 - EXPOSURE MIDPOINT
    # -------------------------------------------------------------------------


    # Calculate exposure midpoint.
    history[
        "exposure_midpoint"
    ] = (

        history[
            "exposure_start_date"
        ]

        + (

            history[
                "_effective_exposure_end"
            ]

            - history[
                "exposure_start_date"
            ]

        ) / 2
    )


    # -------------------------------------------------------------------------
    # 06.5 - ATTACH CURRENT EMPLOYEE AGE
    # -------------------------------------------------------------------------


    # Create employee-age map at valuation date.
    age_lookup = (

        employee_features

        .set_index(
            "employee_id"
        )[
            "attained_age_years"
        ]
    )


    # Attach valuation-date age.
    history[
        "attained_age_at_valuation"
    ] = history[
        "employee_id"
    ].map(
        age_lookup
    )


    # Calculate calendar years between historical midpoint and valuation.
    history[
        "years_midpoint_to_valuation"
    ] = (

        (

            VALUATION_DATE

            - history[
                "exposure_midpoint"
            ]

        ).dt.days

        / 365.25
    )


    # Approximate historical midpoint age from current attained age.
    history[
        "age_at_exposure_midpoint"
    ] = (

        history[
            "attained_age_at_valuation"
        ]

        - history[
            "years_midpoint_to_valuation"
        ]
    )


    # -------------------------------------------------------------------------
    # 06.6 - INITIALISE EXPECTED EXPERIENCE
    # -------------------------------------------------------------------------


    # Expected death count.
    history[
        "expected_death_count"
    ] = np.nan


    # Expected claim cost.
    history[
        "expected_claim_cost"
    ] = np.nan


    # Mortality source.
    history[
        "mortality_source"
    ] = "GTI_PLAN_RULE"


    # Convert Sum Assured at event.
    history[
        "sum_assured_at_event"
    ] = pd.to_numeric(

        history[
            "sum_assured_at_event"
        ],

        errors="coerce"
    )


    # -------------------------------------------------------------------------
    # 06.7 - APPLY PLAN-SPECIFIC HISTORICAL MORTALITY
    # -------------------------------------------------------------------------


    # Process each historical GTI plan.
    for plan_id in history[

        "product_plan_id"

    ].dropna().astype(
        str
    ).unique():


        # Identify this plan.
        mask = history[

            "product_plan_id"

        ].astype(
            str
        ).eq(
            plan_id
        )


        # Retrieve mortality assumptions.
        mortality_A = p09_optional_parameter(

            lookup,

            plan_id,

            "mortality_A",

            default=np.nan
        )


        mortality_B = p09_optional_parameter(

            lookup,

            plan_id,

            "mortality_B",

            default=np.nan
        )


        mortality_c = p09_optional_parameter(

            lookup,

            plan_id,

            "mortality_c",

            default=np.nan
        )


        # If a historical plan has no current controlled basis,
        # leave expected claims unavailable.
        if any(

            pd.isna(
                parameter
            )

            for parameter in [

                mortality_A,

                mortality_B,

                mortality_c,
            ]
        ):


            # Mark plan-basis review.
            history.loc[

                mask,

                "mortality_source"

            ] = "REVIEW_HISTORICAL_GTI_PLAN_RULE_UNAVAILABLE"


            # Move to next plan.
            continue


        # Identify valid model rows.
        valid_rows = (

            mask

            & history[
                "age_at_exposure_midpoint"
            ].notna()

            & history[
                "exposure_years"
            ].notna()

            & (
                history[
                    "exposure_years"
                ]
                >= 0
            )
        )


        # Skip when no usable exposure exists.
        if not valid_rows.any():

            continue


        # Calculate exact finite-period death probability
        # over each historical exposure length.
        q_history = gompertz_makeham_death_probability(

            history.loc[

                valid_rows,

                "age_at_exposure_midpoint"

            ].to_numpy(
                dtype=float
            ),

            history.loc[

                valid_rows,

                "exposure_years"

            ].to_numpy(
                dtype=float
            ),

            mortality_A,

            mortality_B,

            mortality_c
        )


        # Store expected death counts.
        history.loc[

            valid_rows,

            "expected_death_count"

        ] = q_history


        # Store expected claim cost.
        history.loc[

            valid_rows,

            "expected_claim_cost"

        ] = (

            q_history

            * history.loc[

                valid_rows,

                "sum_assured_at_event"

            ].to_numpy(
                dtype=float
            )
        )


    # -------------------------------------------------------------------------
    # 06.8 - ACTUAL DEATH EVENTS
    # -------------------------------------------------------------------------


    # Count Death events regardless of claim adjudication.
    #
    # This is appropriate for mortality A/E.
    history[
        "actual_death_event"
    ] = history[
        "event_type"
    ].apply(

        lambda value:
            1

            if "death"
            in p09_normalise_text(
                value
            )

            else 0
    )


    # Convert claim amount to numeric.
    history[
        "claim_amount"
    ] = pd.to_numeric(

        history[
            "claim_amount"
        ],

        errors="coerce"
    )


    # Determine whether monetary claim amount is accepted.
    history[
        "accepted_claim_amount_flag"
    ] = history.apply(

        lambda row:
            p09_claim_amount_accepted(

                row[
                    "claim_status"
                ],

                row[
                    "claim_amount"
                ]
            ),

        axis=1
    )


    # Keep accepted Death claim amount only.
    history[
        "actual_death_claim_amount"
    ] = np.where(

        history[
            "actual_death_event"
        ].eq(
            1
        )

        & history[
            "accepted_claim_amount_flag"
        ],

        history[
            "claim_amount"
        ],

        0.0
    )


    # -------------------------------------------------------------------------
    # 06.9 - PLAN-LEVEL ACTUAL-TO-EXPECTED
    # -------------------------------------------------------------------------


    # Aggregate experience by GTI plan.
    summary = (

        history

        .groupby(

            "product_plan_id",

            as_index=False
        )

        .agg(


            # Historical employee-year exposure.
            employee_year_exposure=(

                "exposure_years",

                "sum"
            ),


            # Actual Death events.
            actual_death_events=(

                "actual_death_event",

                "sum"
            ),


            # Model expected Death events.
            expected_death_events=(

                "expected_death_count",

                "sum"
            ),


            # Actual accepted claim amount.
            actual_death_claim_amount=(

                "actual_death_claim_amount",

                "sum"
            ),


            # Model expected claim amount.
            expected_claim_cost=(

                "expected_claim_cost",

                "sum"
            ),
        )
    )


    # Rename plan field.
    summary = summary.rename(

        columns={

            "product_plan_id":
                "plan_id"
        }
    )


    # Calculate count-based A/E.
    summary[
        "actual_to_expected_count"
    ] = np.where(

        summary[
            "expected_death_events"
        ] > 0,

        summary[
            "actual_death_events"
        ]

        / summary[
            "expected_death_events"
        ],

        np.nan
    )


    # Calculate monetary A/E.
    summary[
        "actual_to_expected_amount"
    ] = np.where(

        summary[
            "expected_claim_cost"
        ] > 0,

        summary[
            "actual_death_claim_amount"
        ]

        / summary[
            "expected_claim_cost"
        ],

        np.nan
    )


    # Store Pipeline version.
    history[
        "pipeline_09_version"
    ] = P09_VERSION


    summary[
        "pipeline_09_version"
    ] = P09_VERSION


    # Return detailed and summarised experience.
    return (
        history,
        summary
    )


# =============================================================================
# P09 SECTION 07 - GTI CREDIBILITY AND EXPERIENCE FACTOR
# =============================================================================


# Define limited-fluctuation credibility by GTI plan.
def build_gti_credibility_summary(
    current_gti_basis,
    historical_summary,
    active_rules,
):


    # Build rule lookup.
    lookup = build_plan_parameter_lookup(

        active_rules
    )


    # Find all current active GTI plans.
    plan_ids = sorted(

        current_gti_basis[
            "plan_id"
        ].dropna().unique()
    )


    # Create output rows.
    rows = []


    # Process every GTI plan.
    for plan_id in plan_ids:


        # Retrieve confidence z.
        confidence_z = require_lookup_parameter(

            lookup,

            plan_id,

            "credibility_confidence_z"
        )


        # Retrieve relative tolerance k.
        tolerance_k = require_lookup_parameter(

            lookup,

            plan_id,

            "credibility_tolerance_k"
        )


        # Calculate:
        #
        # N_full ~= (z/k)^2
        full_credibility_claims = (

            confidence_z

            / tolerance_k

        ) ** 2


        # Look for historical experience for this plan.
        history_row = historical_summary.loc[

            historical_summary[
                "plan_id"
            ].astype(
                str
            ).eq(
                str(
                    plan_id
                )
            )

        ]


        # Default to no historical experience.
        if history_row.empty:


            # No expected historical claims.
            historical_expected_deaths = 0.0


            # No observed deaths.
            historical_actual_deaths = 0.0


            # Standard benchmark A/E.
            actual_to_expected = 1.0


        else:


            # Use historical expected claims count as credibility volume.
            historical_expected_deaths = float(

                history_row[
                    "expected_death_events"
                ].iloc[
                    0
                ]
            )


            # Store actual deaths.
            historical_actual_deaths = float(

                history_row[
                    "actual_death_events"
                ].iloc[
                    0
                ]
            )


            # Retrieve A/E.
            historical_ae = history_row[

                "actual_to_expected_count"

            ].iloc[
                0
            ]


            # If A/E cannot be calculated, use neutral benchmark one.
            actual_to_expected = (

                float(
                    historical_ae
                )

                if pd.notna(
                    historical_ae
                )

                else 1.0
            )


        # Calculate partial credibility:
        #
        # Z = min(1, sqrt(N/N_full))
        credibility_Z = min(

            1.0,

            np.sqrt(

                historical_expected_deaths

                / full_credibility_claims
            )

            if (
                full_credibility_claims > 0

                and historical_expected_deaths >= 0
            )

            else 0.0
        )


        # Calculate experience factor:
        #
        # Factor = Z(A/E) + (1-Z)(1)
        experience_factor = (

            credibility_Z

            * actual_to_expected

            + (

                1.0

                - credibility_Z
            )
        )


        # Store result.
        rows.append({


            # Plan.
            "plan_id":
                plan_id,


            # Confidence parameter.
            "credibility_confidence_z":
                confidence_z,


            # Tolerance.
            "credibility_tolerance_k":
                tolerance_k,


            # Full credibility threshold.
            "full_credibility_expected_claims":
                full_credibility_claims,


            # Historical expected Death count.
            "historical_expected_death_events":
                historical_expected_deaths,


            # Historical actual Death count.
            "historical_actual_death_events":
                historical_actual_deaths,


            # A/E.
            "actual_to_expected_count":
                actual_to_expected,


            # Partial credibility.
            "credibility_Z":
                credibility_Z,


            # Experience factor.
            "experience_factor":
                experience_factor,


            # Version.
            "pipeline_09_version":
                P09_VERSION,
        })


    # Return plan credibility table.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# P09 SECTION 08 - APPLY CREDIBILITY AND CALCULATE GROSS GTI PREMIUM
# =============================================================================


# Define final current GTI pricing engine.
def build_gti_pricing(
    current_gti_basis,
    credibility_summary,
):


    # Merge plan-level credibility into employees.
    result = current_gti_basis.merge(

        credibility_summary[[

            "plan_id",

            "credibility_Z",

            "actual_to_expected_count",

            "experience_factor",

        ]],

        on="plan_id",

        how="left"
    )


    # Missing experience means no experience adjustment.
    result[
        "credibility_Z"
    ] = result[
        "credibility_Z"
    ].fillna(
        0.0
    )


    # Missing A/E defaults to benchmark one.
    result[
        "actual_to_expected_count"
    ] = result[
        "actual_to_expected_count"
    ].fillna(
        1.0
    )


    # Missing experience factor defaults to one.
    result[
        "experience_factor"
    ] = result[
        "experience_factor"
    ].fillna(
        1.0
    )


    # -------------------------------------------------------------------------
    # 08.1 - EXPERIENCE-ADJUSTED EXPECTED CLAIM COST
    # -------------------------------------------------------------------------


    # Apply the experience factor to NEXT year's fresh expected claim cost.
    result[
        "adjusted_expected_claim_cost"
    ] = (

        result[
            "fresh_expected_claim_cost"
        ]

        * result[
            "experience_factor"
        ]
    )


    # -------------------------------------------------------------------------
    # 08.2 - GROSS PREMIUM
    # -------------------------------------------------------------------------


    # Calculate denominator:
    #
    # 1 - loading
    result[
        "gross_premium_denominator"
    ] = (

        1.0

        - result[
            "gross_premium_loading_rate"
        ]
    )


    # Calculate gross premium only when denominator is positive.
    result[
        "gross_model_premium"
    ] = np.where(

        result[
            "gross_premium_denominator"
        ] > 0,

        result[
            "adjusted_expected_claim_cost"
        ]

        / result[
            "gross_premium_denominator"
        ],

        np.nan
    )


    # -------------------------------------------------------------------------
    # 08.3 - GROSS PREMIUM RATE PER INR 1,000
    # -------------------------------------------------------------------------


    # Calculate premium rate per INR 1,000 cover.
    result[
        "gross_premium_rate_per_1000"
    ] = np.where(

        result[
            "sum_assured"
        ] > 0,

        result[
            "gross_model_premium"
        ]

        / result[
            "sum_assured"
        ]

        * 1000.0,

        np.nan
    )


    # Store Pipeline version.
    result[
        "pipeline_09_version"
    ] = P09_VERSION


    # Return employee-level final pricing.
    return result


# =============================================================================
# P09 SECTION 09 - GTI PLAN PRICING SUMMARY
# =============================================================================


# Define final GTI plan-level management summary.
def build_gti_plan_summary(
    gti_pricing,
):


    # Return empty structure when no GTI members exist.
    if gti_pricing.empty:

        return pd.DataFrame()


    # Aggregate to plan level.
    summary = (

        gti_pricing

        .groupby(

            "plan_id",

            as_index=False
        )

        .agg(


            # Active employees.
            active_members=(

                "employee_id",

                "nunique"
            ),


            # Total Sum Assured.
            total_sum_assured=(

                "sum_assured",

                "sum"
            ),


            # Expected Death count.
            fresh_expected_death_count=(

                "fresh_expected_death_count",

                "sum"
            ),


            # Fresh model expected claim cost.
            fresh_expected_claim_cost=(

                "fresh_expected_claim_cost",

                "sum"
            ),


            # Experience-adjusted expected claims.
            adjusted_expected_claim_cost=(

                "adjusted_expected_claim_cost",

                "sum"
            ),


            # Gross model premium.
            gross_model_premium=(

                "gross_model_premium",

                "sum"
            ),


            # Underwriting referrals.
            underwriting_referral_count=(

                "underwriting_referral_flag",

                "sum"
            ),


            # Cover above FCL.
            total_cover_above_free_cover_limit=(

                "cover_above_free_cover_limit",

                "sum"
            ),
        )
    )


    # Attach average Sum Assured.
    summary[
        "average_sum_assured"
    ] = (

        summary[
            "total_sum_assured"
        ]

        / summary[
            "active_members"
        ]
    )


    # Calculate aggregate gross rate per INR 1,000.
    summary[
        "gross_premium_rate_per_1000"
    ] = np.where(

        summary[
            "total_sum_assured"
        ] > 0,

        summary[
            "gross_model_premium"
        ]

        / summary[
            "total_sum_assured"
        ]

        * 1000.0,

        np.nan
    )


    # Store Pipeline version.
    summary[
        "pipeline_09_version"
    ] = P09_VERSION


    # Return GTI plan summary.
    return summary


# =============================================================================
# P09 SECTION 10 - GTI UNDERWRITING REVIEW TABLE
# =============================================================================


# Define a focused underwriting-referral output.
def build_gti_underwriting_review(
    gti_pricing,
):


    # Keep employees above their plan free-cover limit.
    review = gti_pricing.loc[

        gti_pricing[
            "underwriting_referral_flag"
        ]

    ].copy()


    # Sort highest excess cover first.
    review = review.sort_values(

        "cover_above_free_cover_limit",

        ascending=False
    )


    # Return useful underwriting fields only.
    return review[[

        "employee_id",

        "plan_id",

        "cover_basis",

        "sum_assured",

        "free_cover_limit",

        "cover_above_free_cover_limit",

        "q_death_1y",

        "fresh_expected_claim_cost",

        "gross_model_premium",

        "gti_cover_status",

        "pipeline_09_version",

    ]].copy()


# =============================================================================
# P09 SECTION 11 - PIPELINE 09 VALIDATION
# =============================================================================


# Define mathematical validation checks.
def build_pipeline_09_validation(
    edli_employee_basis,
    gti_pricing,
    gti_plan_summary,
    historical_gti_detail,
):


    # Create result list.
    validation_rows = []


    # Define helper for recording one check.
    def add_validation(
        check,
        exceptions,
        note="",
    ):


        # Convert exception count to integer.
        exception_count = int(
            exceptions
        )


        # Zero exceptions means PASS.
        status = (

            "PASS"

            if exception_count == 0

            else "FAIL"
        )


        # Store check.
        validation_rows.append({

            "check":
                check,

            "exceptions":
                exception_count,

            "status":
                status,

            "note":
                note,
        })


    # -------------------------------------------------------------------------
    # EDLI VALIDATIONS
    # -------------------------------------------------------------------------


    # Employee IDs must be unique.
    add_validation(

        "EDLI employee basis unique",

        edli_employee_basis[
            "employee_id"
        ].duplicated().sum(),
    )


    # Capped wages cannot be negative.
    add_validation(

        "EDLI capped wages non-negative",

        (

            edli_employee_basis[
                "edli_capped_monthly_wage"
            ]

            < 0

        ).sum(),
    )


    # Lower Part B range cannot exceed upper range.
    add_validation(

        "EDLI Part B lower range <= upper range",

        (

            edli_employee_basis[
                "edli_part_b_lower_if_qualifying"
            ]

            > edli_employee_basis[
                "edli_part_b_upper_if_qualifying"
            ]

            + P09_TOLERANCE

        ).sum(),
    )


    # Upper range cannot exceed controlled maximum.
    add_validation(

        "EDLI qualifying Part B upper range <= maximum",

        (

            edli_employee_basis[
                "edli_part_b_upper_if_qualifying"
            ]

            > edli_employee_basis[
                "edli_illustrative_maximum_benefit"
            ]

            + P09_TOLERANCE

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # GTI VALIDATIONS
    # -------------------------------------------------------------------------


    # Sum Assured must be positive.
    add_validation(

        "GTI Sum Assured positive",

        (

            gti_pricing[
                "sum_assured"
            ].isna()

            | (
                gti_pricing[
                    "sum_assured"
                ]
                <= 0
            )

        ).sum(),
    )


    # Mortality probabilities must lie in [0,1].
    add_validation(

        "GTI mortality probability within [0,1]",

        (

            gti_pricing[
                "q_death_1y"
            ].isna()

            | (
                gti_pricing[
                    "q_death_1y"
                ]
                < 0
            )

            | (
                gti_pricing[
                    "q_death_1y"
                ]
                > 1
            )

        ).sum(),
    )


    # Expected claims cannot be negative.
    add_validation(

        "GTI fresh expected claim cost non-negative",

        (

            gti_pricing[
                "fresh_expected_claim_cost"
            ]

            < -P09_TOLERANCE

        ).sum(),
    )


    # Gross premium denominator must be positive.
    add_validation(

        "GTI gross premium loading denominator positive",

        (

            gti_pricing[
                "gross_premium_denominator"
            ]

            <= 0

        ).sum(),
    )


    # Gross premium should be at least adjusted expected claims
    # when loading is non-negative.
    add_validation(

        "GTI gross premium >= adjusted expected claims",

        (

            gti_pricing[
                "gross_model_premium"
            ]

            + P09_TOLERANCE

            < gti_pricing[
                "adjusted_expected_claim_cost"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # PLAN RECONCILIATION
    # -------------------------------------------------------------------------


    # Employee-level gross premium total.
    employee_total_premium = float(

        gti_pricing[
            "gross_model_premium"
        ].sum()
    )


    # Plan-level gross premium total.
    plan_total_premium = float(

        gti_plan_summary[
            "gross_model_premium"
        ].sum()
    )


    # Confirm both totals reconcile.
    add_validation(

        "GTI plan premium reconciles to employee premium",

        int(

            abs(

                employee_total_premium

                - plan_total_premium
            )

            > max(

                1.0,

                abs(
                    employee_total_premium
                )
            )

            * 1e-10
        ),
    )


    # -------------------------------------------------------------------------
    # HISTORICAL EXPERIENCE VALIDATION
    # -------------------------------------------------------------------------


    # Historical expected Death counts cannot be negative.
    if not historical_gti_detail.empty:


        add_validation(

            "Historical GTI expected deaths non-negative",

            (

                historical_gti_detail[
                    "expected_death_count"
                ]

                < -P09_TOLERANCE

            ).sum(),
        )


    # Return validation table.
    return pd.DataFrame(
        validation_rows
    )


# =============================================================================
# P09 SECTION 12 - GOVERNANCE SUMMARY
# =============================================================================


# Define non-failure review items separately from mathematical validation.
def build_pipeline_09_governance(
    edli_employee_basis,
    edli_claim_review,
    gti_pricing,
    historical_gti_detail,
):


    # Count EDLI APB gaps.
    apb_missing = int(

        edli_employee_basis[
            "average_progressive_balance"
        ].isna().sum()
    )


    # Count missing continuity information.
    continuity_missing = int(

        (

            ~edli_employee_basis[
                "edli_continuity_known_flag"
            ]

        ).sum()
    )


    # Count current wage proxies.
    wage_proxy_count = int(

        edli_employee_basis[
            "edli_model_status"
        ].str.contains(

            "CURRENT_WAGE_USED_AS_12M_PROXY",

            na=False
        ).sum()
    )


    # Count historical EDLI claims needing another rule set.
    historical_edli_rule_reviews = (

        int(

            edli_claim_review[
                "edli_claim_review_status"
            ].eq(
                "REVIEW_HISTORICAL_EDLI_RULE_REQUIRED"
            ).sum()
        )

        if not edli_claim_review.empty

        else 0
    )


    # Count GTI mortality rows recalculated directly from the plan rules.
    direct_gti_mortality = int(

        gti_pricing[
            "gti_mortality_source"
        ].eq(
            "DIRECT_GTI_PLAN_RULE_MORTALITY"
        ).sum()
    )


    # Count GTI underwriting referrals.
    underwriting_referrals = int(

        gti_pricing[
            "underwriting_referral_flag"
        ].sum()
    )


    # Count historical GTI rows without exposure.
    historical_exposure_missing = (

        int(

            historical_gti_detail[
                "exposure_years"
            ].isna().sum()
        )

        if not historical_gti_detail.empty

        else 0
    )


    # Build governance register.
    return pd.DataFrame([


        {
            "governance_item":
                "EDLI Average Progressive Balance unavailable",

            "review_rows":
                apb_missing,

            "treatment":
                (
                    "Final statutory benefit is not fabricated; "
                    "qualifying Part B range is shown instead."
                ),
        },


        {
            "governance_item":
                "EDLI continuity information unavailable",

            "review_rows":
                continuity_missing,

            "treatment":
                (
                    "Pipeline does not infer statutory continuity "
                    "from ordinary completed service."
                ),
        },


        {
            "governance_item":
                "EDLI twelve-month average wage unavailable",

            "review_rows":
                wage_proxy_count,

            "treatment":
                (
                    "Current EDLI eligible wage is used only as an "
                    "explicitly flagged analytical proxy."
                ),
        },


        {
            "governance_item":
                "Historical EDLI event requires historical rule set",

            "review_rows":
                historical_edli_rule_reviews,

            "treatment":
                (
                    "Current statutory rule is not back-cast "
                    "to earlier death dates."
                ),
        },


        {
            "governance_item":
                "GTI Pipeline 06 mortality unavailable",

            "review_rows":
                direct_gti_mortality,

            "treatment":
                (
                    "Same GTI plan-specific Gompertz-Makeham parameters "
                    "are calculated directly and source is flagged."
                ),
        },


        {
            "governance_item":
                "GTI free-cover-limit underwriting referrals",

            "review_rows":
                underwriting_referrals,

            "treatment":
                (
                    "Employee remains covered in analytical pricing basis; "
                    "underwriting referral is reported separately."
                ),
        },


        {
            "governance_item":
                "Historical GTI exposure unavailable",

            "review_rows":
                historical_exposure_missing,

            "treatment":
                (
                    "Rows without defensible exposure are excluded "
                    "from expected mortality experience."
                ),
        },
    ])


