# Define a small numerical tolerance for reconciliation checks.
P10_TOLERANCE = 1e-8


# =============================================================================
# P10 HELPER 01 - NORMALISE TEXT
# =============================================================================


def p10_normalise_text(
    value,
):
    """
    Convert text into a consistent comparison format.

    Examples:

        "DB Pension"     -> "dbpension"
        "DB_Pension"     -> "dbpension"
        "DB-Pension"     -> "dbpension"
    """

    # Missing values become blank text.
    if pd.isna(
        value
    ):

        return ""


    # Convert to lower-case text.
    text = str(
        value
    ).strip().lower()


    # Keep only letters and numbers.
    return "".join(

        character

        for character in text

        if character.isalnum()
    )


# =============================================================================
# P10 HELPER 02 - BOOLEAN INTERPRETATION
# =============================================================================


def p10_to_bool(
    value,
):
    """
    Convert common Yes / No / True / False values into Boolean form.
    """

    # Preserve genuine Boolean values.
    if isinstance(
        value,
        (
            bool,
            np.bool_,
        ),
    ):

        return bool(
            value
        )


    # Normalise the remaining values.
    text = p10_normalise_text(
        value
    )


    # Recognise positive representations.
    return text in {

        "true",

        "yes",

        "y",

        "1",

        "active",

        "covered",
    }


# =============================================================================
# P10 HELPER 03 - FIND FIRST AVAILABLE COLUMN
# =============================================================================


def p10_first_column(
    dataframe,
    candidates,
    required=False,
):
    """
    Search several possible column names and return the first one found.
    """

    # Search candidate names in priority order.
    for column in candidates:


        # Return immediately when a column exists.
        if column in dataframe.columns:

            return column


    # Stop transparently when a compulsory field is absent.
    if required:

        raise KeyError(

            "Pipeline 10 could not find any of these required columns: "
            f"{candidates}"
        )


    # Optional columns may legitimately be unavailable.
    return None


# =============================================================================
# P10 HELPER 04 - SAFE NUMERIC CONVERSION
# =============================================================================


def p10_numeric(
    series,
):
    """
    Convert a pandas Series into numeric form without crashing.
    """

    # Convert invalid values to NaN.
    return pd.to_numeric(

        series,

        errors="coerce"
    )


# =============================================================================
# P10 HELPER 05 - SAFE SERIES SUM
# =============================================================================


def p10_sum(
    series,
):
    """
    Sum a Series while preserving the distinction between:

        genuine zero
        and
        completely unavailable data.
    """

    # Return NaN when the Series itself does not exist.
    if series is None:

        return np.nan


    # Convert to numeric.
    numeric_series = pd.to_numeric(

        series,

        errors="coerce"
    )


    # Return NaN if every value is missing.
    if numeric_series.notna().sum() == 0:

        return np.nan


    # Otherwise return the numerical sum.
    return float(

        numeric_series.sum()
    )


# =============================================================================
# P10 HELPER 06 - SEARCH DATAFRAMES INSIDE PRIOR PIPELINE RESULTS
# =============================================================================


def p10_iter_dataframes(
    source,
):
    """
    Recursively yield pandas DataFrames contained inside prior
    pipeline-result dictionaries.
    """

    # A DataFrame can be returned directly.
    if isinstance(
        source,
        pd.DataFrame
    ):

        yield source

        return


    # Search dictionaries recursively.
    if isinstance(
        source,
        dict
    ):


        # Inspect every object stored in the dictionary.
        for value in source.values():


            # Recursively search that object.
            yield from p10_iter_dataframes(
                value
            )


# =============================================================================
# P10 HELPER 07 - FIND ONE DATAFRAME BY COLUMN SIGNATURE
# =============================================================================


def p10_find_dataframe(
    source,
    required_all=(),
    required_any=(),
):
    """
    Find a DataFrame inside a prior pipeline result by checking its columns.
    """

    # Search every DataFrame stored in the result object.
    for dataframe in p10_iter_dataframes(
        source
    ):


        # Convert column names into a set.
        columns = set(
            dataframe.columns
        )


        # Every required-all field must exist.
        all_condition = all(

            column in columns

            for column in required_all
        )


        # At least one required-any field must exist.
        any_condition = (

            True

            if len(
                required_any
            ) == 0

            else any(

                column in columns

                for column in required_any
            )
        )


        # Return the first structurally valid table.
        if (
            all_condition

            and any_condition
        ):

            return dataframe.copy()


    # Return None when nothing appropriate exists.
    return None


# =============================================================================
# P10 HELPER 08 - FIND A SAVED CSV BY COLUMN SIGNATURE
# =============================================================================


def p10_load_csv_by_columns(
    root_directory,
    patterns,
    required_all=(),
    required_any=(),
):
    """
    Search previously written model-ready CSV files.

    The function first inspects only the header.

    The full file is loaded only when the required column structure matches.
    """

    # Process search patterns in priority order.
    for pattern in patterns:


        # Search recursively below the supplied root directory.
        candidate_paths = sorted(

            root_directory.rglob(
                pattern
            )
        )


        # Inspect every matching file.
        for path in candidate_paths:


            # Ignore directories.
            if not path.is_file():

                continue


            try:


                # Read only the header first.
                header = pd.read_csv(

                    path,

                    nrows=0
                )


            except Exception:


                # Ignore an unreadable candidate and continue searching.
                continue


            # Convert available columns to a set.
            columns = set(
                header.columns
            )


            # Check mandatory fields.
            all_condition = all(

                column in columns

                for column in required_all
            )


            # Check alias fields.
            any_condition = (

                True

                if len(
                    required_any
                ) == 0

                else any(

                    column in columns

                    for column in required_any
                )
            )


            # Read the complete file when its structure matches.
            if (
                all_condition

                and any_condition
            ):


                # Load the complete dataset.
                dataframe = pd.read_csv(
                    path
                )


                # Return both data and audit path.
                return (
                    dataframe,
                    path,
                )


    # Nothing suitable was found.
    return (
        pd.DataFrame(),
        None,
    )


# =============================================================================
# P10 HELPER 09 - STANDARDISE GRATUITY EMPLOYEE OUTPUT
# =============================================================================


def p10_standardise_gratuity(
    gratuity_source,
):
    """
    Standardise Pipeline 07 employee-level Gratuity output.

    Pipeline 10 does not change the values.

    It only maps possible historical column names into a stable
    Portfolio Layer naming convention.
    """

    # Return an empty standard structure when no source exists.
    if (
        gratuity_source is None

        or gratuity_source.empty
    ):

        return pd.DataFrame(

            columns=[

                "employee_id",

                "gratuity_dbo",

                "gratuity_puc_one_service_year_pv",
            ]
        )


    # Work on a copy.
    source = gratuity_source.copy()


    # Locate employee identifier.
    employee_column = p10_first_column(

        source,

        [
            "employee_id",
        ],

        required=True,
    )


    # Search possible liability column names.
    liability_column = p10_first_column(

        source,

        [

            "gratuity_dbo",

            "gratuity_liability",

            "projected_unit_credit_dbo",

            "puc_dbo",

            "dbo",

            "present_value_obligation",
        ],

        required=True,
    )


    # Search possible one-service-year PUC fields.
    service_cost_column = p10_first_column(

        source,

        [

            "puc_one_service_year_pv",

            "one_service_year_pv",

            "current_service_cost_pv",

            "puc_service_cost",
        ],

        required=False,
    )


    # Create the standard output.
    result = pd.DataFrame()


    # Copy employee ID.
    result[
        "employee_id"
    ] = source[
        employee_column
    ]


    # Copy Gratuity DBO.
    result[
        "gratuity_dbo"
    ] = p10_numeric(

        source[
            liability_column
        ]
    )


    # Copy one-service-year PUC when available.
    if service_cost_column is not None:


        result[
            "gratuity_puc_one_service_year_pv"
        ] = p10_numeric(

            source[
                service_cost_column
            ]
        )


    # Otherwise preserve the missing information explicitly.
    else:


        result[
            "gratuity_puc_one_service_year_pv"
        ] = np.nan


    # Return standardised employee output.
    return result


# =============================================================================
# P10 HELPER 10 - LOAD LATEST PLAN ASSETS
# =============================================================================


def p10_latest_plan_assets():
    """
    Load the latest plan assets on or before the valuation date.

    Plan assets are used only for funded Defined Benefit arrangements.
    """

    # Define the normal raw-data location.
    raw_asset_path = (

        PROJECT_ROOT

        / "Data"

        / "plan_assets.csv"
    )


    # Define a possible processed-data location.
    processed_asset_path = (

        PROJECT_ROOT

        / "Data"

        / "processed"

        / "plan_assets.csv"
    )


    # Prefer processed data when it exists.
    if processed_asset_path.exists():


        asset_path = processed_asset_path


    # Otherwise use the raw reconciled dataset.
    elif raw_asset_path.exists():


        asset_path = raw_asset_path


    # No asset file means funding cannot be calculated.
    else:


        return pd.DataFrame(

            columns=[

                "plan_id",

                "product_type",

                "plan_assets",
            ]
        )


    # Load plan assets.
    assets = pd.read_csv(
        asset_path
    )


    # Parse valuation date.
    assets[
        "valuation_date"
    ] = pd.to_datetime(

        assets[
            "valuation_date"
        ],

        errors="coerce"
    )


    # Convert closing assets to numeric.
    assets[
        "closing_plan_assets"
    ] = pd.to_numeric(

        assets[
            "closing_plan_assets"
        ],

        errors="coerce"
    )


    # Keep records effective on or before valuation date.
    assets = assets.loc[

        assets[
            "valuation_date"
        ]

        <= VALUATION_DATE

    ].copy()


    # Sort chronologically.
    assets = assets.sort_values(

        [
            "plan_id",

            "valuation_date",
        ]
    )


    # Keep the latest asset record for each plan.
    assets = (

        assets

        .groupby(

            "plan_id",

            as_index=False
        )

        .tail(
            1
        )

        .copy()
    )


    # Keep only fields needed by Pipeline 10.
    assets = assets[[

        "plan_id",

        "product_type",

        "closing_plan_assets",

    ]].copy()


    # Rename the financial field.
    assets = assets.rename(

        columns={

            "closing_plan_assets":
                "plan_assets"
        }
    )


    # Return latest funded position.
    return assets


# =============================================================================
# P10 SECTION 01 - RETRIEVE PIPELINE 07 GRATUITY OUTPUT
# =============================================================================


def p10_get_gratuity_output(
    gratuity_results=None,
):
    """
    Retrieve Pipeline 07 employee-level Gratuity valuation.

    Priority:

        1. In-memory Pipeline 07 result.
        2. Previously saved model-ready Pipeline 07 file.

    This protects Pipeline 10 from depending on one exact variable name.
    """

    # Define possible Gratuity liability field names.
    liability_aliases = [

        "gratuity_dbo",

        "gratuity_liability",

        "projected_unit_credit_dbo",

        "puc_dbo",

        "dbo",

        "present_value_obligation",
    ]


    # Search the in-memory Pipeline 07 result first.
    source = p10_find_dataframe(

        gratuity_results,

        required_all=[
            "employee_id"
        ],

        required_any=liability_aliases,
    )


    # If in-memory data are unavailable, inspect saved model-ready files.
    if source is None:


        # Search Pipeline 07 files by meaningful name patterns.
        (
            source,
            source_path,

        ) = p10_load_csv_by_columns(

            MODEL_READY_DATA_DIR,

            patterns=[

                "*gratuity*employee*.csv*",

                "*gratuity*liability*.csv*",

                "*gratuity*.csv*",
            ],

            required_all=[
                "employee_id"
            ],

            required_any=liability_aliases,
        )


    # Otherwise mark the source as in-memory.
    else:


        source_path = "IN_MEMORY_PIPELINE_07_RESULT"


    # Standardise the employee output.
    standardised = p10_standardise_gratuity(
        source
    )


    # Return both the data and source description.
    return (
        standardised,
        source_path,
    )


# =============================================================================
# P10 SECTION 02 - RETRIEVE PIPELINE 08 OUTPUTS
# =============================================================================


def p10_get_superannuation_outputs(
    superannuation_results=None,
):
    """
    Retrieve Pipeline 08 DB Pension and DC Superannuation employee outputs.
    """

    # -------------------------------------------------------------------------
    # DB PENSION
    # -------------------------------------------------------------------------


    # Search in-memory Pipeline 08 output.
    db_pension = p10_find_dataframe(

        superannuation_results,

        required_all=[

            "employee_id",

            "db_pension_liability",
        ],
    )


    # Use saved model-ready file when necessary.
    if db_pension is None:


        path = (

            MODEL_READY_DATA_DIR

            / "db_pension_employee_liability.csv"
        )


        # Read the saved file when available.
        if path.exists():


            db_pension = pd.read_csv(
                path
            )


        # Otherwise return an empty structure.
        else:


            db_pension = pd.DataFrame()


    # -------------------------------------------------------------------------
    # DC SUPERANNUATION
    # -------------------------------------------------------------------------


    # Search Pipeline 08 outputs.
    dc_superannuation = p10_find_dataframe(

        superannuation_results,

        required_all=[

            "employee_id",

            "projected_future_contribution_corpus",
        ],
    )


    # Use saved model-ready output when necessary.
    if dc_superannuation is None:


        path = (

            MODEL_READY_DATA_DIR

            / "dc_superannuation_member_projection.csv"
        )


        # Load if available.
        if path.exists():


            dc_superannuation = pd.read_csv(
                path
            )


        # Otherwise return empty structure.
        else:


            dc_superannuation = pd.DataFrame()


    # Return both benefit engines.
    return (
        db_pension,
        dc_superannuation,
    )


# =============================================================================
# P10 SECTION 03 - RETRIEVE PIPELINE 09 OUTPUTS
