# =============================================================================
# P10 SECTION 04 - BUILD EMPLOYEE PORTFOLIO RISK MATRIX
# =============================================================================


def build_portfolio_employee_risk_matrix(
    employee_features,
    gratuity_employee,
    db_pension,
    dc_superannuation,
    gti,
    edli,
):
    """
    Build one employee-level cross-product portfolio table.

    One row = one employee.

    Product-engine outputs are merged onto the employee master.
    """

    # -------------------------------------------------------------------------
    # 04.1 - SELECT USEFUL EMPLOYEE FIELDS
    # -------------------------------------------------------------------------


    # Define employee fields useful for portfolio analysis.
    candidate_columns = [

        "employee_id",

        "employment_status",

        "department",

        "location",

        "grade",

        "attained_age_years",

        "completed_service_years",

        "gratuity_plan_id",

        "superannuation_plan_id",

        "gti_plan_id",

        "active_gratuity_member_flag",

        "active_db_pension_member_flag",

        "active_dc_superannuation_member_flag",

        "active_edli_member_flag",

        "active_gti_member_flag",
    ]


    # Retain only columns that genuinely exist.
    available_columns = [

        column

        for column in candidate_columns

        if column
        in employee_features.columns
    ]


    # Employee ID is compulsory.
    if "employee_id" not in available_columns:

        raise KeyError(

            "Pipeline 10 requires employee_id "
            "in Pipeline 04 employee features."
        )


    # Create the initial one-row-per-employee portfolio matrix.
    portfolio = employee_features[

        available_columns

    ].copy()


    # Confirm uniqueness before integrating product outputs.
    if portfolio[
        "employee_id"
    ].duplicated().any():

        raise ValueError(

            "Pipeline 10 found duplicate employee IDs "
            "in the model-ready employee feature table."
        )


    # -------------------------------------------------------------------------
    # 04.2 - MERGE GRATUITY
    # -------------------------------------------------------------------------


    # Merge employee-level Gratuity liability when available.
    if not gratuity_employee.empty:


        portfolio = portfolio.merge(

            gratuity_employee,

            on="employee_id",

            how="left",

            validate="one_to_one"
        )


    # Otherwise create explicit missing fields.
    else:


        portfolio[
            "gratuity_dbo"
        ] = np.nan


        portfolio[
            "gratuity_puc_one_service_year_pv"
        ] = np.nan


    # -------------------------------------------------------------------------
    # 04.3 - MERGE DB PENSION
    # -------------------------------------------------------------------------


    # Merge DB Pension valuation when available.
    if not db_pension.empty:


        # Select relevant DB fields.
        db_columns = [

            column

            for column in [

                "employee_id",

                "plan_id",

                "member_dbo",

                "spouse_dbo",

                "db_pension_liability",

                "puc_one_service_year_pv",

                "probability_reach_retirement_active",

                "active_survival_source",
            ]

            if column
            in db_pension.columns
        ]


        # Create DB merge table.
        db_merge = db_pension[

            db_columns

        ].copy()


        # Rename plan identifier.
        if "plan_id" in db_merge.columns:


            db_merge = db_merge.rename(

                columns={

                    "plan_id":
                        "db_pension_plan_id"
                }
            )


        # Rename PUC field so it cannot be confused with Gratuity.
        if (
            "puc_one_service_year_pv"
            in db_merge.columns
        ):


            db_merge = db_merge.rename(

                columns={

                    "puc_one_service_year_pv":
                        "db_pension_puc_one_service_year_pv"
                }
            )


        # Merge.
        portfolio = portfolio.merge(

            db_merge,

            on="employee_id",

            how="left",

            validate="one_to_one"
        )


    # -------------------------------------------------------------------------
    # 04.4 - MERGE DC SUPERANNUATION
    # -------------------------------------------------------------------------


    # Merge DC projection when available.
    if not dc_superannuation.empty:


        # Select relevant DC fields.
        dc_columns = [

            column

            for column in [

                "employee_id",

                "plan_id",

                "current_annual_employer_contribution",

                "current_annual_employee_contribution",

                "projected_future_contribution_corpus",

                "projected_member_corpus_from_available_data",

                "opening_member_corpus_available",

                "model_status",
            ]

            if column
            in dc_superannuation.columns
        ]


        # Create merge table.
        dc_merge = dc_superannuation[

            dc_columns

        ].copy()


        # Rename generic plan identifier.
        if "plan_id" in dc_merge.columns:


            dc_merge = dc_merge.rename(

                columns={

                    "plan_id":
                        "dc_superannuation_plan_id"
                }
            )


        # Rename model status.
        if "model_status" in dc_merge.columns:


            dc_merge = dc_merge.rename(

                columns={

                    "model_status":
                        "dc_model_status"
                }
            )


        # Merge.
        portfolio = portfolio.merge(

            dc_merge,

            on="employee_id",

            how="left",

            validate="one_to_one"
        )


    # -------------------------------------------------------------------------
    # 04.5 - PREPARE GTI FRESH-MODEL PREMIUM
    # -------------------------------------------------------------------------


    # Work only when GTI output exists.
    if not gti.empty:


        # Copy GTI output.
        gti_merge = gti.copy()


        # Convert loading into numeric form.
        gti_merge[
            "gross_premium_loading_rate"
        ] = p10_numeric(

            gti_merge[
                "gross_premium_loading_rate"
            ]
        )


        # Calculate the denominator:
        #
        #     1 - loading
        gti_merge[
            "_fresh_gross_premium_denominator"
        ] = (

            1.0

            - gti_merge[
                "gross_premium_loading_rate"
            ]
        )


        # Calculate the fresh-model gross premium.
        #
        # IMPORTANT:
        #
        # This deliberately does NOT use Pipeline 09's historical
        # credibility-adjusted expected claim amount.
        gti_merge[
            "fresh_model_gross_premium"
        ] = np.where(

            gti_merge[
                "_fresh_gross_premium_denominator"
            ] > 0,

            gti_merge[
                "fresh_expected_claim_cost"
            ]

            / gti_merge[
                "_fresh_gross_premium_denominator"
            ],

            np.nan
        )


        # Select useful GTI fields.
        gti_columns = [

            column

            for column in [

                "employee_id",

                "plan_id",

                "cover_basis",

                "sum_assured",

                "q_death_1y",

                "fresh_expected_death_count",

                "fresh_expected_claim_cost",

                "gross_premium_loading_rate",

                "fresh_model_gross_premium",

                "underwriting_referral_flag",

                "cover_above_free_cover_limit",

                "free_cover_limit",

                "gross_model_premium",

                "experience_factor",
            ]

            if column
            in gti_merge.columns
        ]


        # Keep those fields.
        gti_merge = gti_merge[

            gti_columns

        ].copy()


        # Rename GTI fields into explicit portfolio names.
        rename_map = {


            "plan_id":
                "gti_pricing_plan_id",


            "sum_assured":
                "gti_sum_assured",


            "q_death_1y":
                "gti_q_death_1y",


            "fresh_expected_death_count":
                "gti_fresh_expected_death_count",


            "fresh_expected_claim_cost":
                "gti_fresh_expected_claim_cost",


            "gross_premium_loading_rate":
                "gti_gross_premium_loading_rate",


            "fresh_model_gross_premium":
                "gti_fresh_model_gross_premium",


            "underwriting_referral_flag":
                "gti_underwriting_referral_flag",


            "cover_above_free_cover_limit":
                "gti_cover_above_free_cover_limit",


            "free_cover_limit":
                "gti_free_cover_limit",


            # Retain the old Pipeline 09 premium only for audit.
            "gross_model_premium":
                "gti_excluded_experience_adjusted_premium",


            "experience_factor":
                "gti_excluded_experience_factor",
        }


        # Rename available fields.
        gti_merge = gti_merge.rename(

            columns=rename_map
        )


        # Merge GTI into employee portfolio.
        portfolio = portfolio.merge(

            gti_merge,

            on="employee_id",

            how="left",

            validate="one_to_one"
        )


    # -------------------------------------------------------------------------
    # 04.6 - MERGE EDLI
    # -------------------------------------------------------------------------


    # Merge EDLI analytical basis when available.
    if not edli.empty:


        # Select relevant EDLI fields.
        edli_columns = [

            column

            for column in [

                "employee_id",

                "edli_plan_id",

                "edli_capped_monthly_wage",

                "edli_part_b_lower_if_qualifying",

                "edli_part_b_upper_if_qualifying",

                "official_calculator_required_flag",

                "edli_model_status",
            ]

            if column
            in edli.columns
        ]


        # Merge EDLI.
        portfolio = portfolio.merge(

            edli[
                edli_columns
            ],

            on="employee_id",

            how="left",

            validate="one_to_one"
        )


    # -------------------------------------------------------------------------
    # 04.7 - ENSURE ALL PORTFOLIO METRIC COLUMNS EXIST
    # -------------------------------------------------------------------------


    # Define fields required downstream even when a product table was absent.
    default_columns = {


        "gratuity_dbo":
            np.nan,


        "gratuity_puc_one_service_year_pv":
            np.nan,


        "db_pension_liability":
            np.nan,


        "db_pension_puc_one_service_year_pv":
            np.nan,


        "current_annual_employer_contribution":
            np.nan,


        "current_annual_employee_contribution":
            np.nan,


        "projected_future_contribution_corpus":
            np.nan,


        "gti_sum_assured":
            np.nan,


        "gti_fresh_expected_claim_cost":
            np.nan,


        "gti_fresh_model_gross_premium":
            np.nan,


        "gti_underwriting_referral_flag":
            False,


        "gti_cover_above_free_cover_limit":
            np.nan,


        "edli_part_b_lower_if_qualifying":
            np.nan,


        "edli_part_b_upper_if_qualifying":
            np.nan,
    }


    # Create any missing fields.
    for (
        column,
        default_value,

    ) in default_columns.items():


        if column not in portfolio.columns:


            portfolio[
                column
            ] = default_value


    # -------------------------------------------------------------------------
    # 04.8 - EMPLOYEE-LEVEL COMBINED DB LIABILITY
    # -------------------------------------------------------------------------


    # Defined Benefit liability consists of:
    #
    #     Gratuity DBO
    #         +
    #     DB Pension DBO
    #
    # DC accumulation is deliberately excluded.
    portfolio[
        "combined_db_liability"
    ] = (

        portfolio[
            "gratuity_dbo"
        ].fillna(
            0.0
        )

        + portfolio[
            "db_pension_liability"
        ].fillna(
            0.0
        )
    )


    # -------------------------------------------------------------------------
    # 04.9 - EMPLOYEE TOTAL CURRENT GROUP-RISK COVER
    # -------------------------------------------------------------------------


    # GTI Sum Assured is a contractual risk exposure.
    #
    # EDLI is deliberately NOT added because final official EDLI benefit
    # has not been calculated.
    portfolio[
        "known_group_risk_cover"
    ] = portfolio[
        "gti_sum_assured"
    ].fillna(
        0.0
    )


    # Store Pipeline version.
    portfolio[
        "pipeline_10_version"
    ] = P10_VERSION


    # Return integrated employee table.
    return portfolio


# =============================================================================
# P10 SECTION 05 - BUILD PLAN-LEVEL PORTFOLIO SUMMARY
# =============================================================================


def build_portfolio_plan_summary(
    employee_portfolio,
    latest_plan_assets,
):
    """
    Produce one portfolio row per benefit plan.
    """

    # Create a container for product-plan tables.
    plan_frames = []


    # -------------------------------------------------------------------------
    # 05.1 - GRATUITY PLANS
    # -------------------------------------------------------------------------


    # Continue if the employee master contains the Gratuity plan ID.
    if (
        "gratuity_plan_id"
        in employee_portfolio.columns
    ):


        # Keep employees with a Gratuity plan.
        gratuity = employee_portfolio.loc[

            employee_portfolio[
                "gratuity_plan_id"
            ].notna()

        ].copy()


        # Build plan summary when rows exist.
        if not gratuity.empty:


            gratuity_summary = (

                gratuity

                .groupby(

                    "gratuity_plan_id",

                    as_index=False
                )

                .agg(


                    active_members=(

                        "employee_id",

                        "nunique"
                    ),


                    actuarial_liability=(

                        "gratuity_dbo",

                        "sum"
                    ),


                    puc_one_service_year_pv=(

                        "gratuity_puc_one_service_year_pv",

                        "sum"
                    ),
                )
            )


            # Rename plan identifier.
            gratuity_summary = gratuity_summary.rename(

                columns={

                    "gratuity_plan_id":
                        "plan_id"
                }
            )


            # Identify product.
            gratuity_summary[
                "product_type"
            ] = "Gratuity"


            # Add to plan collection.
            plan_frames.append(
                gratuity_summary
            )


    # -------------------------------------------------------------------------
    # 05.2 - DB PENSION PLANS
    # -------------------------------------------------------------------------


    # Continue when DB plan ID exists.
    if (
        "db_pension_plan_id"
        in employee_portfolio.columns
    ):


        # Keep DB pension employees.
        db = employee_portfolio.loc[

            employee_portfolio[
                "db_pension_plan_id"
            ].notna()

        ].copy()


        # Build summary.
        if not db.empty:


            db_summary = (

                db

                .groupby(

                    "db_pension_plan_id",

                    as_index=False
                )

                .agg(


                    active_members=(

                        "employee_id",

                        "nunique"
                    ),


                    actuarial_liability=(

                        "db_pension_liability",

                        "sum"
                    ),


                    puc_one_service_year_pv=(

                        "db_pension_puc_one_service_year_pv",

                        "sum"
                    ),
                )
            )


            # Rename plan.
            db_summary = db_summary.rename(

                columns={

                    "db_pension_plan_id":
                        "plan_id"
                }
            )


            # Identify product.
            db_summary[
                "product_type"
            ] = "DB_Pension"


            # Add table.
            plan_frames.append(
                db_summary
            )


    # -------------------------------------------------------------------------
    # 05.3 - DC SUPERANNUATION PLANS
    # -------------------------------------------------------------------------


    # Continue when DC plan ID exists.
    if (
        "dc_superannuation_plan_id"
        in employee_portfolio.columns
    ):


        # Keep DC members.
        dc = employee_portfolio.loc[

            employee_portfolio[
                "dc_superannuation_plan_id"
            ].notna()

        ].copy()


        # Build plan summary.
        if not dc.empty:


            dc_summary = (

                dc

                .groupby(

                    "dc_superannuation_plan_id",

                    as_index=False
                )

                .agg(


                    active_members=(

                        "employee_id",

                        "nunique"
                    ),


                    annual_employer_contribution=(

                        "current_annual_employer_contribution",

                        "sum"
                    ),


                    annual_employee_contribution=(

                        "current_annual_employee_contribution",

                        "sum"
                    ),


                    projected_future_contribution_corpus=(

                        "projected_future_contribution_corpus",

                        "sum"
                    ),
                )
            )


            # Rename plan.
            dc_summary = dc_summary.rename(

                columns={

                    "dc_superannuation_plan_id":
                        "plan_id"
                }
            )


            # Product label.
            dc_summary[
                "product_type"
            ] = "DC_Superannuation"


            # Add table.
            plan_frames.append(
                dc_summary
            )


    # -------------------------------------------------------------------------
    # 05.4 - GTI PLANS
    # -------------------------------------------------------------------------


    # Continue when GTI plan field exists.
    if (
        "gti_pricing_plan_id"
        in employee_portfolio.columns
    ):


        # Keep GTI members.
        gti = employee_portfolio.loc[

            employee_portfolio[
                "gti_pricing_plan_id"
            ].notna()

        ].copy()


        # Build plan summary.
        if not gti.empty:


            gti_summary = (

                gti

                .groupby(

                    "gti_pricing_plan_id",

                    as_index=False
                )

                .agg(


                    active_members=(

                        "employee_id",

                        "nunique"
                    ),


                    total_sum_assured=(

                        "gti_sum_assured",

                        "sum"
                    ),


                    fresh_expected_claim_cost=(

                        "gti_fresh_expected_claim_cost",

                        "sum"
                    ),


                    fresh_model_gross_premium=(

                        "gti_fresh_model_gross_premium",

                        "sum"
                    ),


                    underwriting_referrals=(

                        "gti_underwriting_referral_flag",

                        "sum"
                    ),


                    cover_above_free_cover_limit=(

                        "gti_cover_above_free_cover_limit",

                        "sum"
                    ),
                )
            )


            # Rename plan.
            gti_summary = gti_summary.rename(

                columns={

                    "gti_pricing_plan_id":
                        "plan_id"
                }
            )


            # Product label.
            gti_summary[
                "product_type"
            ] = "GTI"


            # Add table.
            plan_frames.append(
                gti_summary
            )


    # -------------------------------------------------------------------------
    # 05.5 - EDLI PLAN
    # -------------------------------------------------------------------------


    # Continue when EDLI plan exists.
    if (
        "edli_plan_id"
        in employee_portfolio.columns
    ):


        # Keep EDLI employees.
        edli = employee_portfolio.loc[

            employee_portfolio[
                "edli_plan_id"
            ].notna()

        ].copy()


        # Build summary.
        if not edli.empty:


            edli_summary = (

                edli

                .groupby(

                    "edli_plan_id",

                    as_index=False
                )

                .agg(


                    active_members=(

                        "employee_id",

                        "nunique"
                    ),


                    edli_part_b_lower_if_qualifying=(

                        "edli_part_b_lower_if_qualifying",

                        "sum"
                    ),


                    edli_part_b_upper_if_qualifying=(

                        "edli_part_b_upper_if_qualifying",

                        "sum"
                    ),
                )
            )


            # Rename plan.
            edli_summary = edli_summary.rename(

                columns={

                    "edli_plan_id":
                        "plan_id"
                }
            )


            # Product label.
            edli_summary[
                "product_type"
            ] = "EDLI"


            # Add table.
            plan_frames.append(
                edli_summary
            )


    # -------------------------------------------------------------------------
    # 05.6 - COMBINE ALL PLAN TABLES
    # -------------------------------------------------------------------------


    # Stop gracefully when no plan information exists.
    if len(
        plan_frames
    ) == 0:

        return pd.DataFrame()


    # Combine all products vertically.
    plan_summary = pd.concat(

        plan_frames,

        ignore_index=True,

        sort=False
    )


    # -------------------------------------------------------------------------
    # 05.7 - ATTACH FUNDED PLAN ASSETS
    # -------------------------------------------------------------------------


    # Merge latest plan assets.
    if not latest_plan_assets.empty:


        plan_summary = plan_summary.merge(

            latest_plan_assets[[

                "plan_id",

                "plan_assets",

            ]],

            on="plan_id",

            how="left"
        )


    # Create asset field if no asset data exist.
    else:


        plan_summary[
            "plan_assets"
        ] = np.nan


    # Assets are meaningful as funding assets only for:
    #
    #     Gratuity
    #     DB Pension
    funded_product_mask = plan_summary[

        "product_type"

    ].isin([

        "Gratuity",

        "DB_Pension",
    ])


    # Remove asset interpretation from non-funded products.
    plan_summary.loc[

        ~funded_product_mask,

        "plan_assets"

    ] = np.nan


    # -------------------------------------------------------------------------
    # 05.8 - FUNDING RATIO
    # -------------------------------------------------------------------------


    # Calculate:
    #
    #     Assets / Liability
    plan_summary[
        "funding_ratio"
    ] = np.where(

        plan_summary.get(
            "actuarial_liability",
            pd.Series(
                index=plan_summary.index,
                dtype=float
            )
        ) > 0,

        plan_summary[
            "plan_assets"
        ]

        / plan_summary[
            "actuarial_liability"
        ],

        np.nan
    )


    # -------------------------------------------------------------------------
    # 05.9 - NET FUNDED POSITION
    # -------------------------------------------------------------------------


    # Calculate:
    #
    #     Assets - Liability
    plan_summary[
        "net_funded_position"
    ] = (

        plan_summary[
            "plan_assets"
        ]

        - plan_summary.get(

            "actuarial_liability",

            pd.Series(

                np.nan,

                index=plan_summary.index
            )
        )
    )


    # -------------------------------------------------------------------------
    # 05.10 - FUNDING DEFICIT
    # -------------------------------------------------------------------------


    # Calculate:
    #
    #     Liability - Assets
    plan_summary[
        "funding_deficit"
    ] = (

        plan_summary.get(

            "actuarial_liability",

            pd.Series(

                np.nan,

                index=plan_summary.index
            )
        )

        - plan_summary[
            "plan_assets"
        ]
    )


    # Store version.
    plan_summary[
        "pipeline_10_version"
    ] = P10_VERSION


    # Return plan-level portfolio.
    return plan_summary


# =============================================================================
# P10 SECTION 06 - BUILD PRODUCT-LEVEL PORTFOLIO SUMMARY
# =============================================================================


def build_portfolio_product_summary(
    plan_summary,
):
    """
    Aggregate plan results into one row per benefit product.
    """

    # Return empty result if no plan data exist.
    if plan_summary.empty:

        return pd.DataFrame()


    # Define portfolio metrics that may exist.
    metric_columns = [

        "actuarial_liability",

        "puc_one_service_year_pv",

        "plan_assets",

        "annual_employer_contribution",

        "annual_employee_contribution",

        "projected_future_contribution_corpus",

        "total_sum_assured",

        "fresh_expected_claim_cost",

        "fresh_model_gross_premium",

        "underwriting_referrals",

        "cover_above_free_cover_limit",

        "edli_part_b_lower_if_qualifying",

        "edli_part_b_upper_if_qualifying",
    ]


    # Create result rows.
    rows = []


    # Process one product at a time.
    for (
        product_type,
        group,

    ) in plan_summary.groupby(
        "product_type"
    ):


        # Start product row.
        row = {


            "product_type":
                product_type,


            "active_members":
                int(

                    group[
                        "active_members"
                    ].sum()
                ),
        }


        # Aggregate every possible financial metric.
        for metric in metric_columns:


            # Preserve unavailable metrics as NaN.
            if metric not in group.columns:


                row[
                    metric
                ] = np.nan


            else:


                row[
                    metric
                ] = p10_sum(

                    group[
                        metric
                    ]
                )


        # Calculate product-level funding ratio.
        liability = row[
            "actuarial_liability"
        ]


        assets = row[
            "plan_assets"
        ]


        # Funding ratio only applies when both values exist.
        if (

            pd.notna(
                liability
            )

            and liability > 0

            and pd.notna(
                assets
            )
        ):


            row[
                "funding_ratio"
            ] = (

                assets

                / liability
            )


            # Assets minus liability.
            row[
                "net_funded_position"
            ] = (

                assets

                - liability
            )


        else:


            row[
                "funding_ratio"
            ] = np.nan


            row[
                "net_funded_position"
            ] = np.nan


        # Store version.
        row[
            "pipeline_10_version"
        ] = P10_VERSION


        # Add product row.
        rows.append(
            row
        )


    # Convert rows into DataFrame.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# P10 SECTION 07 - BUILD SEGMENT CONCENTRATION SUMMARY
# =============================================================================


def build_portfolio_segment_summary(
    employee_portfolio,
):
    """
    Aggregate portfolio risk by:

        Department
        Location
        Grade

    when those dimensions exist.
    """

    # Define possible analytical dimensions.
    segment_columns = [

        "department",

        "location",

        "grade",
    ]


    # Define quantitative exposure metrics.
    metric_columns = [

        "gratuity_dbo",

        "db_pension_liability",

        "combined_db_liability",

        "current_annual_employer_contribution",

        "current_annual_employee_contribution",

        "projected_future_contribution_corpus",

        "gti_sum_assured",

        "gti_fresh_expected_claim_cost",

        "gti_fresh_model_gross_premium",

        "gti_cover_above_free_cover_limit",

        "edli_part_b_lower_if_qualifying",

        "edli_part_b_upper_if_qualifying",
    ]


    # Store all segment tables here.
    segment_frames = []


    # Process each available segmentation dimension.
    for segment_column in segment_columns:


        # Skip unavailable dimensions.
        if segment_column not in employee_portfolio.columns:

            continue


        # Work on a copy.
        working = employee_portfolio.copy()


        # Replace missing category labels explicitly.
        working[
            "_segment_value"
        ] = working[

            segment_column

        ].fillna(
            "MISSING"
        ).astype(
            str
        )


        # Create one row per segment value.
        rows = []


        # Process every category.
        for (
            segment_value,
            group,

        ) in working.groupby(
            "_segment_value"
        ):


            # Begin row.
            row = {


                "segment_type":
                    segment_column,


                "segment_value":
                    segment_value,


                "employee_count":
                    int(

                        group[
                            "employee_id"
                        ].nunique()
                    ),
            }


            # Aggregate quantitative exposures.
            for metric in metric_columns:


                if metric in group.columns:


                    value = p10_sum(

                        group[
                            metric
                        ]
                    )


                else:


                    value = np.nan


                # Store metric.
                row[
                    metric
                ] = value


            # Count FCL referrals.
            if (
                "gti_underwriting_referral_flag"
                in group.columns
            ):


                row[
                    "gti_underwriting_referrals"
                ] = int(

                    group[
                        "gti_underwriting_referral_flag"
                    ]

                    .fillna(
                        False
                    )

                    .astype(
                        bool
                    )

                    .sum()
                )


            else:


                row[
                    "gti_underwriting_referrals"
                ] = 0


            # Store version.
            row[
                "pipeline_10_version"
            ] = P10_VERSION


            # Add segment row.
            rows.append(
                row
            )


        # Convert segment rows.
        segment_frames.append(

            pd.DataFrame(
                rows
            )
        )


    # Return empty structure when no dimensions were available.
    if len(
        segment_frames
    ) == 0:

        return pd.DataFrame()


    # Combine department, location and grade summaries.
    return pd.concat(

        segment_frames,

        ignore_index=True,

        sort=False
    )


# =============================================================================
# P10 SECTION 08 - COUNT ACTIVE EMPLOYEES AND PRODUCT MEMBERS
# =============================================================================


def p10_membership_count(
    employee_portfolio,
    flag_candidates,
    fallback_column=None,
):
    """
    Count membership from Pipeline 04 membership flags.

    A metric-field fallback is used only when a dedicated flag does not exist.
    """

    # Search for an explicit membership flag.
    flag_column = p10_first_column(

        employee_portfolio,

        flag_candidates,

        required=False,
    )


    # Use explicit membership when available.
    if flag_column is not None:


        return int(

            employee_portfolio[

                flag_column

            ].apply(

                p10_to_bool

            ).sum()
        )


    # Otherwise use presence of a product output.
    if (

        fallback_column is not None

        and fallback_column
        in employee_portfolio.columns
    ):


        return int(

            employee_portfolio[

                fallback_column

            ].notna().sum()
        )


    # No defensible membership measure exists.
    return 0


# =============================================================================
# P10 SECTION 09 - BUILD COMPANY KPI TABLE
# =============================================================================


def build_portfolio_company_kpis(
    employee_portfolio,
    product_summary,
):
    """
    Create the single company-level KPI record used by the dashboard.
    """

    # -------------------------------------------------------------------------
    # 09.1 - EMPLOYEE POPULATION
    # -------------------------------------------------------------------------


    # Count all unique employee records.
    total_employee_records = int(

        employee_portfolio[
            "employee_id"
        ].nunique()
    )


    # Search for active employee flag.
    active_employee_column = p10_first_column(

        employee_portfolio,

        [
            "active_employee_flag",
        ],

        required=False,
    )


    # Use explicit active flag when available.
    if active_employee_column is not None:


        active_employees = int(

            employee_portfolio[

                active_employee_column

            ].apply(

                p10_to_bool

            ).sum()
        )


    # Otherwise use employment status.
    elif (
        "employment_status"
        in employee_portfolio.columns
    ):


        active_employees = int(

            employee_portfolio[

                "employment_status"

            ].apply(

                p10_normalise_text

            ).eq(
                "active"
            ).sum()
        )


    # Final fallback.
    else:


        active_employees = total_employee_records


    # -------------------------------------------------------------------------
    # 09.2 - PRODUCT MEMBERSHIP
    # -------------------------------------------------------------------------


    # Gratuity membership.
    gratuity_members = p10_membership_count(

        employee_portfolio,

        [
            "active_gratuity_member_flag",
        ],

        fallback_column="gratuity_dbo",
    )


    # DB Pension membership.
    db_pension_members = p10_membership_count(

        employee_portfolio,

        [
            "active_db_pension_member_flag",
        ],

        fallback_column="db_pension_liability",
    )


    # DC membership.
    dc_members = p10_membership_count(

        employee_portfolio,

        [
            "active_dc_superannuation_member_flag",
        ],

        fallback_column="projected_future_contribution_corpus",
    )


    # EDLI membership.
    edli_members = p10_membership_count(

        employee_portfolio,

        [
            "active_edli_member_flag",
        ],

        fallback_column="edli_plan_id",
    )


    # GTI membership.
    gti_members = p10_membership_count(

        employee_portfolio,

        [
            "active_gti_member_flag",
        ],

        fallback_column="gti_sum_assured",
    )


    # -------------------------------------------------------------------------
    # 09.3 - GRATUITY
    # -------------------------------------------------------------------------


    # Sum company Gratuity DBO.
    gratuity_dbo = p10_sum(

        employee_portfolio[
            "gratuity_dbo"
        ]
    )


    # Sum Gratuity one-service-year PV.
    gratuity_puc = p10_sum(

        employee_portfolio[
            "gratuity_puc_one_service_year_pv"
        ]
    )


    # -------------------------------------------------------------------------
    # 09.4 - DB PENSION
    # -------------------------------------------------------------------------


    # Sum DB Pension liability.
    db_pension_dbo = p10_sum(

        employee_portfolio[
            "db_pension_liability"
        ]
    )


    # Sum DB Pension one-service-year PUC.
    db_pension_puc = p10_sum(

        employee_portfolio[
            "db_pension_puc_one_service_year_pv"
        ]
    )


    # -------------------------------------------------------------------------
    # 09.5 - COMBINED DEFINED BENEFIT LIABILITY
    # -------------------------------------------------------------------------


    # Add Gratuity and DB Pension liabilities.
    combined_db_liability = (

        (
            0.0

            if pd.isna(
                gratuity_dbo
            )

            else gratuity_dbo
        )

        +

        (
            0.0

            if pd.isna(
                db_pension_dbo
            )

            else db_pension_dbo
        )
    )


    # -------------------------------------------------------------------------
    # 09.6 - COMBINED DEFINED BENEFIT ASSETS
    # -------------------------------------------------------------------------


    # Keep only funded DB products.
    funded_products = product_summary.loc[

        product_summary[
            "product_type"
        ].isin([

            "Gratuity",

            "DB_Pension",
        ])

    ].copy()


    # Sum assets.
    combined_db_assets = p10_sum(

        funded_products[
            "plan_assets"
        ]

        if (
            not funded_products.empty

            and "plan_assets"
            in funded_products.columns
        )

        else None
    )


    # Calculate combined funding ratio.
    combined_db_funding_ratio = (

        combined_db_assets

        / combined_db_liability

        if (

            combined_db_liability > 0

            and pd.notna(
                combined_db_assets
            )
        )

        else np.nan
    )


    # Calculate assets minus liability.
    combined_db_net_funded_position = (

        combined_db_assets

        - combined_db_liability

        if pd.notna(
            combined_db_assets
        )

        else np.nan
    )


    # Calculate liability minus assets.
    combined_db_funding_deficit = (

        combined_db_liability

        - combined_db_assets

        if pd.notna(
            combined_db_assets
        )

        else np.nan
    )


    # -------------------------------------------------------------------------
    # 09.7 - DC SUPERANNUATION
    # -------------------------------------------------------------------------


    # Employer contributions.
    dc_employer_contribution = p10_sum(

        employee_portfolio[
            "current_annual_employer_contribution"
        ]
    )


    # Employee contributions.
    dc_employee_contribution = p10_sum(

        employee_portfolio[
            "current_annual_employee_contribution"
        ]
    )


    # Future-contribution corpus.
    dc_future_corpus = p10_sum(

        employee_portfolio[
            "projected_future_contribution_corpus"
        ]
    )


    # -------------------------------------------------------------------------
    # 09.8 - GTI
    # -------------------------------------------------------------------------


    # Total Sum Assured.
    total_gti_sum_assured = p10_sum(

        employee_portfolio[
            "gti_sum_assured"
        ]
    )


    # Fresh expected claims.
    total_gti_expected_claims = p10_sum(

        employee_portfolio[
            "gti_fresh_expected_claim_cost"
        ]
    )


    # Fresh-model gross premium.
    total_gti_fresh_gross_premium = p10_sum(

        employee_portfolio[
            "gti_fresh_model_gross_premium"
        ]
    )


    # Count FCL referrals.
    gti_fcl_referrals = int(

        employee_portfolio[

            "gti_underwriting_referral_flag"

        ]

        .fillna(
            False
        )

        .astype(
            bool
        )

        .sum()
    )


    # Referral percentage.
    gti_fcl_referral_rate = (

        gti_fcl_referrals

        / gti_members

        if gti_members > 0

        else np.nan
    )


    # -------------------------------------------------------------------------
    # 09.9 - EDLI
    # -------------------------------------------------------------------------


    # Aggregate qualifying lower-range Part B exposure.
    edli_part_b_lower = p10_sum(

        employee_portfolio[
            "edli_part_b_lower_if_qualifying"
        ]
    )


    # Aggregate qualifying upper-range Part B exposure.
    edli_part_b_upper = p10_sum(

        employee_portfolio[
            "edli_part_b_upper_if_qualifying"
        ]
    )


    # Determine whether the official calculator is required.
    official_calculator_required = (

        bool(

            employee_portfolio[
                "official_calculator_required_flag"
            ]

            .fillna(
                False
            )

            .astype(
                bool
            )

            .any()
        )

        if (
            "official_calculator_required_flag"
            in employee_portfolio.columns
        )

        else True
    )


    # -------------------------------------------------------------------------
    # 09.10 - CREATE COMPANY KPI RECORD
    # -------------------------------------------------------------------------


    # Build the company-level dashboard record.
    company_kpis = pd.DataFrame([{


        "valuation_date":
            VALUATION_DATE.date(),


        "total_employee_records":
            total_employee_records,


        "active_employees":
            active_employees,


        "active_gratuity_members":
            gratuity_members,


        "active_db_pension_members":
            db_pension_members,


        "active_dc_superannuation_members":
            dc_members,


        "active_edli_members":
            edli_members,


        "active_gti_members":
            gti_members,


        "gratuity_dbo":
            gratuity_dbo,


        "gratuity_puc_one_service_year_pv":
            gratuity_puc,


        "db_pension_dbo":
            db_pension_dbo,


        "db_pension_puc_one_service_year_pv":
            db_pension_puc,


        "combined_db_liability":
            combined_db_liability,


        "combined_db_plan_assets":
            combined_db_assets,


        "combined_db_funding_ratio":
            combined_db_funding_ratio,


        "combined_db_funding_deficit":
            combined_db_funding_deficit,


        "combined_db_net_funded_position":
            combined_db_net_funded_position,


        "dc_current_annual_employer_contribution":
            dc_employer_contribution,


        "dc_current_annual_employee_contribution":
            dc_employee_contribution,


        "dc_projected_future_contribution_corpus":
            dc_future_corpus,


        "gti_total_sum_assured":
            total_gti_sum_assured,


        "gti_fresh_expected_claim_cost":
            total_gti_expected_claims,


        "gti_fresh_model_gross_premium":
            total_gti_fresh_gross_premium,


        "gti_underwriting_fcl_referrals":
            gti_fcl_referrals,


        "gti_underwriting_fcl_referral_rate":
            gti_fcl_referral_rate,


        "edli_part_b_lower_if_qualifying":
            edli_part_b_lower,


        "edli_part_b_upper_if_qualifying":
            edli_part_b_upper,


        "edli_official_calculator_required":
            official_calculator_required,


        "gti_historical_credibility_premium_used":
            False,


        "pipeline_10_version":
            P10_VERSION,
    }])


    # Return company KPI table.
    return company_kpis


# =============================================================================
# P10 SECTION 10 - PORTFOLIO RECONCILIATION TABLE
# =============================================================================


def build_portfolio_reconciliation(
    company_kpis,
):
    """
    Produce an explicit audit trail of the major portfolio totals.
    """

    # Extract the single company record.
    company = company_kpis.iloc[
        0
    ]


    # Build reconciliation rows.
    reconciliation = pd.DataFrame([


        {
            "metric":
                "Gratuity DBO",

            "amount":
                company[
                    "gratuity_dbo"
                ],

            "source_pipeline":
                "Pipeline 07",
        },


        {
            "metric":
                "DB Pension DBO",

            "amount":
                company[
                    "db_pension_dbo"
                ],

            "source_pipeline":
                "Pipeline 08",
        },


        {
            "metric":
                "Combined DB Liability",

            "amount":
                company[
                    "combined_db_liability"
                ],

            "source_pipeline":
                "Pipeline 10 reconciliation",
        },


        {
            "metric":
                "Combined DB Plan Assets",

            "amount":
                company[
                    "combined_db_plan_assets"
                ],

            "source_pipeline":
                "Validated plan assets",
        },


        {
            "metric":
                "Combined DB Net Funded Position",

            "amount":
                company[
                    "combined_db_net_funded_position"
                ],

            "source_pipeline":
                "Pipeline 10 reconciliation",
        },


        {
            "metric":
                "DC Future-Contribution Corpus",

            "amount":
                company[
                    "dc_projected_future_contribution_corpus"
                ],

            "source_pipeline":
                "Pipeline 08",
        },


        {
            "metric":
                "GTI Total Sum Assured",

            "amount":
                company[
                    "gti_total_sum_assured"
                ],

            "source_pipeline":
                "Pipeline 09",
        },


        {
            "metric":
                "GTI Fresh Expected Claims",

            "amount":
                company[
                    "gti_fresh_expected_claim_cost"
                ],

            "source_pipeline":
                "Pipeline 09",
        },


        {
            "metric":
                "GTI Fresh Gross Premium",

            "amount":
                company[
                    "gti_fresh_model_gross_premium"
                ],

            "source_pipeline":
                "Pipeline 10 controlled pricing basis",
        },
    ])


    # Store version.
    reconciliation[
        "pipeline_10_version"
    ] = P10_VERSION


    # Return audit table.
    return reconciliation


# =============================================================================
# P10 SECTION 11 - PORTFOLIO VALIDATION
# =============================================================================


def build_pipeline_10_validation(
    employee_portfolio,
    company_kpis,
    plan_summary,
    gratuity_employee,
    db_pension,
    dc_superannuation,
    gti,
    edli,
):
    """
    Validate integration and reconciliation.

    Reviews are handled separately in governance.

    This table contains true mathematical/data-structure failures.
    """

    # Store validation rows.
    rows = []


    # Define helper for one validation check.
    def add_check(
        check,
        exceptions,
        note="",
    ):


        # Convert exception count to integer.
        exception_count = int(
            exceptions
        )


        # Zero exceptions means PASS.
        status = (

            "PASS"

            if exception_count == 0

            else "FAIL"
        )


        # Store result.
        rows.append({


            "check":
                check,


            "exceptions":
                exception_count,


            "status":
                status,


            "note":
                note,
        })


    # -------------------------------------------------------------------------
    # 11.1 - SOURCE AVAILABILITY
    # -------------------------------------------------------------------------


    # Pipeline 07 output must exist.
    add_check(

        "Pipeline 07 Gratuity employee output available",

        int(
            gratuity_employee.empty
        ),
    )


    # Pipeline 08 DB output must exist.
    add_check(

        "Pipeline 08 DB Pension output available",

        int(
            db_pension.empty
        ),
    )


    # Pipeline 08 DC output must exist.
    add_check(

        "Pipeline 08 DC Superannuation output available",

        int(
            dc_superannuation.empty
        ),
    )


    # Pipeline 09 GTI output must exist.
    add_check(

        "Pipeline 09 GTI output available",

        int(
            gti.empty
        ),
    )


    # Pipeline 09 EDLI output must exist.
    add_check(

        "Pipeline 09 EDLI output available",

        int(
            edli.empty
        ),
    )


    # -------------------------------------------------------------------------
    # 11.2 - EMPLOYEE MATRIX
    # -------------------------------------------------------------------------


    # Employee matrix must be unique.
    add_check(

        "Portfolio employee matrix unique",

        employee_portfolio[
            "employee_id"
        ].duplicated().sum(),
    )


    # -------------------------------------------------------------------------
    # 11.3 - NEGATIVE LIABILITY CHECKS
    # -------------------------------------------------------------------------


    # Gratuity liability cannot be negative.
    add_check(

        "Gratuity DBO non-negative",

        (

            employee_portfolio[
                "gratuity_dbo"
            ]

            < -P10_TOLERANCE

        ).sum(),
    )


    # DB Pension liability cannot be negative.
    add_check(

        "DB Pension DBO non-negative",

        (

            employee_portfolio[
                "db_pension_liability"
            ]

            < -P10_TOLERANCE

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 11.4 - GTI VALIDATIONS
    # -------------------------------------------------------------------------


    # GTI Sum Assured cannot be negative.
    add_check(

        "GTI Sum Assured non-negative",

        (

            employee_portfolio[
                "gti_sum_assured"
            ]

            < -P10_TOLERANCE

        ).sum(),
    )


    # Fresh expected claims cannot be negative.
    add_check(

        "GTI fresh expected claims non-negative",

        (

            employee_portfolio[
                "gti_fresh_expected_claim_cost"
            ]

            < -P10_TOLERANCE

        ).sum(),
    )


    # Fresh gross premium cannot be lower than fresh expected claims
    # when the loading is non-negative.
    add_check(

        "GTI fresh gross premium >= fresh expected claims",

        (

            employee_portfolio[
                "gti_fresh_model_gross_premium"
            ]

            + P10_TOLERANCE

            < employee_portfolio[
                "gti_fresh_expected_claim_cost"
            ]

        ).sum(),
    )


    # -------------------------------------------------------------------------
    # 11.5 - COMBINED DB LIABILITY RECONCILIATION
    # -------------------------------------------------------------------------


    # Read company KPI row.
    company = company_kpis.iloc[
        0
    ]


    # Recalculate expected combined DB liability.
    expected_combined_liability = (

        company[
            "gratuity_dbo"
        ]

        + company[
            "db_pension_dbo"
        ]
    )


    # Check reconciliation.
    add_check(

        "Combined DB liability reconciles",

        int(

            abs(

                company[
                    "combined_db_liability"
                ]

                - expected_combined_liability
            )

            > max(

                1.0,

                abs(
                    expected_combined_liability
                )
            )

            * 1e-10
        ),
    )


    # -------------------------------------------------------------------------
    # 11.6 - COMBINED FUNDING POSITION RECONCILIATION
    # -------------------------------------------------------------------------


    # Continue when assets are available.
    if pd.notna(

        company[
            "combined_db_plan_assets"
        ]
    ):


        # Recalculate expected net funded position.
        expected_net_position = (

            company[
                "combined_db_plan_assets"
            ]

            - company[
                "combined_db_liability"
            ]
        )


        # Check net funded position.
        add_check(

            "Combined DB net funded position reconciles",

            int(

                abs(

                    company[
                        "combined_db_net_funded_position"
                    ]

                    - expected_net_position
                )

                > max(

                    1.0,

                    abs(
                        expected_net_position
                    )
                )

                * 1e-10
            ),
        )


        # Recalculate funding ratio.
        expected_funding_ratio = (

            company[
                "combined_db_plan_assets"
            ]

            / company[
                "combined_db_liability"
            ]
        )


        # Check funding ratio.
        add_check(

            "Combined DB funding ratio reconciles",

            int(

                abs(

                    company[
                        "combined_db_funding_ratio"
                    ]

                    - expected_funding_ratio
                )

                > 1e-10
            ),
        )


    # -------------------------------------------------------------------------
    # 11.7 - PLAN LIABILITY RECONCILIATION
    # -------------------------------------------------------------------------


    # Keep funded DB plan rows.
    db_plan_rows = plan_summary.loc[

        plan_summary[
            "product_type"
        ].isin([

            "Gratuity",

            "DB_Pension",
        ])

    ].copy()


    # Calculate plan liability.
    plan_db_liability = p10_sum(

        db_plan_rows[
            "actuarial_liability"
        ]

        if (
            not db_plan_rows.empty

            and "actuarial_liability"
            in db_plan_rows.columns
        )

        else None
    )


    # Compare plan liability with company liability.
    add_check(

        "Plan-level DB liabilities reconcile to company DB liability",

        int(

            pd.isna(
                plan_db_liability
            )

            or abs(

                plan_db_liability

                - company[
                    "combined_db_liability"
                ]
            )

            > max(

                1.0,

                abs(
                    company[
                        "combined_db_liability"
                    ]
                )
            )

            * 1e-10
        ),
    )


    # Return validation table.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# P10 SECTION 12 - CONSOLIDATE GOVERNANCE
# =============================================================================


def p10_extract_governance(
    source,
    source_pipeline,
):
    """
    Extract governance rows from an upstream pipeline result.
    """

    # Find a governance-shaped DataFrame.
    governance = p10_find_dataframe(

        source,

        required_all=[

            "governance_item",

            "review_rows",
        ],
    )


    # Return empty table when unavailable.
    if governance is None:

        return pd.DataFrame()


    # Work on a copy.
    governance = governance.copy()


    # Ensure treatment column exists.
    if "treatment" not in governance.columns:


        governance[
            "treatment"
        ] = ""


    # Keep only useful fields.
    governance = governance[[

        "governance_item",

        "review_rows",

        "treatment",

    ]].copy()


    # Add source pipeline.
    governance[
        "source_pipeline"
    ] = source_pipeline


    # Return table.
    return governance


# =============================================================================
# P10 SECTION 13 - BUILD PORTFOLIO GOVERNANCE REGISTER
# =============================================================================


def build_portfolio_governance(
    gratuity_results,
    superannuation_results,
    group_life_results,
    employee_portfolio,
):
    """
    Combine important upstream governance warnings and Pipeline 10 decisions.
    """

    # Create table container.
    governance_frames = []


    # Retrieve Pipeline 07 governance when available.
    p07_governance = p10_extract_governance(

        gratuity_results,

        "Pipeline 07"
    )


    # Add when found.
    if not p07_governance.empty:


        governance_frames.append(
            p07_governance
        )


    # Retrieve Pipeline 08 governance.
    p08_governance = p10_extract_governance(

        superannuation_results,

        "Pipeline 08"
    )


    # Add when available.
    if not p08_governance.empty:


        governance_frames.append(
            p08_governance
        )


    # Retrieve Pipeline 09 governance.
    p09_governance = p10_extract_governance(

        group_life_results,

        "Pipeline 09"
    )


    # Add when available.
    if not p09_governance.empty:


        governance_frames.append(
            p09_governance
        )


    # -------------------------------------------------------------------------
    # PIPELINE 10 OWN GOVERNANCE DECISIONS
    # -------------------------------------------------------------------------


    # Count GTI plans.
    gti_plan_count = (

        int(

            employee_portfolio[
                "gti_pricing_plan_id"
            ].dropna().nunique()
        )

        if (
            "gti_pricing_plan_id"
            in employee_portfolio.columns
        )

        else 0
    )


    # Add the explicit GTI credibility exclusion.
    p10_governance = pd.DataFrame([


        {
            "governance_item":
                (
                    "GTI historical A/E credibility premium "
                    "excluded from final portfolio KPI"
                ),

            "review_rows":
                gti_plan_count,

            "treatment":
                (
                    "Historical claims file does not represent a complete "
                    "insured-member exposure denominator. Final dashboard "
                    "premium therefore uses fresh expected claims divided "
                    "by one minus the governed loading rate."
                ),

            "source_pipeline":
                "Pipeline 10",
        },
    ])


    # Add Pipeline 10 governance decision.
    governance_frames.append(
        p10_governance
    )


    # Return Pipeline 10 row if no other governance existed.
    if len(
        governance_frames
    ) == 1:

        governance = governance_frames[
            0
        ].copy()


    # Otherwise combine all governance sources.
    else:


        governance = pd.concat(

            governance_frames,

            ignore_index=True,

            sort=False
        )


    # Convert review count to numeric.
    governance[
        "review_rows"
    ] = pd.to_numeric(

        governance[
            "review_rows"
        ],

        errors="coerce"
    ).fillna(
        0
    ).astype(
        int
    )


    # Store version.
    governance[
        "pipeline_10_version"
    ] = P10_VERSION


    # Return consolidated governance register.
    return governance


# =============================================================================
# P10 SECTION 14 - MAIN PIPELINE 10 CONTROLLER
# =============================================================================


def run_pipeline_10(
    feature_results,
    gratuity_results=None,
    superannuation_results=None,
    group_life_results=None,
):
    """
    Run the Integrated Employee Benefits Portfolio,
    Funding and Risk Engine.
    """

    # Print opening separator.
    print(
        "\n"
        + "=" * 76
    )


    # Print title.
    print(
        "PIPELINE 10 - "
        "INTEGRATED EMPLOYEE BENEFITS PORTFOLIO / FUNDING / RISK"
    )


    # Print valuation date.
    print(
        f"Valuation date: "
        f"{VALUATION_DATE.date()}"
    )


    # Print Pipeline version.
    print(
        f"Portfolio engine version: "
        f"{P10_VERSION}"
    )


    # Print closing separator.
    print(
        "=" * 76
    )


    # -------------------------------------------------------------------------
    # STEP 14.1 - RETRIEVE EMPLOYEE FEATURES
    # -------------------------------------------------------------------------


    # Pipeline 04 employee features are the portfolio master.
    employee_features = feature_results[

        "employee_features"

    ].copy()


    # -------------------------------------------------------------------------
    # STEP 14.2 - RETRIEVE GRATUITY OUTPUT
    # -------------------------------------------------------------------------


    # Retrieve Pipeline 07 employee-level liability.
    (
        gratuity_employee,
        gratuity_source_path,

    ) = p10_get_gratuity_output(

        gratuity_results
    )


    # -------------------------------------------------------------------------
    # STEP 14.3 - RETRIEVE SUPERANNUATION OUTPUTS
    # -------------------------------------------------------------------------


    # Retrieve DB Pension and DC Superannuation.
    (
        db_pension,
        dc_superannuation,

    ) = p10_get_superannuation_outputs(

        superannuation_results
    )


    # -------------------------------------------------------------------------
    # STEP 14.4 - RETRIEVE GROUP-LIFE OUTPUTS
    # -------------------------------------------------------------------------


    # Retrieve GTI and EDLI.
    (
        gti,
        edli,

    ) = p10_get_group_life_outputs(

        group_life_results
    )


    # -------------------------------------------------------------------------
    # STEP 14.5 - RETRIEVE PLAN ASSETS
    # -------------------------------------------------------------------------


    # Load latest plan assets.
    latest_plan_assets = p10_latest_plan_assets()


    # -------------------------------------------------------------------------
    # STEP 14.6 - BUILD EMPLOYEE RISK MATRIX
    # -------------------------------------------------------------------------


    # Integrate every employee-benefit engine.
    employee_portfolio = build_portfolio_employee_risk_matrix(

        employee_features,

        gratuity_employee,

        db_pension,

        dc_superannuation,

        gti,

        edli,
    )


    # -------------------------------------------------------------------------
    # STEP 14.7 - BUILD PLAN SUMMARY
    # -------------------------------------------------------------------------


    # Aggregate employees into individual benefit plans.
    plan_summary = build_portfolio_plan_summary(

        employee_portfolio,

        latest_plan_assets
    )


    # -------------------------------------------------------------------------
    # STEP 14.8 - BUILD PRODUCT SUMMARY
    # -------------------------------------------------------------------------


    # Aggregate plans into products.
    product_summary = build_portfolio_product_summary(

        plan_summary
    )


    # -------------------------------------------------------------------------
    # STEP 14.9 - BUILD COMPANY KPI TABLE
    # -------------------------------------------------------------------------


    # Create company-level benefit portfolio.
    company_kpis = build_portfolio_company_kpis(

        employee_portfolio,

        product_summary
    )


    # -------------------------------------------------------------------------
    # STEP 14.10 - BUILD SEGMENT CONCENTRATION
    # -------------------------------------------------------------------------


    # Aggregate risk by department, location and grade.
    segment_summary = build_portfolio_segment_summary(

        employee_portfolio
    )


    # -------------------------------------------------------------------------
    # STEP 14.11 - BUILD RECONCILIATION TABLE
    # -------------------------------------------------------------------------


    # Create explicit audit trail.
    reconciliation = build_portfolio_reconciliation(

        company_kpis
    )


    # -------------------------------------------------------------------------
    # STEP 14.12 - VALIDATION
    # -------------------------------------------------------------------------


    # Run portfolio validation.
    validation = build_pipeline_10_validation(

        employee_portfolio,

        company_kpis,

        plan_summary,

        gratuity_employee,

        db_pension,

        dc_superannuation,

        gti,

        edli,
    )


    # Count actual validation failures.
    validation_failures = int(

        validation[
            "status"
        ].eq(
            "FAIL"
        ).sum()
    )


    # -------------------------------------------------------------------------
    # STEP 14.13 - GOVERNANCE
    # -------------------------------------------------------------------------


    # Consolidate governance warnings.
    governance = build_portfolio_governance(

        gratuity_results,

        superannuation_results,

        group_life_results,

        employee_portfolio,
    )


    # Count governance categories with review items.
    governance_reviews = int(

        (

            governance[
                "review_rows"
            ]

            > 0

        ).sum()
    )


    # Store validation status in company KPI table.
    company_kpis[
        "validation_failures"
    ] = validation_failures


    # Store governance category count.
    company_kpis[
        "governance_review_categories"
    ] = governance_reviews


    # -------------------------------------------------------------------------
    # STEP 14.14 - SAVE DASHBOARD-READY MODEL TABLES
    # -------------------------------------------------------------------------


    # Save company-level KPIs.
    company_kpis.to_csv(

        MODEL_READY_DATA_DIR
        / "portfolio_company_kpis.csv",

        index=False
    )


    # Save product-level portfolio.
    product_summary.to_csv(

        MODEL_READY_DATA_DIR
        / "portfolio_product_summary.csv",

        index=False
    )


    # Save plan-level portfolio.
    plan_summary.to_csv(

        MODEL_READY_DATA_DIR
        / "portfolio_plan_summary.csv",

        index=False
    )


    # Save employee-level cross-product risk matrix.
    employee_portfolio.to_csv(

        MODEL_READY_DATA_DIR
        / "portfolio_employee_risk_matrix.csv",

        index=False
    )


    # Save segment concentration table.
    segment_summary.to_csv(

        MODEL_READY_DATA_DIR
        / "portfolio_segment_summary.csv",

        index=False
    )


    # -------------------------------------------------------------------------
    # STEP 14.15 - SAVE PIPELINE 10 REPORTS
    # -------------------------------------------------------------------------


    # Save validation.
    validation.to_csv(

        P10_OUTPUT_DIR
        / "portfolio_validation.csv",

        index=False
    )


    # Save governance.
    governance.to_csv(

        P10_OUTPUT_DIR
        / "portfolio_governance_summary.csv",

        index=False
    )


    # Save reconciliation.
    reconciliation.to_csv(

        P10_OUTPUT_DIR
        / "portfolio_reconciliation.csv",

        index=False
    )


    # -------------------------------------------------------------------------
    # STEP 14.16 - TERMINAL SUMMARY
    # -------------------------------------------------------------------------


    # Read the single company KPI record.
    company = company_kpis.iloc[
        0
    ]


    # Print population section.
    print(
        "\nEmployee Benefit Portfolio"
    )


    # Total employees.
    print(

        f"  Employee records:                    "
        f"{int(company['total_employee_records']):,}"
    )


    # Active employees.
    print(

        f"  Active employees:                    "
        f"{int(company['active_employees']):,}"
    )


    # Gratuity membership.
    print(

        f"  Active Gratuity members:             "
        f"{int(company['active_gratuity_members']):,}"
    )


    # DB Pension membership.
    print(

        f"  Active DB Pension members:           "
        f"{int(company['active_db_pension_members']):,}"
    )


    # DC membership.
    print(

        f"  Active DC Superannuation members:    "
        f"{int(company['active_dc_superannuation_members']):,}"
    )


    # EDLI membership.
    print(

        f"  Active EDLI members:                 "
        f"{int(company['active_edli_members']):,}"
    )


    # GTI membership.
    print(

        f"  Active GTI members:                  "
        f"{int(company['active_gti_members']):,}"
    )


    # -------------------------------------------------------------------------
    # PRINT DEFINED BENEFIT FUNDING
    # -------------------------------------------------------------------------


    print(
        "\nDefined Benefit Liability and Funding"
    )


    # Gratuity DBO.
    print(

        f"  Gratuity DBO:                        "
        f"INR {company['gratuity_dbo']:,.2f}"
    )


    # DB Pension DBO.
    print(

        f"  DB Pension DBO:                      "
        f"INR {company['db_pension_dbo']:,.2f}"
    )


    # Combined liability.
    print(

        f"  Combined DB liability:               "
        f"INR {company['combined_db_liability']:,.2f}"
    )


    # Combined assets.
    print(

        f"  Combined DB plan assets:             "
        f"INR {company['combined_db_plan_assets']:,.2f}"
    )


    # Funding ratio.
    print(

        f"  Combined DB funding ratio:           "
        f"{company['combined_db_funding_ratio']:.2%}"
    )


    # Net funded position.
    print(

        f"  Combined DB net funded position:     "
        f"INR {company['combined_db_net_funded_position']:,.2f}"
    )


    # -------------------------------------------------------------------------
    # PRINT DC
    # -------------------------------------------------------------------------


    print(
        "\nDefined Contribution Superannuation"
    )


    # Employer contribution.
    print(

        f"  Annual employer contributions:       "
        f"INR {company['dc_current_annual_employer_contribution']:,.2f}"
    )


    # Employee contribution.
    print(

        f"  Annual employee contributions:       "
        f"INR {company['dc_current_annual_employee_contribution']:,.2f}"
    )


    # Future-contribution corpus.
    print(

        f"  Future-contribution corpus:          "
        f"INR {company['dc_projected_future_contribution_corpus']:,.2f}"
    )


    # -------------------------------------------------------------------------
    # PRINT GTI
    # -------------------------------------------------------------------------


    print(
        "\nGroup Term Insurance"
    )


    # Total Sum Assured.
    print(

        f"  Total Sum Assured:                   "
        f"INR {company['gti_total_sum_assured']:,.2f}"
    )


    # Fresh expected claims.
    print(

        f"  Fresh expected claims:               "
        f"INR {company['gti_fresh_expected_claim_cost']:,.2f}"
    )


    # Fresh gross premium.
    print(

        f"  Fresh-model gross premium:           "
        f"INR {company['gti_fresh_model_gross_premium']:,.2f}"
    )


    # Underwriting referrals.
    print(

        f"  FCL underwriting referrals:          "
        f"{int(company['gti_underwriting_fcl_referrals']):,}"
    )


    # Referral percentage.
    print(

        f"  FCL referral rate:                   "
        f"{company['gti_underwriting_fcl_referral_rate']:.2%}"
    )


    # State explicitly that distorted A/E pricing was excluded.
    print(

        "  Historical A/E premium used in KPI:  "
        "NO"
    )


    # -------------------------------------------------------------------------
    # PRINT EDLI
    # -------------------------------------------------------------------------


    print(
        "\nEmployees' Deposit Linked Insurance"
    )


    # Lower illustrative range.
    print(

        f"  Aggregate qualifying Part B lower:   "
        f"INR {company['edli_part_b_lower_if_qualifying']:,.2f}"
    )


    # Upper illustrative range.
    print(

        f"  Aggregate qualifying Part B upper:   "
        f"INR {company['edli_part_b_upper_if_qualifying']:,.2f}"
    )


    # Official calculator requirement.
    print(

        "  Official calculator required:        "
        f"{company['edli_official_calculator_required']}"
    )


    # -------------------------------------------------------------------------
    # PRINT QUALITY CONTROLS
    # -------------------------------------------------------------------------


    print(

        f"\nPipeline 10 validation failures:        "
        f"{validation_failures}"
    )


    print(

        f"Pipeline 10 governance review categories: "
        f"{governance_reviews}"
    )


