# =============================================================================
# P11 HELPER 01 - SAFE NUMERIC CONVERSION
# =============================================================================


def p11_numeric(
    value,
):
    """
    Convert a scalar value safely into numeric form.
    """

    # Convert through a temporary pandas Series.
    numeric_value = pd.to_numeric(
        pd.Series([value]),
        errors="coerce",
    ).iloc[0]


    # Return converted value.
    return numeric_value


# =============================================================================
# P11 HELPER 02 - SAFE DIVISION
# =============================================================================


def p11_safe_divide(
    numerator,
    denominator,
):
    """
    Divide two numbers only when the denominator is valid and non-zero.
    """

    # Convert numerator.
    numerator = p11_numeric(
        numerator
    )


    # Convert denominator.
    denominator = p11_numeric(
        denominator
    )


    # Return missing when either input is unavailable.
    if (
        pd.isna(numerator)
        or pd.isna(denominator)
        or denominator == 0
    ):

        return np.nan


    # Perform valid division.
    return float(
        numerator / denominator
    )


# =============================================================================
# P11 HELPER 03 - LOAD PIPELINE 10 TABLE
# =============================================================================


def p11_get_table(
    portfolio_results,
    result_key,
    fallback_path,
    required=True,
):
    """
    Retrieve a Pipeline 10 table.

    Priority:

        1. In-memory Pipeline 10 result
        2. Saved Pipeline 10 CSV

    This makes Pipeline 11 reproducible even when the Python process
    is restarted later.
    """

    # -------------------------------------------------------------------------
    # TRY IN-MEMORY PIPELINE 10 RESULT
    # -------------------------------------------------------------------------


    # Confirm Pipeline 10 result dictionary exists.
    if isinstance(
        portfolio_results,
        dict,
    ):


        # Check whether the required result key exists.
        if result_key in portfolio_results:


            # Retrieve object.
            candidate = portfolio_results[
                result_key
            ]


            # Accept only pandas DataFrames.
            if isinstance(
                candidate,
                pd.DataFrame,
            ):


                # Return a defensive copy.
                return (
                    candidate.copy(),
                    "IN_MEMORY_PIPELINE_10",
                )


    # -------------------------------------------------------------------------
    # TRY SAVED CSV
    # -------------------------------------------------------------------------


    # Check whether fallback CSV exists.
    if fallback_path.exists():


        # Load saved output.
        dataframe = pd.read_csv(
            fallback_path
        )


        # Return data and source path.
        return (
            dataframe,
            str(fallback_path),
        )


    # -------------------------------------------------------------------------
    # HANDLE MISSING TABLE
    # -------------------------------------------------------------------------


    # Required data must exist.
    if required:

        raise FileNotFoundError(

            "Pipeline 11 could not retrieve required Pipeline 10 output: "
            f"{result_key}"
        )


    # Optional outputs may return an empty table.
    return (
        pd.DataFrame(),
        "NOT_AVAILABLE",
    )


