def build_dashboard_product_overview(
    product_summary,
):
    """
    Prepare one dashboard row per benefit product.
    """

    # Copy Pipeline 10 product summary.
    result = product_summary.copy()


    # Define preferred product display order.
    product_order = {

        "Gratuity":
            10,

        "DB_Pension":
            20,

        "DC_Superannuation":
            30,

        "EDLI":
            40,

        "GTI":
            50,
    }


    # Attach display order.
    result[
        "display_order"
    ] = result[
        "product_type"
    ].map(
        product_order
    ).fillna(
        999
    )


    # Convert funding ratio into percentage-point form
    # for direct dashboard plotting.
    if "funding_ratio" in result.columns:


        result[
            "funding_ratio_pct"
        ] = (

            pd.to_numeric(

                result[
                    "funding_ratio"
                ],

                errors="coerce"
            )

            * 100.0
        )


    else:


        result[
            "funding_ratio_pct"
        ] = np.nan


    # Store version.
    result[
        "pipeline_11_version"
    ] = P11_VERSION


    # Sort products.
    result = result.sort_values(

        [
            "display_order",
            "product_type",
        ]

    ).reset_index(
        drop=True
    )


    # Return product view.
    return result


# =============================================================================
# P11 SECTION 04 - PLAN OVERVIEW DATASET
# =============================================================================


def build_dashboard_plan_overview(
    plan_summary,
):
    """
    Prepare one dashboard row per benefit plan.

    The output supports:
        - DB funding charts
        - GTI plan comparison
        - DC plan comparison
        - EDLI statutory plan display
    """

    # Copy source.
    result = plan_summary.copy()


    # -------------------------------------------------------------------------
    # FUNDING RATIO PERCENTAGE
    # -------------------------------------------------------------------------


    # Convert funding ratio to percentage points.
    if "funding_ratio" in result.columns:


        result[
            "funding_ratio_pct"
        ] = (

            pd.to_numeric(

                result[
                    "funding_ratio"
                ],

                errors="coerce"
            )

            * 100.0
        )


    else:


        result[
            "funding_ratio_pct"
        ] = np.nan


    # -------------------------------------------------------------------------
    # DB FUNDING GAP
    # -------------------------------------------------------------------------


    # Absolute DB shortfall amount.
    if (
        "actuarial_liability" in result.columns
        and "plan_assets" in result.columns
    ):


        result[
            "funding_gap"
        ] = (

            pd.to_numeric(

                result[
                    "actuarial_liability"
                ],

                errors="coerce"
            )

            - pd.to_numeric(

                result[
                    "plan_assets"
                ],

                errors="coerce"
            )
        )


    else:


        result[
            "funding_gap"
        ] = np.nan


    # -------------------------------------------------------------------------
    # GTI FCL REFERRAL RATE
    # -------------------------------------------------------------------------


    # Create GTI referral rate where relevant.
    if (
        "underwriting_referrals" in result.columns
        and "active_members" in result.columns
    ):


        result[
            "gti_fcl_referral_rate"
        ] = np.where(

            pd.to_numeric(

                result[
                    "active_members"
                ],

                errors="coerce"
            ) > 0,

            pd.to_numeric(

                result[
                    "underwriting_referrals"
                ],

                errors="coerce"
            )

            / pd.to_numeric(

                result[
                    "active_members"
                ],

                errors="coerce"
            ),

            np.nan
        )


    else:


        result[
            "gti_fcl_referral_rate"
        ] = np.nan


    # -------------------------------------------------------------------------
    # GTI PREMIUM RATE PER INR 1,000 COVER
    # -------------------------------------------------------------------------


    # Calculate fresh premium rate per INR 1,000 Sum Assured.
    if (
        "fresh_model_gross_premium" in result.columns
        and "total_sum_assured" in result.columns
    ):


        result[
            "gti_fresh_premium_rate_per_1000"
        ] = np.where(

            pd.to_numeric(

                result[
                    "total_sum_assured"
                ],

                errors="coerce"
            ) > 0,

            pd.to_numeric(

                result[
                    "fresh_model_gross_premium"
                ],

                errors="coerce"
            )

            / pd.to_numeric(

                result[
                    "total_sum_assured"
                ],

                errors="coerce"
            )

            * 1000.0,

            np.nan
        )


    else:


        result[
            "gti_fresh_premium_rate_per_1000"
        ] = np.nan


    # Identify funded DB products objectively.
    result[
        "funded_db_product_flag"
    ] = result[

        "product_type"

    ].isin([

        "Gratuity",

        "DB_Pension",
    ])


    # Store version.
    result[
        "pipeline_11_version"
    ] = P11_VERSION


    # Return plan view.
    return result


# =============================================================================
# P11 SECTION 05 - DASHBOARD EMPLOYEE DETAIL
# =============================================================================


def build_dashboard_employee_detail(
    employee_risk_matrix,
):
    """
    Create a compact employee-level drill-down table.

    This table supports dashboard filters and employee drill-down,
    while avoiding unnecessary internal calculation fields.
    """

    # Define preferred dashboard fields.
    preferred_columns = [

        # -------------------------------------------------------------
        # EMPLOYEE / ORGANISATION
        # -------------------------------------------------------------

        "employee_id",

        "employment_status",

        "department",

        "location",

        "grade",

        "attained_age_years",

        "completed_service_years",


        # -------------------------------------------------------------
        # PLAN IDENTIFIERS
        # -------------------------------------------------------------

        "gratuity_plan_id",

        "db_pension_plan_id",

        "dc_superannuation_plan_id",

        "gti_pricing_plan_id",

        "edli_plan_id",


        # -------------------------------------------------------------
        # DEFINED BENEFIT
        # -------------------------------------------------------------

        "gratuity_dbo",

        "db_pension_liability",

        "combined_db_liability",


        # -------------------------------------------------------------
        # DEFINED CONTRIBUTION
        # -------------------------------------------------------------

        "current_annual_employer_contribution",

        "current_annual_employee_contribution",

        "projected_future_contribution_corpus",


        # -------------------------------------------------------------
        # GTI
        # -------------------------------------------------------------

        "gti_sum_assured",

        "gti_q_death_1y",

        "gti_fresh_expected_claim_cost",

        "gti_fresh_model_gross_premium",

        "gti_underwriting_referral_flag",

        "gti_cover_above_free_cover_limit",

        "gti_free_cover_limit",


        # -------------------------------------------------------------
        # EDLI
        # -------------------------------------------------------------

        "edli_capped_monthly_wage",

        "edli_part_b_lower_if_qualifying",

        "edli_part_b_upper_if_qualifying",

        "official_calculator_required_flag",

        "edli_model_status",
    ]


    # Keep only fields that actually exist.
    available_columns = [

        column

        for column in preferred_columns

        if column
        in employee_risk_matrix.columns
    ]


    # Employee ID is mandatory.
    if "employee_id" not in available_columns:

        raise KeyError(

            "Pipeline 11 requires employee_id "
            "in the Pipeline 10 employee risk matrix."
        )


    # Create employee detail dataset.
    result = employee_risk_matrix[

        available_columns

    ].copy()


    # Add version.
    result[
        "pipeline_11_version"
    ] = P11_VERSION


    # Sort employee IDs for stable dashboard behaviour.
    result = result.sort_values(
        "employee_id"
    ).reset_index(
        drop=True
    )


    # Return employee detail.
    return result


# =============================================================================
# P11 SECTION 06 - SEGMENT CONCENTRATION DATASET
# =============================================================================


def build_dashboard_segment_risk(
    segment_summary,
):
    """
    Prepare department, location and grade concentration analytics.

    Shares and rankings are calculated separately inside each
    segmentation dimension.
    """

    # Copy source.
    result = segment_summary.copy()


    # Define additive portfolio risk metrics.
    risk_metrics = [

        "combined_db_liability",

        "projected_future_contribution_corpus",

        "gti_sum_assured",

        "gti_fresh_expected_claim_cost",

        "gti_fresh_model_gross_premium",

        "gti_cover_above_free_cover_limit",
    ]


    # -------------------------------------------------------------------------
    # CALCULATE WITHIN-DIMENSION SHARES
    # -------------------------------------------------------------------------


    # Process each risk metric separately.
    for metric in risk_metrics:


        # Skip metrics absent from the source.
        if metric not in result.columns:

            continue


        # Convert metric to numeric.
        result[
            metric
        ] = pd.to_numeric(

            result[
                metric
            ],

            errors="coerce"
        )


        # Calculate total exposure independently for:
        #
        #     department
        #     location
        #     grade
        dimension_total = result.groupby(

            "segment_type"

        )[

            metric

        ].transform(
            "sum"
        )


        # Create share field.
        share_column = (
            f"{metric}_share"
        )


        # Calculate proportional contribution.
        result[
            share_column
        ] = np.where(

            dimension_total > 0,

            result[
                metric
            ]

            / dimension_total,

            np.nan
        )


    # -------------------------------------------------------------------------
    # RANK DEFINED BENEFIT LIABILITY
    # -------------------------------------------------------------------------


    if "combined_db_liability" in result.columns:


        result[
            "db_liability_rank"
        ] = result.groupby(

            "segment_type"

        )[

            "combined_db_liability"

        ].rank(

            method="dense",

            ascending=False
        )


    # -------------------------------------------------------------------------
    # RANK GTI SUM ASSURED
    # -------------------------------------------------------------------------


    if "gti_sum_assured" in result.columns:


        result[
            "gti_sum_assured_rank"
        ] = result.groupby(

            "segment_type"

        )[

            "gti_sum_assured"

        ].rank(

            method="dense",

            ascending=False
        )


    # -------------------------------------------------------------------------
    # RANK DC FUTURE CORPUS
    # -------------------------------------------------------------------------


    if (
        "projected_future_contribution_corpus"
        in result.columns
    ):


        result[
            "dc_future_corpus_rank"
        ] = result.groupby(

            "segment_type"

        )[

            "projected_future_contribution_corpus"

        ].rank(

            method="dense",

            ascending=False
        )


    # Store version.
    result[
        "pipeline_11_version"
    ] = P11_VERSION


    # Sort consistently.
    result = result.sort_values(

        [
            "segment_type",
            "segment_value",
        ]

    ).reset_index(
        drop=True
    )


    # Return segment-risk mart.
    return result


# =============================================================================
# P11 SECTION 07 - GOVERNANCE DASHBOARD DATASET
# =============================================================================


def build_dashboard_governance(
    governance,
):
    """
    Prepare governance issues for dashboard display.
    """

    # Copy governance register.
    result = governance.copy()


    # Convert review rows into numeric form.
    result[
        "review_rows"
    ] = pd.to_numeric(

        result[
            "review_rows"
        ],

        errors="coerce"
    ).fillna(
        0
    ).astype(
        int
    )


    # Objective status:
    #
    # review_rows > 0 -> REVIEW
    # otherwise       -> OK
    result[
        "dashboard_status"
    ] = np.where(

        result[
            "review_rows"
        ] > 0,

        "REVIEW",

        "OK"
    )


    # Indicate whether the row should appear in the dashboard alert panel.
    result[
        "display_alert_flag"
    ] = (

        result[
            "review_rows"
        ]

        > 0
    )


    # Store version.
    result[
        "pipeline_11_version"
    ] = P11_VERSION


    # Sort non-zero review items first.
    result = result.sort_values(

        [
            "display_alert_flag",
            "review_rows",
        ],

        ascending=[

            False,

            False,
        ]

    ).reset_index(
        drop=True
    )


    # Return governance view.
    return result


# =============================================================================
# P11 SECTION 08 - VALIDATION DASHBOARD DATASET
# =============================================================================


def build_dashboard_validation(
    validation,
):
    """
    Prepare Pipeline 10 validation checks for dashboard display.
    """

    # Copy source.
    result = validation.copy()


    # Standardise status text.
    result[
        "status"
    ] = result[
        "status"
    ].astype(
        str
    ).str.upper()


    # Create a simple dashboard failure flag.
    result[
        "failure_flag"
    ] = result[
        "status"
    ].eq(
        "FAIL"
    )


    # Store version.
    result[
        "pipeline_11_version"
    ] = P11_VERSION


    # Put failures first if they ever occur.
    result = result.sort_values(

        "failure_flag",

        ascending=False

    ).reset_index(
        drop=True
    )


    # Return validation dataset.
    return result


# =============================================================================
# P11 SECTION 09 - DASHBOARD FILTER CATALOGUE
# =============================================================================


def build_dashboard_filters(
    employee_detail,
):
    """
    Create a controlled list of filter values available to Streamlit.

    The Streamlit application will not need to repeatedly derive
    these distinct values from the full employee matrix.
    """

    # Define dashboard dimensions.
    filter_columns = [

        "department",

        "location",

        "grade",

        "gratuity_plan_id",

        "db_pension_plan_id",

        "dc_superannuation_plan_id",

        "gti_pricing_plan_id",

        "edli_plan_id",
    ]


    # Store filter tables.
    filter_frames = []


    # Process each available dimension.
    for column in filter_columns:


        # Skip unavailable fields.
        if column not in employee_detail.columns:

            continue


        # Extract unique non-missing values.
        values = (

            employee_detail[
                column
            ]

            .dropna()

            .astype(
                str
            )

            .drop_duplicates()

            .sort_values()
        )


        # Build long-form filter table.
        filter_table = pd.DataFrame({

            "filter_name":
                column,

            "filter_value":
                values.values,
        })


        # Add to collection.
        filter_frames.append(
            filter_table
        )


    # Return empty table if no filter dimensions exist.
    if len(
        filter_frames
    ) == 0:


        return pd.DataFrame(

            columns=[

                "filter_name",

                "filter_value",

                "pipeline_11_version",
            ]
        )


    # Combine all filter values.
    result = pd.concat(

        filter_frames,

        ignore_index=True
    )


    # Store version.
    result[
        "pipeline_11_version"
    ] = P11_VERSION


    # Return filter catalogue.
    return result


