# =============================================================================
# P11 SECTION 11 - DASHBOARD MANIFEST
# =============================================================================


def build_dashboard_manifest(
    dashboard_tables,
):
    """
    Create one auditable record per dashboard dataset.
    """

    # Define dataset descriptions.
    descriptions = {

        "dashboard_kpi_cards.csv":
            "Executive KPI cards; one row per dashboard KPI.",

        "dashboard_product_overview.csv":
            "Product-level employee-benefits portfolio summary.",

        "dashboard_plan_overview.csv":
            "Plan-level funding, contribution and risk summary.",

        "dashboard_employee_detail.csv":
            "Employee-level dashboard drill-down dataset.",

        "dashboard_segment_risk.csv":
            "Department, location and grade concentration analytics.",

        "dashboard_governance.csv":
            "Consolidated model-governance register.",

        "dashboard_validation.csv":
            "Portfolio mathematical and structural validation checks.",

        "dashboard_filters.csv":
            "Controlled dashboard filter values.",

        "dashboard_visual_catalog.csv":
            "Approved Streamlit visualization architecture.",
    }


    # Create manifest rows.
    rows = []


    # Process every dashboard dataset.
    for (
        file_name,
        dataframe,

    ) in dashboard_tables.items():


        # Store dataset information.
        rows.append({

            "file_name":
                file_name,

            "row_count":
                len(
                    dataframe
                ),

            "column_count":
                len(
                    dataframe.columns
                ),

            "purpose":
                descriptions.get(
                    file_name,
                    ""
                ),

            "valuation_date":
                VALUATION_DATE.date(),

            "pipeline_11_version":
                P11_VERSION,
        })


    # Return manifest.
    return pd.DataFrame(
        rows
    )


# =============================================================================
# P11 SECTION 12 - PIPELINE 11 VALIDATION
# =============================================================================


def build_pipeline_11_validation(
    company_kpis,
    kpi_cards,
    product_overview,
    plan_overview,
    employee_detail,
    segment_risk,
    dashboard_governance,
    dashboard_validation,
):
    """
    Validate that the data mart faithfully reproduces Pipeline 10.

    No actuarial formulas are revalidated here.
    """

    # Store validation records.
    rows = []


    # Define reusable validation writer.
    def add_check(
        check,
        exceptions,
        note="",
    ):


        # Convert exception count.
        exception_count = int(
            exceptions
        )


        # Zero exceptions means PASS.
        status = (

            "PASS"

            if exception_count == 0

            else "FAIL"
        )


        # Store row.
        rows.append({

            "check":
                check,

            "exceptions":
                exception_count,

            "status":
                status,

            "note":
                note,
        })


    # -------------------------------------------------------------------------
    # 12.1 - COMPANY KPI GRAIN
    # -------------------------------------------------------------------------


    add_check(

        "Company KPI table contains exactly one row",

        int(
            len(company_kpis) != 1
        ),
    )


    # -------------------------------------------------------------------------
    # 12.2 - KPI CARD UNIQUENESS
    # -------------------------------------------------------------------------


    add_check(

        "Dashboard KPI IDs unique",

        kpi_cards[
            "kpi_id"
        ].duplicated().sum(),
    )


    # -------------------------------------------------------------------------
    # 12.3 - EMPLOYEE UNIQUENESS
    # -------------------------------------------------------------------------


    add_check(

        "Dashboard employee detail unique",

        employee_detail[
            "employee_id"
        ].duplicated().sum(),
    )


    # -------------------------------------------------------------------------
    # 12.4 - PLAN UNIQUENESS
    # -------------------------------------------------------------------------


    add_check(

        "Dashboard product-plan combinations unique",

        plan_overview[

            [
                "product_type",
                "plan_id",
            ]

        ].duplicated().sum(),
    )


    # -------------------------------------------------------------------------
    # 12.5 - SEGMENT UNIQUENESS
    # -------------------------------------------------------------------------


    if not segment_risk.empty:


        add_check(

            "Dashboard segment combinations unique",

            segment_risk[

                [
                    "segment_type",
                    "segment_value",
                ]

            ].duplicated().sum(),
        )


    # -------------------------------------------------------------------------
    # 12.6 - PIPELINE 10 VALIDATION STATUS
    # -------------------------------------------------------------------------


    upstream_failures = int(

        dashboard_validation[
            "status"
        ].eq(
            "FAIL"
        ).sum()
    )


    add_check(

        "Pipeline 10 validation contains no failures",

        upstream_failures,
    )


    # -------------------------------------------------------------------------
    # 12.7 - COMPANY DB LIABILITY RECONCILIATION
    # -------------------------------------------------------------------------


    company = company_kpis.iloc[
        0
    ]


    # Calculate dashboard product DB liability.
    db_products = product_overview.loc[

        product_overview[
            "product_type"
        ].isin([

            "Gratuity",

            "DB_Pension",
        ])

    ].copy()


    # Sum product liabilities.
    dashboard_db_liability = pd.to_numeric(

        db_products[
            "actuarial_liability"
        ],

        errors="coerce"

    ).sum()


    # Read company liability.
    company_db_liability = p11_numeric(

        company[
            "combined_db_liability"
        ]
    )


    # Compare.
    add_check(

        "Dashboard product DB liability reconciles to company KPI",

        int(

            abs(

                dashboard_db_liability
                - company_db_liability

            )

            > max(

                1.0,

                abs(
                    company_db_liability
                )
            )

            * 1e-10
        ),
    )


    # -------------------------------------------------------------------------
    # 12.8 - GTI PREMIUM RECONCILIATION
    # -------------------------------------------------------------------------


    # Keep GTI plan rows.
    gti_plans = plan_overview.loc[

        plan_overview[
            "product_type"
        ].eq(
            "GTI"
        )

    ].copy()


    # Sum dashboard GTI fresh premiums.
    dashboard_gti_premium = pd.to_numeric(

        gti_plans[
            "fresh_model_gross_premium"
        ],

        errors="coerce"

    ).sum()


    # Read company GTI fresh premium.
    company_gti_premium = p11_numeric(

        company[
            "gti_fresh_model_gross_premium"
        ]
    )


    # Compare.
    add_check(

        "Dashboard GTI fresh premium reconciles to company KPI",

        int(

            abs(

                dashboard_gti_premium
                - company_gti_premium

            )

            > max(

                1.0,

                abs(
                    company_gti_premium
                )
            )

            * 1e-10
        ),
    )


    # -------------------------------------------------------------------------
    # 12.9 - GOVERNANCE REGISTER PRESERVED
    # -------------------------------------------------------------------------


    add_check(

        "Dashboard governance register available",

        int(
            dashboard_governance.empty
        ),
    )


    # -------------------------------------------------------------------------
    # 12.10 - FUNDING-RATIO RECONCILIATION
    # -------------------------------------------------------------------------


    # Keep funded DB plan rows with valid liabilities and assets.
    funded_rows = plan_overview.loc[

        plan_overview[
            "funded_db_product_flag"
        ]

        & pd.to_numeric(

            plan_overview[
                "actuarial_liability"
            ],

            errors="coerce"

        ).gt(
            0
        )

        & pd.to_numeric(

            plan_overview[
                "plan_assets"
            ],

            errors="coerce"

        ).notna()

    ].copy()


    # Start mismatch count.
    funding_ratio_mismatches = 0


    # Validate every funded plan.
    for row in funded_rows.itertuples(
        index=False
    ):


        # Recalculate expected funding ratio percentage.
        expected_ratio_pct = (

            float(
                row.plan_assets
            )

            / float(
                row.actuarial_liability
            )

            * 100.0
        )


        # Compare with visualization field.
        if abs(

            float(
                row.funding_ratio_pct
            )

            - expected_ratio_pct

        ) > 1e-8:


            funding_ratio_mismatches += 1


    # Store check.
    add_check(

        "Dashboard funding percentages reconcile",

        funding_ratio_mismatches,
    )


    # -------------------------------------------------------------------------
    # RETURN VALIDATION TABLE
    # -------------------------------------------------------------------------


    # Convert results into DataFrame.
    validation = pd.DataFrame(
        rows
    )


    # Store Pipeline version.
    validation[
        "pipeline_11_version"
    ] = P11_VERSION


    # Return.
    return validation


# =============================================================================
# P11 SECTION 13 - MAIN DASHBOARD DATA MART CONTROLLER
# =============================================================================


def run_pipeline_11(
    portfolio_results=None,
):
    """
    Run the Dashboard Data Mart and Visualization Layer.
    """

    # Print opening separator.
    print(
        "\n"
        + "=" * 76
    )


    # Print title.
    print(
        "PIPELINE 11 - "
        "DASHBOARD DATA MART AND VISUALIZATION LAYER"
    )


    # Print valuation date.
    print(
        f"Valuation date: "
        f"{VALUATION_DATE.date()}"
    )


    # Print version.
    print(
        f"Dashboard mart version: "
        f"{P11_VERSION}"
    )


    # Print separator.
    print(
        "=" * 76
    )


    # -------------------------------------------------------------------------
    # STEP 13.1 - RETRIEVE PIPELINE 10 OUTPUTS
    # -------------------------------------------------------------------------


    # Load validated integrated portfolio outputs.
    sources = p11_get_pipeline_10_sources(

        portfolio_results
    )


    # Extract company KPIs.
    company_kpis = sources[
        "company_kpis"
    ]


    # Extract product summary.
    product_summary = sources[
        "product_summary"
    ]


    # Extract plan summary.
    plan_summary = sources[
        "plan_summary"
    ]


    # Extract employee risk matrix.
    employee_risk_matrix = sources[
        "employee_risk_matrix"
    ]


    # Extract segment summary.
    segment_summary = sources[
        "segment_summary"
    ]


    # Extract Pipeline 10 validation.
    p10_validation = sources[
        "validation"
    ]


    # Extract governance.
    p10_governance = sources[
        "governance"
    ]


    # Extract source audit.
    source_audit = sources[
        "source_audit"
    ]


    # -------------------------------------------------------------------------
    # STEP 13.2 - EXECUTIVE KPI CARDS
    # -------------------------------------------------------------------------


    # Build KPI-card data.
    kpi_cards = build_dashboard_kpi_cards(

        company_kpis
    )


    # -------------------------------------------------------------------------
    # STEP 13.3 - PRODUCT OVERVIEW
    # -------------------------------------------------------------------------


    # Build product-level visualization table.
    product_overview = build_dashboard_product_overview(

        product_summary
    )


    # -------------------------------------------------------------------------
    # STEP 13.4 - PLAN OVERVIEW
    # -------------------------------------------------------------------------


    # Build plan-level dashboard table.
    plan_overview = build_dashboard_plan_overview(

        plan_summary
    )


    # -------------------------------------------------------------------------
    # STEP 13.5 - EMPLOYEE DRILL-DOWN
    # -------------------------------------------------------------------------


    # Build compact employee drill-down.
    employee_detail = build_dashboard_employee_detail(

        employee_risk_matrix
    )


    # -------------------------------------------------------------------------
    # STEP 13.6 - WORKFORCE CONCENTRATION
    # -------------------------------------------------------------------------


    # Build segment analytics.
    segment_risk = build_dashboard_segment_risk(

        segment_summary
    )


    # -------------------------------------------------------------------------
    # STEP 13.7 - GOVERNANCE VIEW
    # -------------------------------------------------------------------------


    # Prepare governance dashboard.
    dashboard_governance = build_dashboard_governance(

        p10_governance
    )


    # -------------------------------------------------------------------------
    # STEP 13.8 - VALIDATION VIEW
    # -------------------------------------------------------------------------


    # Prepare Pipeline 10 validation dashboard.
    dashboard_validation = build_dashboard_validation(

        p10_validation
    )


    # -------------------------------------------------------------------------
    # STEP 13.9 - DASHBOARD FILTERS
    # -------------------------------------------------------------------------


    # Build controlled filter catalogue.
    dashboard_filters = build_dashboard_filters(

        employee_detail
    )


    # -------------------------------------------------------------------------
    # STEP 13.10 - VISUALIZATION CATALOGUE
    # -------------------------------------------------------------------------


    # Build approved visual specification.
    visual_catalog = build_dashboard_visual_catalog()


    # -------------------------------------------------------------------------
    # STEP 13.11 - PIPELINE 11 VALIDATION
    # -------------------------------------------------------------------------


    # Validate visualization-layer reconciliation.
    p11_validation = build_pipeline_11_validation(

        company_kpis,

        kpi_cards,

        product_overview,

        plan_overview,

        employee_detail,

        segment_risk,

        dashboard_governance,

        dashboard_validation,
    )


    # Count true failures.
    validation_failures = int(

        p11_validation[
            "status"
        ].eq(
            "FAIL"
        ).sum()
    )


    # -------------------------------------------------------------------------
    # STEP 13.12 - BUILD DASHBOARD DATASET COLLECTION
    # -------------------------------------------------------------------------


    # Create mapping between output file and DataFrame.
    dashboard_tables = {

        "dashboard_kpi_cards.csv":
            kpi_cards,

        "dashboard_product_overview.csv":
            product_overview,

        "dashboard_plan_overview.csv":
            plan_overview,

        "dashboard_employee_detail.csv":
            employee_detail,

        "dashboard_segment_risk.csv":
            segment_risk,

        "dashboard_governance.csv":
            dashboard_governance,

        "dashboard_validation.csv":
            dashboard_validation,

        "dashboard_filters.csv":
            dashboard_filters,

        "dashboard_visual_catalog.csv":
            visual_catalog,
    }


    # -------------------------------------------------------------------------
    # STEP 13.13 - BUILD MANIFEST
    # -------------------------------------------------------------------------


    # Build dashboard dataset manifest.
    dashboard_manifest = build_dashboard_manifest(

        dashboard_tables
    )


    # -------------------------------------------------------------------------
    # STEP 13.14 - WRITE DASHBOARD-READY DATA
    # -------------------------------------------------------------------------


    # Save every dashboard dataset.
    for (
        file_name,
        dataframe,

    ) in dashboard_tables.items():


        # Write CSV.
        dataframe.to_csv(

            DASHBOARD_READY_DIR
            / file_name,

            index=False
        )


    # Save manifest.
    dashboard_manifest.to_csv(

        DASHBOARD_READY_DIR
        / "dashboard_manifest.csv",

        index=False
    )


    # -------------------------------------------------------------------------
    # STEP 13.15 - WRITE PIPELINE 11 AUDIT REPORTS
    # -------------------------------------------------------------------------


    # Save Pipeline 11 validation.
    p11_validation.to_csv(

        P11_OUTPUT_DIR
        / "pipeline_11_validation.csv",

        index=False
    )


    # Save source audit.
    source_audit.to_csv(

        P11_OUTPUT_DIR
        / "dashboard_source_audit.csv",

        index=False
    )


    # Save manifest in audit directory as well.
    dashboard_manifest.to_csv(

        P11_OUTPUT_DIR
        / "dashboard_manifest.csv",

        index=False
    )


    # -------------------------------------------------------------------------
    # STEP 13.16 - TERMINAL SUMMARY
    # -------------------------------------------------------------------------


    # Print dashboard mart summary.
    print(
        "\nDashboard Data Mart"
    )


    # KPI cards.
    print(

        f"  Executive KPI cards:                "
        f"{len(kpi_cards):,}"
    )


    # Products.
    print(

        f"  Product overview rows:              "
        f"{len(product_overview):,}"
    )


    # Plans.
    print(

        f"  Plan overview rows:                 "
        f"{len(plan_overview):,}"
    )


    # Employee drill-down.
    print(

        f"  Employee detail rows:               "
        f"{len(employee_detail):,}"
    )


    # Segment rows.
    print(

        f"  Segment concentration rows:         "
        f"{len(segment_risk):,}"
    )


    # Governance.
    print(

        f"  Governance rows:                    "
        f"{len(dashboard_governance):,}"
    )


    # Validation.
    print(

        f"  Pipeline 10 validation rows:        "
        f"{len(dashboard_validation):,}"
    )


    # Filters.
    print(

        f"  Dashboard filter values:            "
        f"{len(dashboard_filters):,}"
    )


    # Visual catalogue.
    print(

        f"  Approved dashboard visuals:         "
        f"{len(visual_catalog):,}"
    )


    # Pipeline 11 failures.
    print(

        f"\nPipeline 11 validation failures:       "
        f"{validation_failures}"
    )


    # Dashboard-ready directory.
    print(

        f"\nDashboard-ready data written to:\n"
        f"{DASHBOARD_READY_DIR}"
    )


    # Audit directory.
    print(

        f"\nPipeline 11 reports written to:\n"
        f"{P11_OUTPUT_DIR}"
    )


    # Completion statement.
    print(

        "\nPipeline 11 complete."
        "\nNo actuarial valuation formulas were recalculated."
        "\nPipeline 10 outputs were converted into dashboard-ready data."
        "\nHistorical GTI credibility pricing remains excluded from final KPIs."
        "\nThe data layer is ready for the Streamlit application.\n"
    )


    # -------------------------------------------------------------------------
    # STEP 13.17 - RETURN PIPELINE 11 RESULTS
    # -------------------------------------------------------------------------


    # Return dashboard objects for direct use by Streamlit if required.
    return {

        "kpi_cards":
            kpi_cards,

        "product_overview":
            product_overview,

        "plan_overview":
            plan_overview,

        "employee_detail":
            employee_detail,

        "segment_risk":
            segment_risk,

        "governance":
            dashboard_governance,

        "upstream_validation":
            dashboard_validation,

        "dashboard_filters":
            dashboard_filters,

        "visual_catalog":
            visual_catalog,

        "dashboard_manifest":
            dashboard_manifest,

        "pipeline_11_validation":
            p11_validation,

        "source_audit":
            source_audit,
    }


# =============================================================================
# RUN PIPELINE 11
# =============================================================================
#
# IMPORTANT:
#
# This execution block is deliberately included.
#
# It prevents the mistake where Pipeline 11 is defined successfully
# but never actually executed.
#
# Pipeline 11 first uses the Pipeline 10 in-memory result.
#
# If that result is unavailable later, the helper functions automatically
# reload the saved Pipeline 10 CSV outputs.
# =============================================================================


if __name__ == "__main__":


    # Run Dashboard Data Mart and Visualization Layer.
    dashboard_mart_results = run_pipeline_11(

        portfolio_results=globals().get(
            "portfolio_results"
        )
    )